import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Các tùy chọn điều khiển môi trường thực thi ACP để bật điều phối, chọn backend, giới hạn các tác nhân đích được phép và chọn cách biểu diễn lượt tương tác theo luồng.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Các tác nhân ACP được phép`},help:{"v1-f2mw0d-3a":`Danh sách các ID tác nhân đích ACP được phép dùng trong các phiên thực thi ACP. Để trống nghĩa là không áp dụng thêm giới hạn theo danh sách cho phép.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Backend ACP`},help:{"v1-1s1l6bz-2v":`ID backend mặc định của môi trường thực thi ACP (ví dụ: acpx). Phải khớp với một backend của plugin thực thi ACP đã đăng ký.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Tác nhân ACP mặc định`},help:{"v1-7donnu-2c":`ID tác nhân đích ACP dự phòng được dùng khi yêu cầu khởi tạo ACP không chỉ định đích cụ thể.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Bật điều phối ACP`},help:{"v1-1ug9t9m-3w":`Công tắc điều phối độc lập cho các lượt tương tác trong phiên ACP (mặc định: true). Đặt thành false để vẫn cho phép sử dụng các lệnh ACP nhưng chặn việc thực thi các lượt tương tác ACP.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`Bật ACP`},help:{"v1-1uonl1v-2a":`Công tắc tính năng ACP toàn cục. Giữ ở trạng thái tắt trừ khi môi trường thực thi và chính sách ACP đã được cấu hình.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Các backend dự phòng ACP`},help:{"v1-1wvdifq-5m":`Danh sách có thứ tự các ID backend ACP dự phòng được thử khi backend chính gặp lỗi UNAVAILABLE (ví dụ: giới hạn tốc độ / hết hạn ngạch). Mỗi mục phải khớp với một backend của plugin môi trường thực thi ACP đã đăng ký.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Lệnh cài đặt môi trường thực thi ACP`},help:{"v1-1jjuv9m-39":"Lệnh cài đặt/thiết lập tùy chọn dành cho người vận hành, được `/acp install` và `/acp doctor` hiển thị khi chưa có cấu hình kết nối backend ACP."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Luồng ACP`},help:{"v1-1bka5p-2v":`Các tùy chọn kiểm soát cách biểu diễn luồng ACP, gồm kích thước đoạn, khả năng hiển thị siêu dữ liệu và hành vi phân phối đã loại bỏ trùng lặp.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Chế độ phân phối luồng ACP`},help:{"v1-19gdmx1-3s":`Kiểu phân phối ACP: live truyền dần đầu ra đã được biểu diễn, final_only lưu đệm toàn bộ đầu ra ACP đã được biểu diễn cho đến khi có sự kiện kết thúc lượt.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Ẩn nội dung lặp lại trong luồng ACP`},help:{"v1-manh32-3d":`Khi là true (mặc định), ẩn các dòng biểu diễn trạng thái/công cụ ACP lặp lại trong một lượt, đồng thời giữ nguyên các sự kiện ACP thô.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Khả năng hiển thị thẻ trong luồng ACP`},help:{"v1-1ybhx22-34":`Các thiết lập ghi đè khả năng hiển thị theo từng sessionUpdate cho phần biểu diễn ACP (ví dụ: usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Tác tử`},help:{"v1-2rc4v8-55":`Gốc cấu hình môi trường thực thi tác tử. Các mục cùng cấp ở gốc quản lý hạ tầng và các giá trị mặc định dùng chung giữa các tác tử; agents.defaults quản lý hành vi vòng lặp tác tử; các mục tác tử có thể ghi đè một trong hai nhóm này nếu được hỗ trợ.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Mặc định của tác nhân`},help:{"v1-1af7k5b-5a":`Các thiết lập mặc định dùng chung được tác tử kế thừa, trừ khi bị ghi đè trong từng mục của agents.entries. Sử dụng các giá trị mặc định để bảo đảm hành vi cơ bản nhất quán và giảm cấu hình trùng lặp giữa các tác tử.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Đích kế thừa xác thực`},help:{"v1-2d16wl-2x":`Chủ sở hữu bảo đảm khả năng tương thích khi nâng cấp cho kho thông tin xác thực được kế thừa, cho đến khi thông tin xác thực được chuyển sang từng tác tử.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Chủ sở hữu nguồn kế thừa xác thực`},help:{"v1-1a1s7nm-4s":`Tác tử có kho thông tin xác thực cũ tiếp tục làm nguồn kế thừa sau khi dấu đánh dấu mặc định bị loại bỏ. Được ghi tự động trong quá trình nâng cấp khi chủ sở hữu trước đó không phải là main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Số ký tự khởi tạo tối đa`},help:{"v1-drlo3i-37":`Số ký tự tối đa của mỗi tệp khởi tạo trong không gian làm việc được chèn vào lời nhắc hệ thống trước khi bị cắt ngắn (mặc định: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Tổng số ký tự khởi tạo tối đa`},help:{"v1-1evwsjb-2c":`Tổng số ký tự tối đa của tất cả các tệp khởi tạo trong không gian làm việc được chèn vào (mặc định: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Nén gọn`},help:{"v1-1qxdwz8-5p":`Hành vi nén gọn khi ngữ cảnh gần đạt giới hạn token, bao gồm chiến lược và hành vi lưu bộ nhớ trước khi nén gọn. Sử dụng thiết lập này khi các phiên chạy dài cần duy trì tính liên tục ổn định trong cửa sổ ngữ cảnh hạn hẹp.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Tự động nén gọn tích hợp`},help:{"v1-1et7vwu-5l":`Bật tính năng tự động cô đọng chủ động tích hợp (mặc định: true). Đặt thành false để dừng cô đọng tích hợp theo ngưỡng, đồng thời vẫn giữ khả năng khôi phục khi tràn ngữ cảnh của OpenClaw, cô đọng trước khi xử lý và lệnh /compact thủ công.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Chính sách định danh khi cô đọng`},help:{"v1-hby01l-4l":`Chính sách bảo toàn định danh cho bản tóm tắt cô đọng: "strict" thêm hướng dẫn tích hợp về việc giữ nguyên các định danh không mang ý nghĩa rõ ràng vào đầu (mặc định), còn "off" tắt tiền tố này.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Số token gần đây được giữ lại khi cô đọng`},help:{"v1-tgysub-5h":`Số token tối thiểu được giữ lại từ cửa sổ hội thoại gần nhất khi cô đọng. Dùng giá trị cao hơn để bảo đảm tính liên tục của ngữ cảnh hiện tại và giá trị thấp hơn để giữ lại nhiều lịch sử cũ hơn.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Ngưỡng kích thước bản ghi hội thoại đang hoạt động để cô đọng`},help:{"v1-u715n1-90":`Ngưỡng byte kích hoạt cô đọng cục bộ thông thường trước khi xử lý khi cửa sổ bản ghi hội thoại mà mô hình thấy (kể từ lần cô đọng hoặc đặt lại gần nhất) đạt kích thước này (số byte hoặc chuỗi như "20mb"). Đặt thành 0 hoặc để trống để tắt. Đồng thời giới hạn bản ghi rollout gốc của Codex app-server; các luồng gốc quá lớn sẽ được khởi động lại từ đầu.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Lưu bộ nhớ trước khi cô đọng`},help:{"v1-18q0ve9-55":`Cài đặt lưu bộ nhớ trước khi cô đọng, cho phép tác tử ghi vào bộ nhớ trước khi cô đọng sâu. Nên bật cho các phiên dài để ngữ cảnh quan trọng được lưu bền vững trước khi cắt giảm mạnh.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Bật lưu bộ nhớ trước khi thu gọn`},help:{"v1-9xllgp-5o":`Bật lưu bộ nhớ trước khi thu gọn, trước khi môi trường thực thi cắt giảm lịch sử mạnh hơn lúc gần đạt giới hạn token. Nên giữ bật trừ khi bạn chủ động tắt các tác động đến bộ nhớ trong môi trường hạn chế tài nguyên.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Ngưỡng kích thước bản ghi hội thoại để lưu bộ nhớ trước khi thu gọn`},help:{"v1-1rzov1e-93":`Buộc lưu bộ nhớ trước khi thu gọn khi phần bản ghi hội thoại mà mô hình nhìn thấy đạt ngưỡng này (tính bằng byte hoặc chuỗi như "2mb"). Sau khi thu gọn, phần này bao gồm đoạn cuối được giữ lại và các lượt tiếp theo, thay vì lịch sử đã bị loại bỏ. Dùng thiết lập này để tránh treo trong các phiên dài ngay cả khi bộ đếm token chưa được cập nhật; đặt thành 0 để tắt.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Ghi đè mô hình lưu bộ nhớ trước khi thu gọn`},help:{"v1-1r3ctyu-7w":`Thiết lập ghi đè nhà cung cấp/mô hình tùy chọn, chỉ dùng cho các lượt lưu bộ nhớ trước khi thu gọn. Đặt thành một mô hình cục bộ như ollama/qwen3:8b nếu muốn tránh dùng mô hình trả phí của phiên hiện tại để trích xuất bộ nhớ lưu trữ lâu dài. Thiết lập ghi đè chỉ dùng đúng mô hình được chỉ định và không kế thừa chuỗi mô hình dự phòng của mô hình đang hoạt động.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Ngưỡng mềm để lưu bộ nhớ trước khi thu gọn`},help:{"v1-1dqo2l1-5c":`Khoảng cách đến ngưỡng thu gọn (tính bằng token) để kích hoạt lưu bộ nhớ trước khi thu gọn. Dùng ngưỡng kích hoạt sớm hơn để lưu trữ an toàn hơn, hoặc ngưỡng sát hơn để giảm tần suất lưu.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Kiểm tra trước khi nén ngữ cảnh giữa lượt`},help:{"v1-am6gbh-6x":`Bước kiểm tra trước tùy chọn trong vòng lặp công cụ OpenClaw nhúng, giúp phát hiện áp lực ngữ cảnh sau khi kết quả công cụ được thêm vào và trước lần gọi mô hình tiếp theo. Khi được bật, OpenClaw sử dụng lại cơ chế khôi phục của bước kiểm tra trước hiện có để cắt ngắn kết quả công cụ hoặc nén ngữ cảnh trước khi thử lại.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Bật kiểm tra trước khi nén ngữ cảnh giữa lượt`},help:{"v1-engbwe-5u":`Bật các bước kiểm tra áp lực ngữ cảnh có cấu trúc giữa lượt cho các vòng lặp công cụ OpenClaw nhúng. Mặc định: false. Chỉ bật nếu các phiên dài sử dụng nhiều công cụ bị tràn ngữ cảnh trước khi quy trình nén ngữ cảnh thông thường vào cuối lượt có thể chạy.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Chế độ nén ngữ cảnh`},help:{"v1-1unahwc-76":`Chế độ chiến lược nén ngữ cảnh: "safeguard" (mặc định được áp dụng khi chưa thiết lập) sử dụng các biện pháp bảo vệ để giữ lại ngữ cảnh gần đây, còn "default" sử dụng phương pháp tóm tắt cơ bản mà không có các biện pháp này. Chỉ đặt thành "default" nếu việc tóm tắt theo chế độ safeguard gây ra vấn đề với nhà cung cấp của bạn.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Ghi đè mô hình nén ngữ cảnh`},help:{"v1-cfeys9-6q":`Giá trị provider/model tùy chọn hoặc bí danh đơn đã cấu hình, chỉ dùng để tóm tắt khi nén ngữ cảnh. Bí danh đơn được phân giải trước khi gửi yêu cầu; ID mô hình nguyên văn đã cấu hình được ưu tiên nếu trùng với bí danh. Để trống để tiếp tục sử dụng mô hình chính của tác nhân.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Thông báo cho người dùng khi nén ngữ cảnh`},help:{"v1-lvymm8-bv":`Khi bật, gửi thông báo ngắn về việc bảo trì ngữ cảnh cho người dùng: khi quá trình thu gọn bắt đầu và hoàn tất (ví dụ: '🧹 Đang thu gọn ngữ cảnh...' và '🧹 Đã thu gọn xong'), và khi không thể tiếp tục lưu bộ nhớ trước khi thu gọn, khiến quá trình trả lời tiếp diễn trong trạng thái suy giảm (ví dụ: '⚠️ Tạm thời không thể bảo trì bộ nhớ; đang tiếp tục trả lời bạn.'). Mặc định tắt để việc bảo trì ngữ cảnh diễn ra âm thầm và không gây gián đoạn.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Các mục ngữ cảnh sau khi thu gọn`},help:{"v1-1n0ln2u-5f":`Tên các mục H2/H3 trong AGENTS.md được chọn để chèn lại sau khi thu gọn. Để trống hoặc đặt [] để tắt tính năng chèn lại. Đặt rõ ["Session Startup", "Red Lines"] để bật cặp mục mặc định trước đây.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Đồng bộ chỉ mục sau khi thu gọn`},help:{"v1-ekpjeq-6l":`Kiểm soát chế độ lập lại chỉ mục bộ nhớ phiên sau khi thu gọn: "off", "async" hoặc "await" (mặc định: "async"). Dùng "await" để đảm bảo dữ liệu cập nhật nhất, "async" để giảm độ trễ khi thu gọn và chỉ dùng "off" khi việc đồng bộ bộ nhớ phiên được xử lý ở nơi khác.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Nhà cung cấp dịch vụ thu gọn`},help:{"v1-kiwk91-86":`ID của plugin cung cấp dịch vụ thu gọn đã đăng ký, dùng để tóm tắt. Khi được đặt và nhà cung cấp đã đăng ký, phương thức summarize() của nhà cung cấp sẽ được gọi thay cho quy trình summarizeInStages tích hợp sẵn. Quay về dùng chức năng tích hợp sẵn nếu nhà cung cấp gặp lỗi. Để trống để dùng chức năng tóm tắt mặc định tích hợp sẵn.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Bảo vệ chất lượng thu gọn`},help:{"v1-u9ognp-4k":`Cài đặt thử lại kiểm tra chất lượng cho bản tóm tắt khi thu gọn ở chế độ bảo vệ. Chế độ bảo vệ bật tính năng này theo mặc định; đặt enabled: false để bỏ qua việc kiểm tra và tạo lại bản tóm tắt.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Bật bảo vệ chất lượng thu gọn`},help:{"v1-1xk2vt3-36":`Bật kiểm tra chất lượng bản tóm tắt và thử tạo lại khi thu gọn ở chế độ bảo vệ. Mặc định: true trong chế độ bảo vệ.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Số lần thử lại tối đa để bảo vệ chất lượng thu gọn`},help:{"v1-n7l46y-3y":`Số lần thử tạo lại tối đa sau khi bản tóm tắt ở chế độ bảo vệ không đạt kiểm tra chất lượng. Dùng giá trị nhỏ để giới hạn độ trễ và chi phí token phát sinh.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Giữ lại các lượt gần đây khi thu gọn`},help:{"v1-y34ihi-5k":`Số lượt trao đổi gần nhất của người dùng/trợ lý được giữ nguyên văn, không đưa vào phần tóm tắt ở chế độ bảo vệ (mặc định: 3). Tăng giá trị này để giữ chính xác ngữ cảnh hội thoại gần đây, hoặc giảm để tối đa hóa mức tiết kiệm nhờ thu gọn.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Mức độ suy nghĩ khi thu gọn`},help:{"v1-1vafgaw-g1":`Mức suy luận chỉ dùng cho các bản tóm tắt thu gọn tích hợp trong OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" hoặc "inherit". Mặc định theo tùy chọn thu gọn của nhà cung cấp, nếu không có thì dùng "low"; Ollama cục bộ gốc ưu tiên "off". Đặt thành "inherit" để dùng lại mức của phiên. Thiết lập tường minh sẽ ghi đè giá trị mặc định của nhà cung cấp, và mức được chọn sẽ được giới hạn theo mô hình thu gọn/môi trường chạy thực tế. Cơ chế thu gọn gốc của Codex app-server bỏ qua thiết lập này vì yêu cầu thu gọn của nó không hỗ trợ ghi đè mức suy luận cho từng thao tác, và OpenClaw sẽ ghi cảnh báo vào nhật ký.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Thời gian chờ thu gọn (giây)`},help:{"v1-2bhn29-7m":`Khoảng thời gian an toàn tính bằng giây cho mỗi yêu cầu đến mô hình thu gọn tích hợp (mặc định: 180). Quá trình thu gọn nhiều giai đoạn tính lại khoảng thời gian này khi mỗi yêu cầu tuần tự bắt đầu, nên toàn bộ quá trình có thể kéo dài hơn; quá trình thu gọn do plugin đảm nhiệm chỉ nhận một khoảng thời gian cho toàn bộ thao tác.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Chèn ngữ cảnh`},help:{"v1-u18x0-7u":`Kiểm soát việc chèn tệp khởi tạo không gian làm việc trong môi trường thực thi nhúng: "always" sử dụng cách chèn thông thường (mặc định), "continuation-skip" bỏ qua các lượt tiếp nối đủ điều kiện sau một lượt khởi tạo đầy đủ đã được ghi nhận, còn "never" tắt việc chèn. Không kiểm soát việc chuẩn bị lời nhắc qua CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Giới hạn ngữ cảnh mặc định`},help:{"v1-1coeez8-5d":`Các mức ngân sách mặc định theo ngữ cảnh của từng tác nhân, tập trung vào một số đoạn trích có dung lượng lớn và các khối lời nhắc được chèn. Dùng thiết lập này để điều chỉnh giới hạn kích thước đọc/chèn mà không mở lại bất kỳ luồng gọi không giới hạn nào.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Số ký tự tối đa mặc định của memory_get`},help:{"v1-1qb40qv-4v":`Số ký tự tối đa mặc định mà memory_get trả về trước khi thêm siêu dữ liệu cắt ngắn và thông báo tiếp nối. Tăng giá trị này để có các đoạn trích dài gần bằng trước đây, nhưng vẫn cần đặt giới hạn.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Số ký tự tối đa mặc định sau khi nén`},help:{"v1-64qo8g-5r":`Số ký tự tối đa mặc định được giữ lại từ AGENTS.md khi chèn nội dung làm mới ngữ cảnh sau khi nén. Giảm giá trị này để giảm chi phí khôi phục sau khi nén, hoặc tăng giá trị cho các tác nhân phụ thuộc vào hướng dẫn khởi động dài hơn.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Thư mục làm việc`},help:{"v1-1y8wlxn-6a":`Thư mục làm việc cho các lượt chạy trả lời của tác nhân, tách biệt với các tệp khởi tạo không gian làm việc và bộ nhớ. cwd riêng của tác nhân và cwd được thiết lập khi tạo phiên được ưu tiên. Hỗ trợ ~ và đường dẫn tương đối; cwd riêng biệt yêu cầu lượt chạy bên ngoài môi trường cách ly.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Mô hình ra quyết định`},help:{"v1-7nd7ze-64":`Nhà cung cấp/mô hình tùy chọn cho các lựa chọn có kiểu dữ liệu, điểm số và xác suất boolean. Không đặt hoặc để trống sẽ tắt các lệnh gọi ra quyết định. Các plugin hỗ trợ gửi dữ liệu làm căn cứ cho tác vụ trong phạm vi giới hạn đến nhà cung cấp này; các mô hình trò chuyện và tiện ích không thay đổi.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`OpenClaw nhúng`},help:{"v1-1keek32-3k":`Các tùy chọn tăng cường bảo mật cho trình chạy OpenClaw nhúng, kiểm soát cách tin cậy và áp dụng các thiết lập tác nhân cục bộ trong không gian làm việc vào các phiên OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Chuyển sang dự phòng khi bị từ chối do chính sách an ninh mạng`},help:{"v1-xvv6wl-2r":`Tự động chuyển lên Daybreak đối với các yêu cầu bị OpenAI từ chối do chính sách an ninh mạng trong môi trường thực thi nhúng mà có thể gửi lại an toàn.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Thời gian chờ chuyển sang dự phòng khi bị từ chối do chính sách an ninh mạng`},help:{"v1-16smtrl-25":`Khoảng thời gian bỏ qua một đích xử lý cấp cao hơn không khả dụng trong phiên hiện tại.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Chế độ chuyển sang dự phòng khi bị từ chối do chính sách an ninh mạng`},help:{"v1-rzsd2b-2h":`Bật tính năng tự động chuyển lên cấp xử lý cao hơn ("auto", mặc định) hoặc dừng xử lý khi nhà cung cấp từ chối ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Mô hình dự phòng khi bị từ chối do chính sách an ninh mạng`},help:{"v1-1aaj8nn-1t":`Nhà cung cấp/mô hình đích được dùng để tự động chuyển lên cấp xử lý cao hơn khi bị từ chối do chính sách an ninh mạng.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Hợp đồng thực thi OpenClaw nhúng`},help:{"v1-1fch2ig-66":`Hợp đồng thực thi OpenClaw nhúng: "default" giữ nguyên hành vi tiêu chuẩn của trình chạy, còn "strict-agentic" bật tính năng theo dõi kế hoạch có cấu trúc và khôi phục lượt mà người dùng không nhìn thấy cho các lượt chạy được hỗ trợ thuộc dòng GPT-5 của OpenAI/OpenAI Codex.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Chính sách thiết lập dự án OpenClaw nhúng`},help:{"v1-fdyy04-65":'Cách OpenClaw nhúng xử lý `.openclaw/settings.json` cục bộ trong không gian làm việc: "sanitize" (mặc định) loại bỏ shellPath/shellCommandPrefix, "ignore" vô hiệu hóa hoàn toàn cài đặt dự án, còn "trusted" áp dụng nguyên trạng cài đặt dự án.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Các cờ thử nghiệm của tác nhân`},help:{"v1-cvv5cl-2w":`Các cờ thử nghiệm mặc định cho tác nhân. Hãy tắt các cờ này trừ khi bạn chủ động thử nghiệm một tính năng xem trước.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Bật chế độ mô hình cục bộ tinh gọn (Thử nghiệm)`},help:{"v1-gj06u6-7b":`Thiết lập ghi đè để khắc phục sự cố nâng cao, hạn chế các công cụ tùy chọn như browser, automations và message. Mặc định tắt; các môi trường chạy cục bộ được hỗ trợ tự động sử dụng Tool Search mà không có hạn chế này. Các quyền cho phép công cụ được chỉ định rõ ràng và các công cụ gửi bắt buộc vẫn được giữ nguyên.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Chế độ nhanh mặc định của tác nhân`},help:{"v1-zv4y98-2z":`Chính sách chế độ nhanh mặc định cho vòng lặp tác nhân ("auto", true hoặc false). Các mục cấu hình tác nhân riêng lẻ sẽ ghi đè chính sách này.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Tác nhân nhịp tim`},help:{"v1-1jynxej-3w":`Tác nhân phụ trách các lần chạy nhịp tim nền khi không có cấu hình nhịp tim riêng cho từng tác nhân. Để trống để giữ nguyên định tuyến mặc định đã cấu hình.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Chính sách gửi trực tiếp của nhịp tim`},help:{"v1-nhyxa9-41":`Kiểm soát việc nhịp tim có được gửi tới các cuộc trò chuyện trực tiếp/tin nhắn riêng (DM) hay không: "allow" (mặc định) cho phép gửi DM, còn "block" ngăn gửi tới các đích trực tiếp.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Thời gian chờ nhịp kiểm tra (giây)`},help:{"v1-1se21py-5f":`Thời gian tối đa tính bằng giây cho một lượt tác nhân chạy theo nhịp kiểm tra trước khi bị hủy. Để trống để dùng agents.defaults.timeoutSeconds nếu đã được đặt; nếu không, dùng chu kỳ nhịp kiểm tra nhưng không quá 600 giây.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Độ trễ mô phỏng con người tối đa (ms)`},help:{"v1-vnmvli-1m":`Độ trễ tối đa tính bằng ms cho humanDelay tùy chỉnh (mặc định: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Độ trễ mô phỏng con người tối thiểu (ms)`},help:{"v1-5nrtr5-1l":`Độ trễ tối thiểu tính bằng ms cho humanDelay tùy chỉnh (mặc định: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Chế độ trễ mô phỏng con người`},help:{"v1-k7hyg3-1n":`Kiểu độ trễ cho các phản hồi theo khối ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Kích thước ảnh tối đa (px)`},help:{"v1-vju8x-2u":`Độ dài cạnh ảnh tối đa tính bằng pixel khi làm sạch dữ liệu ảnh trong bản ghi hội thoại/kết quả công cụ (mặc định: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Các mô hình ảnh dự phòng`},help:{"v1-1kgx5i9-1b":`Các mô hình ảnh dự phòng theo thứ tự (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Mô hình ảnh`},help:{"v1-dstqyh-2c":`Mô hình ảnh tùy chọn (provider/model) được dùng khi mô hình chính không hỗ trợ đầu vào là ảnh.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Chất lượng ảnh`},help:{"v1-1uyxc5s-6u":`Tùy chọn nén nội dung đa phương tiện cho công cụ hình ảnh: "auto" điều chỉnh theo giới hạn của nhà cung cấp/mô hình và số lượng hình ảnh, "efficient" tiết kiệm token và byte, "balanced" giữ mức cân bằng hiện tại, còn "high" giữ lại nhiều chi tiết hơn cho ảnh chụp màn hình và ảnh tài liệu.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Các mô hình tạo hình ảnh dự phòng`},help:{"v1-oljfk4-1m":`Các mô hình tạo hình ảnh dự phòng theo thứ tự (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Mô hình tạo hình ảnh`},help:{"v1-g4yw0h-2o":`Mô hình tạo hình ảnh tùy chọn (provider/model) được tính năng tạo hình ảnh dùng chung sử dụng.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Thời gian chờ tạo hình ảnh (ms)`},help:{"v1-9yesfj-31":`Thời gian chờ mặc định cho yêu cầu gửi đến nhà cung cấp, tính bằng mili giây, đối với các lệnh gọi image_generate. timeoutMs của từng lệnh gọi sẽ ghi đè giá trị này.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Các mô hình tạo nhạc dự phòng`},help:{"v1-wyg9xe-1m":`Các mô hình tạo nhạc dự phòng theo thứ tự (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Mô hình tạo nhạc`},help:{"v1-xs1e2h-2o":`Mô hình tạo nhạc tùy chọn (provider/model) được tính năng tạo nhạc dùng chung sử dụng.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Các mô hình tạo video dự phòng`},help:{"v1-wpbf1e-1m":`Các mô hình tạo video dự phòng theo thứ tự (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Mô hình tạo video`},help:{"v1-hfmlbl-2o":`Mô hình tạo video tùy chọn (provider/model) được chức năng tạo video dùng chung sử dụng.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Thời gian chờ tạo video (ms)`},help:{"v1-1bqj80s-4i":`Thời gian chờ mặc định cho yêu cầu gửi đến nhà cung cấp, tính bằng mili giây, đối với các lệnh gọi video_generate. timeoutMs của từng lệnh gọi ghi đè giá trị này, và giá trị này ghi đè các giá trị mặc định do nhà cung cấp đặt.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Các mô hình dự phòng`},help:{"v1-t4djq2-24":`Các mô hình dự phòng theo thứ tự (provider/model). Được sử dụng khi mô hình chính gặp lỗi.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Mô hình chính`},help:{"v1-1i8a1v4-v":`Mô hình chính (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Chính sách mô hình`},help:{"v1-z0txb7-2e":`Chính sách cụ thể cho việc ghi đè mô hình. Bỏ qua chính sách này hoặc để trống allow để cho phép mọi mô hình.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Các mô hình được phép`},help:{"v1-1fqace-3x":`Các tham chiếu mô hình được phép dùng để ghi đè. Chấp nhận bí danh, tham chiếu đầy đủ dạng "provider/model" và ký tự đại diện cho nhà cung cấp như "openai/*". Để trống để cho phép mọi mô hình.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Mô hình`},help:{"v1-13cvq23-4i":`Danh mục mô hình đã cấu hình và các thiết lập cho từng mô hình. Các mục cung cấp bí danh, tham số, siêu dữ liệu thời gian chạy và các thiết lập ghi đè cho Code Mode; chúng không hạn chế việc ghi đè mô hình.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Môi trường thực thi mô hình của tác nhân mặc định`},help:{"v1-6km9kx-41":`Chính sách môi trường thực thi tùy chọn theo từng mô hình cho tác nhân mặc định. Dùng thiết lập này cho các ngoại lệ về môi trường thực thi dành riêng cho mô hình, thay vì đặt môi trường thực thi cho toàn bộ tác nhân.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`ID môi trường thực thi mô hình của tác nhân mặc định`},help:{"v1-1co96w7-4a":`ID môi trường thực thi mô hình của tác nhân mặc định: "openclaw", "auto", ID bộ điều phối plugin đã đăng ký như "codex", hoặc bí danh backend CLI được hỗ trợ như "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Chế độ mã`},help:{"v1-rsdl5o-6x":`Chế độ lập trình OpenClaw cho đúng nhà cung cấp/mô hình này: Bật buộc kích hoạt chế độ này, Tắt vô hiệu hóa chế độ này, còn Mặc định kế thừa tools.codeMode.enabled. Các thiết lập kích hoạt riêng của tác nhân được ưu tiên. Thiết lập này không thay đổi môi trường thực thi đã chọn hoặc chế độ lập trình gốc của Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Phạm vi lựa chọn mô hình`},help:{"v1-sj8owq-bl":`Phạm vi áp dụng cho các lệnh trò chuyện và cập nhật mô hình phiên của Gateway khi không chỉ định phạm vi rõ ràng: "session" (mặc định) chỉ thay đổi phiên hiện tại, "agent" còn cập nhật mô hình chính của tác nhân đó, và "global" còn cập nhật mô hình dự phòng dùng chung agents.defaults.model. Các cờ chỉ định phạm vi rõ ràng được ưu tiên; việc ghi giá trị mặc định trong cấu hình yêu cầu quyền chủ sở hữu/quản trị viên. Bộ chọn qua callback của Telegram và TUI cục bộ nhúng vẫn chỉ áp dụng cho phiên.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Kích thước PDF tối đa (MB)`},help:{"v1-1uig1dr-1u":`Kích thước tệp PDF tối đa tính bằng megabyte cho công cụ PDF (mặc định: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Số trang PDF tối đa`},help:{"v1-11na7hp-1y":`Số trang PDF tối đa mà công cụ PDF xử lý (mặc định: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Các mô hình PDF dự phòng`},help:{"v1-89ebd8-19":`Các mô hình PDF dự phòng theo thứ tự (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Mô hình PDF`},help:{"v1-2ktkxt-2y":`Mô hình PDF tùy chọn (provider/model) cho công cụ phân tích PDF. Mặc định dùng imageModel, sau đó là mô hình của phiên.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Thư mục gốc kho mã`},help:{"v1-j3sh74-2h":`Thư mục gốc kho mã tùy chọn, hiển thị trong dòng thông tin thời gian chạy của lời nhắc hệ thống (ghi đè kết quả tự động phát hiện).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Dải cổng nguồn CDP của trình duyệt trong môi trường cô lập`},help:{"v1-1jkowdc-2b":`Danh sách CIDR được phép tùy chọn cho lưu lượng CDP đi vào tại biên container (ví dụ: 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Mạng trình duyệt trong môi trường cô lập`},help:{"v1-8m74ud-5w":`Mạng Docker cho các container trình duyệt trong môi trường cô lập (mặc định: openclaw-sandbox-browser). Dùng mạng mặc định chuyên dụng hoặc mạng cầu nối tùy chỉnh; không hỗ trợ "none" vì việc điều khiển trình duyệt yêu cầu các cổng CDP được công bố.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Cho phép Docker trong môi trường cô lập tham gia không gian tên container`},help:{"v1-qm39de-4c":`Tùy chọn ghi đè khẩn cấp NGUY HIỂM, cho phép chế độ mạng Docker container:<id> trong môi trường cô lập. Thao tác này tham gia không gian tên của container khác và làm suy yếu khả năng cách ly của môi trường.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU Docker trong môi trường cô lập`},help:{"v1-jj0yhw-4k":`Giá trị tùy chọn để chuyển tiếp GPU cho Docker, được truyền vào --gpus, ví dụ "all" hoặc "device=GPU-uuid". Yêu cầu môi trường thực thi tương thích trên máy chủ, chẳng hạn như NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Đích kho lưu trữ phiên kiểu cũ`},help:{"v1-1xkej6i-2g":`Chủ sở hữu phục vụ khả năng tương thích khi nâng cấp cho các bản ghi main-agent đã ngừng sử dụng và các kho lưu trữ phiên kiểu cũ cố định.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Chủ sở hữu kho lưu trữ phiên kiểu cũ`},help:{"v1-ommm7e-5w":`Tác nhân sở hữu các bản ghi main-agent đã ngừng sử dụng hoặc các bản ghi không có phạm vi trong kho lưu trữ phiên kiểu cũ cố định sau khi loại bỏ dấu đánh dấu mặc định. Được ghi tự động trong quá trình nâng cấp khi chủ sở hữu trước đó không phải là main hoặc tác nhân duy nhất.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Danh sách cho phép kỹ năng mặc định tùy chọn, được kế thừa bởi các tác nhân không khai báo agents.entries.*.skills. Bỏ qua để không giới hạn kỹ năng, đặt [] để các tác nhân kế thừa không có kỹ năng nào, và lưu ý rằng agents.entries.*.skills được khai báo tường minh sẽ thay thế giá trị mặc định này thay vì hợp nhất với nó.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Bỏ qua việc tạo tệp khởi tạo không gian làm việc`},help:{"v1-kbstgw-5v":`Bỏ qua việc tự động tạo các tệp khởi tạo không gian làm việc, không bỏ qua việc chèn các tệp hiện có. Với môi trường thực thi nhúng, đặt agents.defaults.contextInjection thành "never" để tắt việc chèn, trừ khi có thiết lập ghi đè cho từng tác nhân.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Các tệp khởi tạo tùy chọn bị bỏ qua`},help:{"v1-1j2z4yj-4c":`Các tệp khởi tạo tùy chọn không nên được tạo trong không gian làm việc của tác nhân. Giá trị hợp lệ: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md được chấp nhận nhưng không có tác dụng).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Ngữ cảnh khởi động`},help:{"v1-1ugsihy-5o":`Phần mở đầu lượt đầu tiên do môi trường thực thi quản lý cho các lệnh "/new" và "/reset" không kèm nội dung. Dùng tùy chọn này để kiểm soát việc tải sẵn các tệp bộ nhớ hằng ngày gần đây vào lời nhắc đầu tiên, thay vì yêu cầu mô hình quyết định cần đọc gì.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Áp dụng ngữ cảnh khởi động cho`},help:{"v1-wav4a5-36":`Chọn các lệnh đặt lại không kèm nội dung sẽ nhận ngữ cảnh khởi động: gồm "new", "reset" hoặc cả hai (mặc định: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Số ngày bộ nhớ hằng ngày trong ngữ cảnh khởi động`},help:{"v1-4i5xcm-3p":`Số tệp bộ nhớ theo ngày cần tải, tính ngược từ hôm nay theo múi giờ người dùng đã cấu hình (mặc định: 2 cho hôm nay + hôm qua).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Bật ngữ cảnh khởi động`},help:{"v1-1d5vz2u-4i":`Bật phần mở đầu ngữ cảnh khởi động cho các lần đặt lại phiên không kèm nội dung (mặc định: true). Tắt tùy chọn này để quay về chế độ chỉ dùng lời nhắc, không tải bộ nhớ hằng ngày qua môi trường thực thi.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Số byte tối đa mỗi tệp trong ngữ cảnh khởi động`},help:{"v1-11cbian-41":`Số byte tối đa được phép cho mỗi tệp bộ nhớ hằng ngày khi tạo ngữ cảnh khởi động (mặc định: 16384). Các tệp vượt quá giới hạn đọc an toàn theo ranh giới này sẽ bị bỏ qua.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Số ký tự tối đa mỗi tệp trong ngữ cảnh khởi động`},help:{"v1-10z53s-2u":`Số ký tự tối đa được giữ lại từ mỗi tệp bộ nhớ hằng ngày đã tải trong phần mở đầu khởi động (mặc định: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Tổng số ký tự tối đa của ngữ cảnh khởi động`},help:{"v1-sf676u-54":`Tổng số ký tự tối đa được giữ lại trong tất cả các tệp bộ nhớ hằng ngày đã tải vào phần mở đầu khi khởi động (mặc định: 2800). Khi đạt giới hạn này, nội dung từ các tệp bổ sung sẽ bị cắt khỏi phần mở đầu.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Chế độ ủy quyền cho tác nhân phụ`},help:{"v1-pqewbk-5o":`Mức độ yêu cầu ủy quyền cho tác nhân phụ, chỉ thông qua lời nhắc. Mặc định là "prefer" trong phiên chính của mỗi tác nhân và "suggest" ở các phiên khác; "prefer" chỉ thị mạnh mẽ cho tác nhân ủy quyền công việc không đơn giản qua sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Đích của tác nhân hệ thống`},help:{"v1-1wwimo9-34":`Cài đặt đích cho hoạt động suy luận nền của tác nhân hệ thống OpenClaw và Custodian, cùng một số thao tác đọc không giới hạn phạm vi của người vận hành.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Chủ sở hữu tác nhân hệ thống`},help:{"v1-15rvt92-8c":`Tác nhân sở hữu mô hình và thông tin xác thực dùng cho các lượt tham vấn nền của tác nhân hệ thống và Custodian. Cũng được dùng khi models.list, models.authStatus, skills.status, doctor.memory.status hoặc lệnh CLI infer xác định mô hình hay trạng thái xác thực thuộc tác nhân không chỉ định agentId hoặc --agent; agentId được chỉ định rõ trong yêu cầu luôn được ưu tiên.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Khoảng thời gian cập nhật trạng thái đang nhập (giây)`},help:{"v1-1y701ox-42":`Điều khiển chu kỳ duy trì chỉ báo đang nhập, tính bằng giây, cho mọi tác nhân. Tăng giá trị này để giảm tần suất cập nhật trên tất cả các kênh hỗ trợ chỉ báo đang nhập.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Chế độ chỉ báo đang nhập`},help:{"v1-m2hvpw-3m":`Kiểm soát thời điểm bắt đầu hiển thị trạng thái đang nhập của tác nhân: "never", "instant", "thinking" hoặc "message". typingMode của từng tác nhân sẽ ghi đè giá trị mặc định này.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Mô hình tiện ích`},help:{"v1-1wg7h1a-7s":`Mô hình có chi phí thấp hơn, không bắt buộc (provider/model hoặc bí danh), dùng cho các tác vụ nội bộ ngắn như tạo tiêu đề và mô tả tiến độ. Nếu không được đặt, sẽ dùng mô hình nhỏ do nhà cung cấp chính khai báo khi có (nếu không thì dùng mô hình chính); đặt thành chuỗi rỗng để tắt định tuyến tác vụ tiện ích.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Các mô hình giọng nói dự phòng`},help:{"v1-faazv4-1b":`Các mô hình giọng nói dự phòng theo thứ tự ưu tiên (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Mô hình giọng nói`},help:{"v1-1yeh3h4-2t":`Mô hình giọng nói không bắt buộc (provider/model), dùng cho các chức năng phát giọng nói, chuyển lời nói thành văn bản và giọng nói thời gian thực.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Thời gian chờ giọng nói (ms)`},help:{"v1-1sbergs-32":`Thời gian chờ mặc định của yêu cầu gửi đến nhà cung cấp, tính bằng mili giây, cho các thao tác với mô hình giọng nói khi bên gọi hỗ trợ thời gian chờ.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Không gian làm việc`},help:{"v1-1lssx8l-5w":`Không gian làm việc mặc định của tác nhân dành cho các tệp khởi tạo và bộ nhớ. Cũng được dùng làm thư mục làm việc khi agents.defaults.cwd chưa được đặt. Hãy đặt rõ giá trị này khi chạy thông qua các trình bao để việc phân giải đường dẫn luôn nhất quán.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Danh sách tác nhân`},help:{"v1-yurood-5l":`Danh sách tường minh các tác nhân đã cấu hình, gồm ID và các thiết lập ghi đè không bắt buộc cho mô hình, công cụ, danh tính và không gian làm việc. Giữ ID ổn định theo thời gian để các liên kết, phê duyệt và định tuyến phiên luôn nhất quán.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Môi trường thực thi tác tử kiểu cũ`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID môi trường thực thi tác tử kiểu cũ`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Số ký tự khởi tạo tối đa của tác tử`},help:{"v1-rsf1es-4j":`Thiết lập ghi đè riêng cho từng tác tử về số ký tự tối đa của mỗi tệp khởi tạo trong không gian làm việc được chèn vào lời nhắc hệ thống của tác tử này. Bỏ qua để kế thừa agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Tổng số ký tự khởi tạo tối đa của tác tử`},help:{"v1-1bal68p-4y":`Thiết lập ghi đè riêng cho từng tác tử về tổng số ký tự tối đa của tất cả các tệp khởi tạo trong không gian làm việc được chèn vào lời nhắc hệ thống của tác tử này. Bỏ qua để kế thừa agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Chèn ngữ cảnh cho tác tử`},help:{"v1-1j68ys8-50":`Thiết lập ghi đè cho từng tác nhân đối với việc chèn tệp khởi tạo của không gian làm việc trong môi trường thực thi nhúng. Bỏ qua để kế thừa agents.defaults.contextInjection. Không kiểm soát việc chuẩn bị lời nhắc dựa trên CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Giới hạn ngữ cảnh của tác tử`},help:{"v1-f1qxq8-3c":`Các thiết lập ghi đè tùy chọn riêng cho từng tác tử đối với các tham số điều chỉnh dung lượng ngữ cảnh trọng tâm. Các trường bị bỏ qua sẽ kế thừa agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Số ký tự memory_get tối đa của tác tử`},help:{"v1-12hlmsv-1v":`Thiết lập ghi đè riêng cho từng tác tử về giới hạn số ký tự tối đa mặc định của memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Số ký tự tối đa sau khi thu gọn của tác tử`},help:{"v1-15s0npd-1w":`Ghi đè giới hạn trích đoạn AGENTS.md sau khi thu gọn cho từng tác nhân.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Thư mục làm việc của tác nhân`},help:{"v1-mv43ak-6a":`Thư mục làm việc cho các lượt chạy trả lời của tác nhân này. Ghi đè agents.defaults.cwd nhưng không ghi đè cwd được tạo khi khởi tạo phiên; các tệp khởi tạo và bộ nhớ vẫn nằm trong không gian làm việc. Hỗ trợ ~ và đường dẫn tương đối; cwd riêng yêu cầu chạy ngoài môi trường sandbox.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Mô hình ra quyết định của tác nhân`},help:{"v1-1mih8bf-3j":`Mô hình ra quyết định cho từng tác nhân. Nếu không đặt, sẽ kế thừa agents.defaults.decisionModel; chuỗi rỗng sẽ tắt các lệnh gọi ra quyết định cho tác nhân này.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`OpenClaw nhúng của tác nhân`},help:{"v1-uoomza-4b":`Các thiết lập ghi đè OpenClaw nhúng tùy chọn cho từng tác nhân. Dùng để áp dụng hành vi thực thi GPT-5 nghiêm ngặt hơn cho các tác nhân cụ thể mà không thay đổi thiết lập mặc định toàn cục.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Quy ước thực thi OpenClaw nhúng của tác nhân`},help:{"v1-1d1jaoi-7k":`Thiết lập ghi đè tùy chọn cho quy ước thực thi OpenClaw nhúng của từng tác nhân. Đặt thành "strict-agentic" để bật theo dõi kế hoạch có cấu trúc và khôi phục lượt không hiển thị cho tác nhân đó trong các lượt chạy thuộc họ GPT-5 của OpenAI/OpenAI Codex được hỗ trợ, hoặc "default" để kế thừa hành vi tiêu chuẩn của trình chạy.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Cờ thử nghiệm của tác nhân`},help:{"v1-1r06jov-2a":`Các cờ thử nghiệm cho từng tác nhân. Các trường bị bỏ qua sẽ kế thừa agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Chế độ mô hình cục bộ tinh gọn của tác nhân`},help:{"v1-5o3tgx-58":`Thiết lập ghi đè để khắc phục sự cố cho từng tác nhân trong chế độ mô hình cục bộ tinh gọn. Chỉ bật khi việc hạn chế các công cụ tùy chọn giải quyết được lỗi mô hình đã được xác nhận, mà không cần cắt giảm công cụ của mọi tác nhân.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Chế độ nhanh mặc định của tác nhân`},help:{"v1-1ujydjc-3o":`Giá trị mặc định tùy chọn cho chế độ nhanh của từng tác nhân ("auto", true hoặc false). Áp dụng khi không có thiết lập ghi đè chế độ nhanh cho từng tin nhắn hoặc phiên.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Chính sách gửi trực tiếp của nhịp kiểm tra`},help:{"v1-11gl9l0-41":`Thiết lập ghi đè theo từng tác nhân cho chính sách gửi nhịp kiểm tra trực tiếp/qua tin nhắn riêng (DM); dùng "block" cho các tác nhân chỉ nên gửi cảnh báo nhịp kiểm tra đến những đích không phải DM.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Thời gian chờ nhịp kiểm tra (giây)`},help:{"v1-kdetv4-6s":`Thời gian tối đa tính bằng giây cho phép một lượt nhịp kiểm tra của từng tác nhân chạy trước khi bị hủy. Để trống để kế thừa thời gian chờ nhịp kiểm tra đã hợp nhất, sau đó là agents.defaults.timeoutSeconds nếu được đặt; nếu không, dùng chu kỳ nhịp kiểm tra với giới hạn tối đa 600 giây.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Ảnh đại diện định danh`},help:{"v1-pzp9gr-1t":`Ảnh đại diện của tác nhân (đường dẫn tương đối với không gian làm việc, URL http(s) hoặc URI dữ liệu).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Chính sách mô hình của tác nhân`},help:{"v1-17d5je8-2r":`Chính sách ghi đè mô hình cho từng tác nhân. Danh sách cho phép được chỉ định rõ sẽ thay thế chính sách mặc định của tác nhân này.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Các mô hình được phép của tác nhân`},help:{"v1-v1ueke-5b":`Các tham chiếu mô hình được phép dùng để ghi đè cho tác nhân này. Chấp nhận bí danh, tham chiếu đầy đủ dạng "provider/model" và mẫu tiền tố có ký tự đại diện ở cuối như "provider/*" hoặc "provider/namespace/*"; để trống để cho phép mọi mô hình.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Thiết lập ghi đè mô hình của tác nhân`},help:{"v1-nld1vq-1v":`Các thiết lập ghi đè danh mục mô hình theo từng tác tử, với khóa là ID đầy đủ của nhà cung cấp/mô hình.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Môi trường thực thi mô hình của tác tử`},help:{"v1-7b59y-3s":`Chính sách môi trường thực thi tùy chọn theo từng mô hình cho tác tử này. Dùng tùy chọn này cho các ngoại lệ mô hình riêng của tác tử thay vì đặt môi trường thực thi cho toàn bộ tác tử.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`ID môi trường thực thi mô hình của tác tử`},help:{"v1-1ckfc39-46":`ID môi trường thực thi mô hình theo từng tác tử: "openclaw", "auto", ID bộ điều phối plugin đã đăng ký như "codex", hoặc bí danh backend CLI được hỗ trợ như "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Chế độ mã`},help:{"v1-91zu7f-7m":`Chế độ mã của OpenClaw cho tác tử này và đúng cặp nhà cung cấp/mô hình: Bật buộc kích hoạt, Tắt vô hiệu hóa, còn Mặc định kế thừa thiết lập kích hoạt của tác tử, sau đó là thiết lập ghi đè mô hình dùng chung, rồi đến tools.codeMode.enabled. Điều này không thay đổi môi trường thực thi đã chọn hoặc Chế độ mã gốc của Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Hiển thị suy luận mặc định của tác tử`},help:{"v1-13ly0xf-3m":`Chế độ hiển thị suy luận mặc định tùy chọn theo từng tác tử (on|off|stream). Áp dụng khi không có thiết lập ghi đè suy luận cho từng tin nhắn hoặc phiên.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Môi trường thực thi của tác tử`},help:{"v1-avjgkf-3l":`Bộ mô tả môi trường thực thi tùy chọn cho tác tử này. Dùng embedded để thực thi mặc định bằng OpenClaw hoặc acp để dùng các thiết lập mặc định của bộ điều phối ACP bên ngoài.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Môi trường thực thi ACP của tác tử`},help:{"v1-91zvdk-3i":`Các giá trị mặc định của môi trường thực thi ACP cho tác tử này khi runtime.type=acp. Các giá trị ghi đè ACP ở cấp liên kết vẫn được ưu tiên cho từng cuộc hội thoại.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Tác tử trong bộ điều phối ACP của tác tử`},help:{"v1-1pm98vp-37":`ID tác tử tùy chọn trong bộ điều phối ACP để dùng cho tác tử OpenClaw này (ví dụ: codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Hệ thống nền ACP của tác tử`},help:{"v1-1u3cdsg-2n":`Giá trị ghi đè tùy chọn cho hệ thống nền ACP dùng trong các phiên ACP của tác tử này (nếu không đặt, dùng acp.backend toàn cục).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Thư mục làm việc ACP của tác tử`},help:{"v1-d9p9rf-1t":`Thư mục làm việc mặc định tùy chọn cho các phiên ACP của tác tử này.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Chế độ ACP của tác tử`},help:{"v1-yatuk4-21":`Chế độ phiên ACP mặc định tùy chọn cho tác tử này (persistent hoặc oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Loại môi trường thực thi của tác tử`},help:{"v1-139fbk6-2r":`Loại môi trường thực thi cho tác tử này: "embedded" (môi trường thực thi OpenClaw mặc định) hoặc "acp" (các giá trị mặc định của bộ điều phối ACP).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Dải địa chỉ nguồn CDP của trình duyệt trong môi trường cô lập của tác tử`},help:{"v1-1q1qyso-1d":`Giá trị ghi đè theo từng tác tử cho danh sách cho phép CIDR nguồn CDP.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Mạng của trình duyệt trong môi trường cô lập của tác tử`},help:{"v1-13bdfww-4c":`Ghi đè mạng Docker của trình duyệt trong môi trường cách ly cho từng tác nhân. Hãy dùng mạng bridge; "none" không được hỗ trợ vì việc điều khiển trình duyệt yêu cầu các cổng CDP được công bố.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Cho phép tham gia không gian tên container trong Docker của môi trường cách ly tác nhân`},help:{"v1-1xtnseb-2i":`Tùy chọn ghi đè NGUY HIỂM cho từng tác nhân để cho phép tham gia không gian tên container trong chế độ mạng Docker của môi trường cách ly.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`GPU Docker trong môi trường cách ly tác nhân`},help:{"v1-1kek1n2-1t":`Ghi đè thiết lập chuyển tiếp GPU Docker cho từng tác nhân đối với các container trong môi trường cách ly.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Bộ lọc kỹ năng của tác nhân`},help:{"v1-igchue-6v":`Danh sách kỹ năng được phép tùy chọn cho tác nhân này. Nếu bỏ qua, tác nhân sẽ kế thừa agents.defaults.skills khi được thiết lập; nếu không, các kỹ năng vẫn không bị giới hạn. Đặt [] để không cho phép kỹ năng nào. Danh sách được chỉ định rõ sẽ thay thế hoàn toàn các giá trị mặc định được kế thừa thay vì hợp nhất với chúng.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Giới hạn Skills của tác nhân`},help:{"v1-1sv10v9-4y":`Các tùy chọn ghi đè hạn mức của hệ thống con kỹ năng cho từng tác nhân. Dùng khi tác nhân cần hạn mức lời nhắc kỹ năng khác mà không phải thêm một nhánh cấu hình giới hạn ngữ cảnh chung thứ hai.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Số ký tự tối đa trong lời nhắc Skills của tác nhân`},help:{"v1-dys63y-52":`Thiết lập ghi đè cho từng tác nhân về giới hạn ký tự của lời nhắc kỹ năng. Thiết lập này mở rộng đường dẫn skills.limits.maxSkillsPromptChars hiện có thay vì đưa cùng giới hạn đó qua contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Chế độ ủy quyền cho tác nhân phụ`},help:{"v1-1rkgh6p-4s":`Thiết lập ghi đè cho từng tác nhân về mức độ ưu tiên ủy quyền cho tác nhân phụ. Bỏ qua để dùng "prefer" trong phiên chính của tác nhân này và "suggest" ở những nơi khác; giá trị "prefer" hoặc "suggest" được đặt tường minh luôn được ưu tiên.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Mức suy nghĩ mặc định của tác nhân`},help:{"v1-173q7vy-43":`Mức suy nghĩ mặc định tùy chọn cho từng tác nhân. Ghi đè agents.defaults.thinkingDefault cho tác nhân này khi không có thiết lập ghi đè theo tin nhắn hoặc phiên.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Phần bổ sung vào danh sách công cụ được phép của tác nhân`},help:{"v1-1550ui9-46":`Danh sách công cụ được phép bổ sung cho từng tác nhân, bên cạnh chính sách toàn cục và chính sách hồ sơ. Giữ phạm vi hẹp để tránh vô tình mở rộng đặc quyền cho các tác nhân chuyên biệt.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Chính sách công cụ của tác nhân theo nhà cung cấp`},help:{"v1-mthxv9-4t":`Các thiết lập ghi đè chính sách công cụ theo nhà cung cấp cho từng tác nhân để kiểm soát khả năng trong phạm vi kênh. Dùng thiết lập này khi một tác nhân cần hạn chế chặt chẽ hơn đối với một nhà cung cấp so với các nhà cung cấp khác.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Chế độ mã của tác nhân`},help:{"v1-118t8u5-65":`Các tùy chọn Code Mode cho từng tác nhân. Giá trị enabled được đặt tường minh sẽ ghi đè các giá trị mặc định về kích hoạt của mô hình dùng chung và toàn cục; cấu hình ghi đè codeMode của mô hình dành riêng cho tác nhân được ưu tiên cao nhất. Các tùy chọn khác được hợp nhất vào tools.codeMode mà không thay đổi trạng thái kích hoạt.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Thời gian chờ thực thi của tác nhân (giây)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Ghi đè danh tính GitHub CLI của tác nhân`},help:{"v1-mjwdh4-38":`Ghi đè toàn bộ danh tính GitHub CLI được quản lý và thông tin tác giả Git cho tác nhân này. Bỏ qua để kế thừa danh tính hệ thống.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Email tác giả Git của tác nhân`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Tên tác giả Git của tác nhân`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Loại thông tin xác thực GitHub của tác nhân`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Phiên bản hồ sơ GitHub của tác nhân`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Danh sách thao tác tin nhắn được phép của tác nhân`},help:{"v1-1g5gov3-67":`Danh sách thao tác tin nhắn được phép cho từng tác nhân khi dùng công cụ message. Đặt thành danh sách tối thiểu như ["send"] cho các tác nhân trong môi trường cô lập công khai để các thao tác đọc, chỉnh sửa, xóa, bày tỏ cảm xúc và các thao tác tin nhắn khác dành riêng cho từng nhà cung cấp luôn bị ẩn và bị chặn.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Nhắn tin xuyên ngữ cảnh của tác nhân (giữa các nhà cung cấp)`},help:{"v1-pehesn-49":`Ghi đè thiết lập gửi tin nhắn giữa các nhà cung cấp cho từng tác nhân. Kế thừa thiết lập chung (mặc định: true). Đặt thành false để chặn tác nhân này gửi tin nhắn giữa các nhà cung cấp.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Nhắn tin xuyên ngữ cảnh của tác nhân (cùng nhà cung cấp)`},help:{"v1-s9u09h-4t":`Biện pháp kiểm soát theo từng tác nhân khi gửi tin nhắn đến các cuộc trò chuyện khác trên cùng một nhà cung cấp. Đặt cả thiết lập này và allowAcrossProviders thành false để giới hạn các tác nhân công khai chỉ gửi tin nhắn trong cuộc trò chuyện hiện tại.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Hồ sơ công cụ của tác nhân`},help:{"v1-1du76ix-57":`Thiết lập ghi đè theo từng tác nhân để chọn hồ sơ công cụ khi một tác nhân cần bộ năng lực cơ sở khác. Hạn chế sử dụng để các khác biệt về chính sách giữa các tác nhân luôn có chủ đích và có thể rà soát.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Bầy tác nhân`},help:{"v1-420ljs-2c":`Thiết lập ghi đè cấu hình bầy theo từng tác nhân. Các giá trị được hợp nhất và ưu tiên hơn cấu hình tools.swarm ở cấp cao nhất.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Chế độ báo đang nhập của tác nhân`},help:{"v1-oxir52-2e":`Ghi đè chính sách mặc định về thời điểm bắt đầu báo đang nhập cho một tác nhân mà không thay đổi các tác nhân khác.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Mô hình tiện ích của tác nhân`},help:{"v1-1v9oskz-2z":`Thiết lập ghi đè mô hình tiện ích tùy chọn theo từng tác nhân cho các tác vụ nội bộ ngắn. Ghi đè agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Thế hệ quyền sở hữu tác nhân`},help:{"v1-m2hp61-8g":`Dấu mốc thế hệ quyền sở hữu đa tác nhân được lưu bền vững. "explicit" có nghĩa là các kênh nền, nhịp kiểm tra định kỳ, hoạt động tham vấn tác nhân hệ thống, Talk, cron và các thao tác CLI không chỉ định tác nhân phải xác định được chủ sở hữu riêng cho từng bề mặt tương tác, nếu không thì phải từ chối thực hiện. OpenClaw tự động ghi dấu mốc này khi tạo hoặc di chuyển một nhóm tác nhân; hãy bỏ qua nếu chỉ có một tác nhân.`}},approvals:{label:{"v1-1m405m7-9":`Phê duyệt`},help:{"v1-4y3in-5w":`Các tùy chọn định tuyến phê duyệt để chuyển tiếp yêu cầu phê duyệt exec và plugin đến các đích trò chuyện ngoài phiên gốc. Giữ các tùy chọn này ở trạng thái tắt trừ khi người vận hành cần theo dõi rõ ràng các yêu cầu phê duyệt ngoài phiên.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Chuyển tiếp phê duyệt exec`},help:{"v1-1r2mozk-5v":`Nhóm các tùy chọn chuyển tiếp phê duyệt exec, bao gồm trạng thái bật, chế độ định tuyến, bộ lọc và đích cụ thể. Cấu hình tại đây khi lời nhắc phê duyệt cần được gửi đến các kênh vận hành thay vì chỉ luồng trò chuyện gốc.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Bộ lọc tác nhân cho phê duyệt`},help:{"v1-xbuhd3-5i":'Danh sách cho phép tùy chọn gồm các ID tác nhân đủ điều kiện được chuyển tiếp yêu cầu phê duyệt, ví dụ `["primary", "ops-agent"]`. Dùng danh sách này để giới hạn phạm vi ảnh hưởng của việc chuyển tiếp và tránh gửi thông báo đến các kênh về những tác nhân không liên quan.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Chuyển tiếp yêu cầu phê duyệt exec`},help:{"v1-1t0whe8-5s":`Bật chuyển tiếp yêu cầu phê duyệt exec đến các đích nhận đã cấu hình (mặc định: false). Giữ ở trạng thái tắt trong các thiết lập ít rủi ro và chỉ bật khi người xử lý phê duyệt cần thấy lời nhắc trên kênh.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Chế độ chuyển tiếp phê duyệt`},help:{"v1-1dedfo4-69":`Kiểm soát nơi gửi lời nhắc phê duyệt: "session" dùng cuộc trò chuyện gốc, "targets" dùng các đích đã cấu hình và "both" gửi theo cả hai đường. Dùng "session" làm chế độ cơ sở và chỉ mở rộng khi quy trình vận hành yêu cầu dự phòng.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Bộ lọc phiên cho phê duyệt`},help:{"v1-smeg8e-5u":'Các bộ lọc khóa phiên tùy chọn, khớp theo chuỗi con hoặc mẫu biểu thức chính quy, ví dụ `["discord:", "^agent:ops:"]`. Sử dụng mẫu có phạm vi hẹp để chỉ những ngữ cảnh phê duyệt dự kiến mới được chuyển tiếp đến các đích dùng chung.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Đích chuyển tiếp phê duyệt`},help:{"v1-17ah848-5u":`Các đích gửi được chỉ định rõ ràng, dùng khi chế độ chuyển tiếp bao gồm các đích, mỗi đích có thông tin chi tiết về kênh và nơi nhận. Giới hạn danh sách đích theo nguyên tắc đặc quyền tối thiểu và xác minh từng đích trước khi bật chuyển tiếp trên phạm vi rộng.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`ID tài khoản đích nhận phê duyệt`},help:{"v1-16zopng-5e":`Bộ chọn tài khoản tùy chọn dành cho cấu hình kênh có nhiều tài khoản khi phê duyệt phải được định tuyến qua ngữ cảnh tài khoản cụ thể. Chỉ sử dụng tùy chọn này khi kênh đích có nhiều danh tính đã được cấu hình.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Kênh đích nhận phê duyệt`},help:{"v1-ji1igl-59":`ID kênh/nhà cung cấp dùng để gửi phê duyệt được chuyển tiếp, chẳng hạn như discord, slack hoặc ID kênh của plugin. Chỉ sử dụng ID kênh hợp lệ để tránh việc gửi phê duyệt thất bại mà không có thông báo do tuyến không xác định.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`ID luồng đích nhận phê duyệt`},help:{"v1-1axynw7-59":`Luồng/chủ đề đích tùy chọn cho các kênh hỗ trợ gửi phê duyệt được chuyển tiếp vào luồng. Sử dụng tùy chọn này để giữ các trao đổi phê duyệt trong luồng vận hành thay vì kênh chính.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Địa chỉ đích nhận phê duyệt`},help:{"v1-1ijng7e-5n":`Định danh đích trong kênh nhận (ID kênh, ID người dùng hoặc tin nhắn gốc của luồng tùy theo nhà cung cấp). Hãy xác minh ý nghĩa theo từng nhà cung cấp vì định dạng đích khác nhau giữa các tích hợp kênh.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Chuyển tiếp phê duyệt plugin`},help:{"v1-1m6pzxv-6b":`Nhóm các thiết lập về cách chuyển tiếp phê duyệt plugin, bao gồm trạng thái bật, chế độ định tuyến, bộ lọc và đích được chỉ định cụ thể. Độc lập với việc chuyển tiếp phê duyệt thực thi. Cấu hình tại đây khi lời nhắc phê duyệt plugin cần được gửi đến các kênh vận hành.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Bộ lọc tác nhân cho phê duyệt plugin`},help:{"v1-jb1bra-4b":'Danh sách cho phép tùy chọn gồm các ID tác nhân có yêu cầu phê duyệt plugin được phép chuyển tiếp, ví dụ `["primary", "ops-agent"]`. Dùng thiết lập này để giới hạn phạm vi ảnh hưởng của việc chuyển tiếp.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Chuyển tiếp yêu cầu phê duyệt plugin`},help:{"v1-1ntctaf-3v":`Bật chuyển tiếp yêu cầu phê duyệt plugin đến các đích nhận đã cấu hình (mặc định: false). Độc lập với approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Chế độ chuyển tiếp phê duyệt plugin`},help:{"v1-1h62vy4-3z":`Kiểm soát nơi gửi lời nhắc phê duyệt plugin: "session" dùng cuộc trò chuyện gốc, "targets" dùng các đích đã cấu hình và "both" gửi theo cả hai cách.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Bộ lọc phiên cho phê duyệt plugin`},help:{"v1-1eppxmt-57":'Các bộ lọc khóa phiên tùy chọn, đối sánh theo chuỗi con hoặc mẫu biểu thức chính quy, ví dụ `["discord:", "^agent:ops:"]`. Dùng mẫu có phạm vi hẹp để chỉ chuyển tiếp các ngữ cảnh phê duyệt mong muốn.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Đích chuyển tiếp yêu cầu phê duyệt plugin`},help:{"v1-o92qze-3k":`Các đích gửi được chỉ định rõ, được sử dụng khi chế độ chuyển tiếp yêu cầu phê duyệt plugin bao gồm các đích; mỗi đích có thông tin chi tiết về kênh và nơi nhận.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`ID tài khoản đích nhận yêu cầu phê duyệt plugin`},help:{"v1-1wf3lqn-3j":`Bộ chọn tài khoản tùy chọn cho cấu hình kênh có nhiều tài khoản khi yêu cầu phê duyệt plugin phải được định tuyến qua một tài khoản cụ thể.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Kênh đích nhận yêu cầu phê duyệt plugin`},help:{"v1-1mzhzi9-34":`ID kênh/nhà cung cấp dùng để gửi yêu cầu phê duyệt plugin được chuyển tiếp, chẳng hạn như discord, slack hoặc ID kênh plugin.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`ID luồng đích nhận yêu cầu phê duyệt plugin`},help:{"v1-1scaw9c-2v":`Luồng/chủ đề đích tùy chọn cho các kênh hỗ trợ gửi yêu cầu phê duyệt plugin được chuyển tiếp theo luồng.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Nơi nhận yêu cầu phê duyệt plugin`},help:{"v1-sh5te1-31":`Mã định danh nơi nhận trong kênh đích (ID kênh, ID người dùng hoặc tin nhắn gốc của luồng, tùy theo nhà cung cấp).`}},attachments:{label:{"v1-8925gh-b":`Tệp đính kèm`},help:{"v1-1xvgkss-40":`Cách thức lưu giữ ở cấp cao nhất, dùng chung cho các nhà cung cấp và công cụ lưu trữ nội dung đa phương tiện. Sử dụng ttlHours khi cần dọn dẹp nội dung đa phương tiện lưu tạm nói chung trong một thời hạn xác định.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`TTL lưu giữ tệp đính kèm (giờ)`},help:{"v1-1g90day-9e":`Khoảng thời gian lưu giữ tùy chọn, tính bằng giờ, cho nội dung đa phương tiện đã lưu, do lượt quét mtime chung xử lý. Để trống để tắt lượt quét đó, hoặc đặt các giá trị như 24 (1 ngày) hay 168 (7 ngày) để định kỳ xóa nội dung đa phương tiện cũ trong vùng tạm. Nội dung đa phương tiện gửi đi được quản lý (tệp đính kèm tạo từ cuộc trò chuyện) không nằm trong phạm vi này và tuân theo cơ chế lưu giữ riêng có xét đến SQLite và bản ghi hội thoại.`}},audio:{label:{"v1-11wczsp-5":`Âm thanh`}},auth:{label:{"v1-5xz433-4":`Xác thực`},help:{"v1-1eu3aud-5c":`Cấu hình gốc của các hồ sơ xác thực, dùng cho thông tin xác thực nhà cung cấp theo nhiều hồ sơ và thứ tự chuyển đổi dự phòng dựa trên thời gian chờ. Giữ các hồ sơ tối giản và rõ ràng để luôn có thể kiểm tra hành vi chuyển đổi dự phòng tự động.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Thứ tự hồ sơ xác thực`},help:{"v1-1x6kknp-1w":`Các ID hồ sơ xác thực được sắp xếp theo thứ tự cho từng nhà cung cấp (dùng để chuyển đổi dự phòng tự động).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Hồ sơ xác thực`},help:{"v1-kzoqcn-1j":`Các hồ sơ xác thực có tên (nhà cung cấp + chế độ + email tùy chọn).`}},bindings:{label:{"v1-1hcih9f-8":`Liên kết`},help:{"v1-y7hrzb-4i":`Các quy tắc liên kết cấp cao nhất để định tuyến và duy trì quyền sở hữu cuộc hội thoại ACP. Dùng type=route để định tuyến thông thường và type=acp cho các liên kết bền vững với bộ điều phối ACP.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Thiết lập ghi đè liên kết ACP`},help:{"v1-1t4lisi-44":`Các thiết lập ghi đè ACP tùy chọn cho từng liên kết có bindings[].type=acp. Lớp này ghi đè các giá trị mặc định của agents.entries.*.runtime.acp cho cuộc hội thoại khớp với liên kết.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend của liên kết ACP`},help:{"v1-rsrbkp-2x":`Thiết lập ghi đè backend ACP cho liên kết này (nếu không có thì dùng backend ACP của môi trường thực thi tác nhân, sau đó là acp.backend toàn cục).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Thư mục làm việc của liên kết ACP`},help:{"v1-ngpkj0-1y":`Ghi đè thư mục làm việc cho các phiên ACP được tạo từ liên kết này.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Nhãn liên kết ACP`},help:{"v1-azce82-23":`Nhãn dễ đọc cho trạng thái/chẩn đoán ACP trong cuộc trò chuyện được liên kết này.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Chế độ liên kết ACP`},help:{"v1-cgq8xv-1v":`Ghi đè chế độ phiên ACP cho liên kết này (persistent hoặc oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`ID tác nhân của liên kết`},help:{"v1-17ra0cl-4m":`ID tác nhân đích nhận lưu lượng khi quy tắc khớp của liên kết tương ứng được thỏa mãn. Chỉ sử dụng ID tác nhân hợp lệ đã được cấu hình để tránh lỗi định tuyến khi chạy.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Quy tắc khớp của liên kết`},help:{"v1-sc1w2e-51":`Đối tượng quy tắc khớp để xác định khi nào áp dụng liên kết, bao gồm kênh và các ràng buộc tùy chọn về tài khoản/đối tác. Giới hạn phạm vi quy tắc để tránh tác nhân vô tình tiếp quản các ngữ cảnh khác.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`ID tài khoản của liên kết`},help:{"v1-1d209g7-56":`Bộ chọn tài khoản tùy chọn dành cho cấu hình kênh nhiều tài khoản, giúp liên kết chỉ áp dụng cho một danh tính. Sử dụng khi tuyến cần giới hạn phạm vi theo tài khoản; nếu không, hãy để chưa thiết lập.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Kênh của liên kết`},help:{"v1-d22m5-54":"Mã định danh kênh/nhà cung cấp mà liên kết này áp dụng, chẳng hạn như `telegram`, `discord` hoặc ID kênh của plugin. Sử dụng chính xác khóa kênh đã cấu hình để việc đánh giá liên kết hoạt động ổn định."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`ID máy chủ của liên kết`},help:{"v1-jzzfj1-4x":`Ràng buộc tùy chọn về ID cộng đồng/máy chủ theo kiểu Discord để đánh giá liên kết trong các triển khai nhiều máy chủ. Sử dụng khi cùng một mã định danh đối tác có thể xuất hiện ở các cộng đồng khác nhau.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Đối sánh đối tác cho liên kết`},help:{"v1-gcjxff-4i":`Bộ đối sánh đối tác tùy chọn cho các cuộc trò chuyện cụ thể, bao gồm loại và ID đối tác. Sử dụng khi chỉ cần gán cố định một đích trò chuyện trực tiếp/nhóm/kênh cho một tác nhân.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`ID đối tác cho liên kết`},help:{"v1-86fbh7-4b":`Mã định danh cuộc trò chuyện dùng để đối sánh đối tác, chẳng hạn như ID cuộc trò chuyện, ID kênh hoặc ID nhóm từ nhà cung cấp. Giữ giá trị này chính xác để tránh trường hợp không khớp mà không có thông báo.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Loại đối tác cho liên kết`},help:{"v1-uufscp-4x":`Loại cuộc trò chuyện với đối tác: "direct", "group", "channel" hoặc giá trị cũ "dm" (bí danh của direct không còn được khuyến nghị). Ưu tiên "direct" cho cấu hình mới và giữ kind phù hợp với ngữ nghĩa của kênh.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Vai trò cho liên kết`},help:{"v1-6s891m-4k":`Danh sách bộ lọc tùy chọn dựa trên vai trò, được dùng bởi các nhà cung cấp gắn vai trò vào ngữ cảnh trò chuyện. Sử dụng để định tuyến lưu lượng từ các vai trò có đặc quyền hoặc vai trò vận hành đến các tác nhân chuyên biệt.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`ID đội cho liên kết`},help:{"v1-hh9ps2-48":`Ràng buộc tùy chọn về ID đội/không gian làm việc, được dùng bởi các nhà cung cấp giới hạn phạm vi trò chuyện theo đội. Thêm ràng buộc này khi cần giới hạn các liên kết trong ngữ cảnh của một không gian làm việc.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Phiên cho liên kết`},help:{"v1-x325l2-4v":`Các tùy chọn ghi đè phiên theo tuyến cho những cuộc trò chuyện khớp với liên kết này. Dùng khi một tuyến có phạm vi hẹp cần giữ nguyên tác nhân nhưng tách biệt tính liên tục của phiên theo cách khác.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Phạm vi phiên tin nhắn trực tiếp của liên kết`},help:{"v1-10sg3xw-4s":`Tùy chọn ghi đè phạm vi phiên tin nhắn trực tiếp cho liên kết tuyến này. Ví dụ: giữ session.dmScope="main" ở cấp toàn cục nhưng dùng "per-account-channel-peer" cho một số đối tác nhắn tin trực tiếp được chọn.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Phạm vi phiên nhóm của liên kết`},help:{"v1-1ys2u7k-6n":`Tùy chọn ghi đè phạm vi phiên nhóm/kênh cho liên kết tuyến này. "per-group" giữ các phòng khớp tách biệt và được phiên chính của tác nhân theo dõi ngầm, bất kể dmScope; "main" gộp ngữ cảnh của các phòng vào phiên chính và không cần theo dõi.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Loại liên kết`},help:{"v1-172mhtk-3o":`Loại liên kết. Dùng "route" (hoặc bỏ qua đối với các mục tuyến kiểu cũ) để định tuyến thông thường, và "acp" cho các liên kết cuộc trò chuyện ACP lâu dài.`}},broadcast:{label:{"v1-awqjh0-j":`Luồng hội thoại nhóm tác tử`},help:{"v1-1tz72sr-6b":`Sử dụng luồng hội thoại nhóm tác tử để chạy nhiều tác tử đã cấu hình trên cùng một cuộc hội thoại đến, mỗi tác tử có phiên riêng. Các mục có định danh kênh hỗ trợ số vòng tiếp nối có giới hạn; các mảng đối tác WhatsApp kiểu cũ vẫn giữ cách xử lý một lượt.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Thành viên và tùy chọn của nhóm tác tử`},help:{"v1-1b63zmt-7d":`Sử dụng ID đối tác có định danh kênh (ví dụ "telegram:-100123") để cấu hình một mảng ID tác tử hoặc một đối tượng có cấu trúc nghiêm ngặt với agents, mentionGating, maxRounds và maxTurns. Các mục có định danh kênh được ưu tiên hơn các khóa đối tác WhatsApp kiểu cũ và cho phép tối đa 16 tác tử.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Thành viên nhóm tác tử`},help:{"v1-g5o0ky-43":`ID của các tác tử tham gia từ agents.entries (tối đa: 16). Mỗi thành viên sử dụng phiên riêng cho kênh, tài khoản, cuộc hội thoại và luồng hội thoại này.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Số vòng tối đa của nhóm tác nhân`},help:{"v1-i6v4jc-5a":`Số vòng tối đa cho mỗi tin nhắn đến, bao gồm vòng đầu tiên (số nguyên: 1–4, mặc định: 1). Các vòng tiếp theo chia sẻ những phản hồi có giới hạn và ghi rõ nguồn từ các tác nhân cùng nhóm, rồi dừng khi mọi thành viên đều bỏ lượt.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Số lượt tối đa của nhóm tác nhân`},help:{"v1-1kiv8dy-72":`Số lượt tham gia tối đa cho mỗi tin nhắn đến trên tất cả các vòng (số nguyên: 1–32, mặc định: agents.length). Các suất được dành trước khi phân công song song; giới hạn này áp dụng cho lượt của tác nhân, không phải các đoạn tin nhắn thực tế hay lượt gửi qua công cụ. Hạn mức không được tiếp tục sau khi khởi động lại.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Chọn thành viên nhóm tác nhân qua lượt nhắc tên`},help:{"v1-uay9zu-5u":`Chỉ chọn các thành viên được nhắc tên rõ ràng bằng @ khi có tên khớp; nếu không, chạy tất cả thành viên (mặc định: true). Tên không kèm @ hoặc biểu tượng cảm xúc không dùng để chọn thành viên. Danh sách cho phép của kênh và quy tắc tiếp nhận vẫn được áp dụng.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Chiến lược nhóm tác nhân`},help:{"v1-p4k9hu-4q":`Thứ tự thực thi của các thành viên: "parallel" (mặc định) chạy các tác nhân đồng thời, còn "sequential" chạy theo thứ tự đã cấu hình. Mỗi vòng hoàn tất trước khi vòng tiếp theo bắt đầu.`}},browser:{label:{"v1-13dzmen-7":`Trình duyệt`},help:{"v1-5b74wi-5l":`Các tùy chọn điều khiển trình duyệt khi chạy, dùng để kết nối CDP cục bộ hoặc từ xa, định tuyến hồ sơ và thiết lập hành vi chụp ảnh màn hình/bản chụp trạng thái. Giữ các giá trị mặc định trừ khi quy trình tự động hóa của bạn yêu cầu tùy chỉnh thiết lập truyền tải của trình duyệt.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Cho phép nhập hồ sơ hệ thống`},help:{"v1-1lsvlxw-5w":`Cho phép máy chủ macOS nhập cookie từ hồ sơ hệ thống cục bộ của trình duyệt thuộc họ Chrome vào hồ sơ trình duyệt do OpenClaw quản lý. Tắt tùy chọn này để ngăn việc nhập cookie từ hồ sơ trình duyệt và lời nhắc xin phép truy cập macOS Keychain đi kèm.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Chế độ chỉ kết nối trình duyệt`},help:{"v1-xaw7xm-4s":`Giới hạn trình duyệt ở chế độ chỉ kết nối mà không khởi chạy các tiến trình trình duyệt cục bộ. Dùng tùy chọn này khi tất cả các phiên trình duyệt được quản lý bên ngoài bởi một nhà cung cấp CDP từ xa.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`URL CDP của trình duyệt`},help:{"v1-2n72jb-65":`URL điểm cuối CDP/DevTools dùng để kết nối với một phiên bản trình duyệt được quản lý bên ngoài. Dùng URL này cho các máy chủ trình duyệt tập trung, đường hầm hoặc để kết nối với phiên hiện có, đồng thời giới hạn quyền truy cập URL chỉ qua các đường dẫn mạng đáng tin cậy.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Hồ sơ mặc định của trình duyệt`},help:{"v1-a6xo96-52":`Tên hồ sơ trình duyệt mặc định được chọn khi bên gọi không chỉ định rõ hồ sơ. Dùng một hồ sơ ổn định với quyền hạn thấp làm mặc định để giảm nguy cơ vô tình dùng trạng thái giữa các ngữ cảnh khác nhau.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Bật trình duyệt`},help:{"v1-19qr4oj-56":`Bật tích hợp chức năng trình duyệt trong Gateway để các công cụ trình duyệt và quy trình dựa trên CDP có thể chạy. Tắt khi không cần tự động hóa trình duyệt để giảm bề mặt tấn công và khối lượng công việc lúc khởi động.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Bật đánh giá mã trong trình duyệt`},help:{"v1-1oa79mq-59":`Bật các tiện ích đánh giá mã phía trình duyệt để hỗ trợ đánh giá tập lệnh trong thời gian chạy ở những nơi được hỗ trợ. Giữ ở trạng thái tắt trừ khi quy trình của bạn cần đánh giá mã ngoài các thao tác chụp trạng thái/điều hướng.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Đường dẫn tệp thực thi trình duyệt`},help:{"v1-1plb4ki-6i":`Đường dẫn tệp thực thi trình duyệt được chỉ định rõ khi tính năng tự động phát hiện không đáp ứng được môi trường máy chủ của bạn. Dùng đường dẫn tuyệt đối ổn định hoặc đường dẫn bắt đầu bằng ~ để trỏ đến thư mục chính của người dùng trên hệ điều hành, nhằm giữ hành vi khởi chạy nhất quán qua các lần khởi động lại.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Bộ chuyển tiếp tiện ích mở rộng trình duyệt`},help:{"v1-6ywlwr-4e":`Cài đặt tương thích xác thực cho bộ chuyển tiếp tiện ích mở rộng Chrome. Chỉ duy trì giai đoạn hỗ trợ cơ chế cũ khi các tiện ích mở rộng đã ghép nối phiên bản cũ hoặc các máy khách CDP bên ngoài vẫn cần cơ chế đó.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Cho phép xác thực kiểu cũ cho bộ chuyển tiếp trình duyệt`},help:{"v1-pj2e90-63":`Tạm thời chấp nhận xác thực kiểu cũ của bộ chuyển tiếp bằng Bearer, Basic và token-subprotocol. Mặc định: true trong một giai đoạn chuyển đổi. Đặt thành false sau khi mọi tiện ích mở rộng và máy khách CDP bên ngoài đều sử dụng Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Chế độ trình duyệt không giao diện`},help:{"v1-1rswq8j-5a":`Buộc trình duyệt khởi chạy ở chế độ không giao diện khi trình khởi chạy cục bộ khởi động các phiên bản trình duyệt. Giữ chế độ không giao diện được bật trong môi trường máy chủ và chỉ tắt khi cần gỡ lỗi với giao diện hiển thị.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Chế độ trình duyệt không có sandbox`},help:{"v1-slntux-4w":`Tắt các cờ cách ly sandbox của Chromium trong những môi trường mà sandbox không hoạt động khi chạy. Hãy giữ tùy chọn này ở trạng thái tắt bất cứ khi nào có thể vì việc bật tùy chọn sẽ làm giảm khả năng bảo vệ bằng cách ly tiến trình.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Hồ sơ trình duyệt`},help:{"v1-1x8lf05-51":`Bảng ánh xạ kết nối của các hồ sơ trình duyệt có tên, dùng để định tuyến rõ ràng đến các cổng CDP hoặc URL, kèm siêu dữ liệu tùy chọn. Giữ tên hồ sơ nhất quán và tránh định nghĩa điểm cuối chồng chéo.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Chế độ chỉ kết nối của hồ sơ trình duyệt`},help:{"v1-2b5zs0-5a":`Thiết lập ghi đè chế độ chỉ kết nối cho từng hồ sơ, bỏ qua việc khởi chạy trình duyệt cục bộ và chỉ kết nối với điểm cuối CDP hiện có. Hữu ích khi một hồ sơ được quản lý bên ngoài còn các hồ sơ khác được khởi chạy cục bộ.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Cổng CDP của hồ sơ trình duyệt`},help:{"v1-gx1yiq-49":`Cổng CDP cục bộ cho từng hồ sơ, được dùng khi kết nối với các phiên bản trình duyệt qua cổng thay vì URL. Dùng cổng riêng cho mỗi hồ sơ để tránh xung đột kết nối.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`URL CDP của hồ sơ trình duyệt`},help:{"v1-x491r0-64":`URL điểm cuối CDP/DevTools cho từng hồ sơ, dùng để định tuyến trình duyệt rõ ràng theo tên hồ sơ. Dùng tùy chọn này cho máy chủ CDP từ xa, đường hầm hoặc các hồ sơ có phiên hiện hữu cần kết nối qua một điểm cuối Chrome DevTools đang chạy.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Trình điều khiển của hồ sơ trình duyệt`},help:{"v1-17byyx6-5r":`Chế độ trình điều khiển trình duyệt cho từng hồ sơ. Dùng "openclaw" (hoặc "clawd" cũ) cho hồ sơ dựa trên CDP, "existing-session" để kết nối qua Chrome DevTools MCP, hoặc "extension" cho bộ chuyển tiếp tiện ích mở rộng Chrome có xác thực.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Đường dẫn tệp thực thi của hồ sơ trình duyệt`},help:{"v1-29azyv-4w":`Đường dẫn tệp thực thi trình duyệt cho từng hồ sơ trình duyệt được quản lý và khởi chạy cục bộ. Ghi đè browser.executablePath và chấp nhận đường dẫn bắt đầu bằng ~ để chỉ thư mục chính của người dùng trên hệ điều hành.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Chế độ không giao diện của hồ sơ trình duyệt`},help:{"v1-p4jtgv-4u":`Thiết lập ghi đè chế độ không giao diện cho từng hồ sơ đối với các phiên bản trình duyệt khởi chạy cục bộ. Dùng khi một hồ sơ cần duy trì chế độ không giao diện mà không buộc mọi hồ sơ khác phải dùng browser.headless.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Đối số Chrome MCP của hồ sơ trình duyệt`},help:{"v1-rc45ke-5g":`Các đối số Chrome DevTools MCP bổ sung cho từng hồ sơ để kết nối theo chế độ existing-session, chẳng hạn như --no-usage-statistics. Các đối số điểm cuối tại đây ghi đè cơ chế tự động kết nối hoặc lựa chọn URL trình duyệt tích hợp sẵn.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Lệnh Chrome MCP của hồ sơ trình duyệt`},help:{"v1-1xpty8o-2h":`Lệnh Chrome DevTools MCP cho từng hồ sơ để kết nối theo chế độ existing-session. Mặc định là npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Thư mục dữ liệu người dùng của hồ sơ trình duyệt`},help:{"v1-5xvgex-9h":`Thư mục dữ liệu người dùng Chromium cho từng hồ sơ, dùng để kết nối với phiên hiện có qua Chrome DevTools MCP. Sử dụng mục này cho Brave, Edge, Chromium hoặc các hồ sơ Chrome không mặc định khi cơ chế tự động kết nối tích hợp chọn nhầm thư mục dữ liệu trình duyệt trên máy chủ hoặc nút trình duyệt đã chọn. Đường dẫn bắt đầu bằng ~ sẽ được mở rộng thành thư mục chính của người dùng trên hệ điều hành.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Thiết lập mặc định cho bản chụp trình duyệt`},help:{"v1-v19wdy-4y":`Cấu hình chụp bản chụp mặc định được dùng khi bên gọi không cung cấp tùy chọn bản chụp cụ thể. Điều chỉnh mục này để hành vi chụp nhất quán trên các kênh và luồng tự động hóa.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Chế độ bản chụp trình duyệt`},help:{"v1-joeyxp-5c":`Chế độ trích xuất bản chụp mặc định kiểm soát cách nội dung trang được chuyển đổi để tác nhân sử dụng. Chọn chế độ cân bằng giữa tính dễ đọc, độ trung thực và lượng token tiêu thụ cho quy trình làm việc của bạn.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Chính sách SSRF của trình duyệt`},help:{"v1-1qbp9im-5e":`Thiết lập bảo vệ chống giả mạo yêu cầu phía máy chủ cho các luồng truy xuất qua trình duyệt/mạng có thể tiếp cận máy chủ nội bộ. Giữ các thiết lập mặc định hạn chế trong môi trường sản xuất và chỉ cho phép các đích đã được phê duyệt rõ ràng.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Tên máy chủ được trình duyệt cho phép`},help:{"v1-1rng39-2k":`Tên máy chủ chính xác hoặc địa chỉ IP cụ thể được cho phép qua các bước kiểm tra chính sách SSRF của trình duyệt. Giữ danh sách ở mức tối thiểu.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Cho phép dải địa chỉ IPv6 cục bộ duy nhất trong trình duyệt`},help:{"v1-1glx5cy-2c":`Cho phép địa chỉ IPv6 cục bộ duy nhất (fc00::/7) trong các môi trường proxy fake-IP đáng tin cậy.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Cho phép dải địa chỉ đo hiệu năng RFC 2544 trong trình duyệt`},help:{"v1-10ateu3-2i":`Cho phép các IP thuộc dải đo hiệu năng RFC 2544 (198.18.0.0/15) cho môi trường proxy IP giả đáng tin cậy.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Tên máy chủ bị chặn trong trình duyệt`},help:{"v1-nug0we-6k":`Các mẫu tên máy chủ bị từ chối trước khi phân giải DNS và áp dụng quy tắc cho phép, ngay cả khi đã bật quyền truy cập mạng riêng. Hỗ trợ tên máy chủ chính xác và "*.example.com" chỉ dành cho tên miền phụ; thêm riêng "example.com" để chặn tên miền gốc. Để trống hoặc không thiết lập sẽ không thêm quy tắc từ chối nào.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Cho phép mạng riêng trong trình duyệt (nguy hiểm)`},help:{"v1-17103pi-4m":`Cho phép các công cụ trình duyệt truy cập dải địa chỉ mạng riêng. Mặc định tắt khi chưa thiết lập; chỉ bật cho các đích mạng riêng đã được xác định rõ là đáng tin cậy.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Dọn dẹp thẻ trình duyệt`},help:{"v1-1ctwaad-4y":`Chính sách dọn dẹp trong khả năng có thể đối với các thẻ trình duyệt do phiên của tác nhân chính mở. Nên duy trì bật để tránh tích tụ các thẻ không còn dùng trong môi trường cách ly hoặc trình duyệt được quản lý trên các Gateway chạy lâu dài.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Bật dọn dẹp thẻ trình duyệt`},help:{"v1-4sv97p-3u":`Bật tính năng dọn dẹp các thẻ trình duyệt được theo dõi nhưng không hoạt động trong phiên của tác nhân chính. Chỉ tắt khi công cụ bên ngoài quản lý hoàn toàn vòng đời của thẻ.`}},channels:{label:{"v1-1ju93md-8":`Kênh`},help:{"v1-12yv6ma-5n":`Cấu hình nhà cung cấp kênh cùng các giá trị mặc định dùng chung để kiểm soát chính sách truy cập, khả năng hiển thị tín hiệu duy trì hoạt động và hành vi trên từng giao diện. Nên quản lý tập trung các giá trị mặc định và chỉ ghi đè cho từng nhà cung cấp khi cần.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Thiết lập mặc định cho kênh`},help:{"v1-uz6veb-4p":`Hành vi mặc định của kênh được áp dụng cho mọi nhà cung cấp khi chưa có thiết lập riêng cho từng nhà cung cấp. Dùng thiết lập này để áp dụng chính sách cơ sở nhất quán trước khi tinh chỉnh cho từng nhà cung cấp.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Bảo vệ chống vòng lặp bot mặc định`},help:{"v1-1lpznyk-4w":`Thiết lập mặc định để bảo vệ chống vòng lặp theo cặp cho các nhà cung cấp kênh có hỗ trợ cơ chế chống vòng lặp giữa các bot. Chỉ dùng thiết lập ghi đè riêng cho từng nhà cung cấp khi một kênh cần giới hạn khác.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Thời gian chờ mặc định cho vòng lặp bot (giây)`},help:{"v1-1yl5ird-2z":`Thời gian chờ tính bằng giây áp dụng cho một cặp sau khi vượt quá giới hạn vòng lặp. Giá trị mặc định cho các kênh có hỗ trợ là 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Bật bảo vệ chống vòng lặp bot theo mặc định`},help:{"v1-3ruik-4r":`Bật bảo vệ chống vòng lặp theo cặp theo mặc định cho các kênh có hỗ trợ khi tin nhắn do bot tạo có thể đi đến bước điều phối. Nhà cung cấp vẫn có thể tắt cơ chế bảo vệ khi bot bị bỏ qua.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Số sự kiện vòng lặp bot mặc định trong mỗi khoảng thời gian`},help:{"v1-1u0mdjc-41":`Số sự kiện tối đa mà một cặp người gửi/người nhận có thể trao đổi trong khoảng thời gian đã cấu hình trước khi bắt đầu chặn. Giá trị mặc định cho các kênh có hỗ trợ là 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Khoảng thời gian mặc định cho vòng lặp bot (giây)`},help:{"v1-12xpmen-2m":`Độ dài cửa sổ trượt tính bằng giây cho hạn mức vòng lặp theo cặp. Giá trị mặc định cho các kênh có hỗ trợ là 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Chế độ hiển thị ngữ cảnh mặc định`},help:{"v1-1hze3g1-5o":`Chế độ hiển thị ngữ cảnh bổ sung mặc định cho nội dung trích dẫn/luồng hội thoại/lịch sử được truy xuất: "all" (giữ toàn bộ ngữ cảnh), "allowlist" (chỉ người gửi trong danh sách cho phép) hoặc "allowlist_quote" (danh sách cho phép + giữ các trích dẫn tường minh).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Chính sách nhóm mặc định`},help:{"v1-ntl9m4-4n":`Chính sách nhóm mặc định trên các kênh: "open", "disabled" hoặc "allowlist". Giữ "allowlist" để cấu hình môi trường vận hành an toàn hơn, trừ khi bạn chủ động muốn cho phép tham gia nhóm rộng rãi.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Chế độ hiển thị tín hiệu định kỳ mặc định`},help:{"v1-49bw75-4v":`Cài đặt hiển thị tín hiệu định kỳ mặc định cho thông báo trạng thái do nhà cung cấp/kênh phát ra. Điều chỉnh trên toàn hệ thống để giảm các cập nhật trạng thái bình thường gây nhiễu mà vẫn hiển thị cảnh báo.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Hiển thị cảnh báo tín hiệu định kỳ`},help:{"v1-8dk8zx-4g":`Hiển thị cảnh báo tín hiệu định kỳ về tình trạng suy giảm/lỗi khi đặt thành true, giúp các kênh dành cho người vận hành kịp thời báo sự cố. Duy trì bật trong môi trường vận hành để thấy được các trạng thái kênh bị lỗi.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Hiển thị trạng thái bình thường của tín hiệu định kỳ`},help:{"v1-17tg3mk-4z":`Hiển thị các mục trạng thái nhịp tim bình thường/OK trong đầu ra trạng thái kênh khi đặt thành true. Giữ giá trị false trong môi trường có nhiều thông tin gây nhiễu và chỉ bật khi người vận hành cần xác nhận rõ ràng rằng hệ thống hoạt động bình thường.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Dùng chỉ báo nhịp tim`},help:{"v1-1w12cs2-4m":`Bật cách hiển thị nhịp tim dưới dạng chỉ báo ngắn gọn thay cho văn bản trạng thái dài dòng ở những nơi được hỗ trợ. Dùng chế độ chỉ báo cho bảng điều khiển dày đặc thông tin với nhiều kênh đang hoạt động.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Lượt nhắc ngầm định mặc định`},help:{"v1-4gtdyv-48":`Chính sách mặc định quy định liệu việc trả lời bot, trích dẫn bot và nhắn trong luồng có bot tham gia có kích hoạt các kênh nhắn tin hỗ trợ tính năng này mà không cần nhắc trực tiếp hay không.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Lượt nhắc ngầm định khi trích dẫn bot theo mặc định`},help:{"v1-va1u5v-2v":`Mặc định coi việc trích dẫn tin nhắn của bot là lượt nhắc ngầm định. Giá trị mặc định là true để tương thích ngược.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Lượt nhắc ngầm định khi trả lời bot theo mặc định`},help:{"v1-lm44c3-39":`Mặc định coi việc trả lời tin nhắn của chính bot là lượt nhắc ngầm định. Giá trị mặc định là true để tương thích ngược.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Lượt nhắc ngầm định trong luồng có bot tham gia theo mặc định`},help:{"v1-160205h-3o":`Mặc định coi các tin nhắn tiếp theo trong luồng mà bot đã tham gia là lượt nhắc ngầm định. Giá trị mặc định là true để tương thích ngược.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Ghi đè mô hình theo kênh`},help:{"v1-1b01spx-2p":`Ánh xạ nhà cung cấp -> ID kênh / ID người nhắn tin trực tiếp -> mô hình ghi đè (giá trị có dạng provider/model hoặc bí danh).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Worker đám mây`},help:{"v1-10carc4-5v":`Các hồ sơ worker đám mây cần chủ động bật cho môi trường từ xa dùng tạm thời. Khi bỏ qua phần này hoặc không có hồ sơ nào, tính năng tạo worker đám mây vẫn không khả dụng và cách xử lý trạng thái gateway/node hiện tại không thay đổi.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Màn hình nền worker đám mây (thử nghiệm)`},help:{"v1-vllayc-3n":`Bật giao diện thử nghiệm worker.desktop.observe và bảng Màn hình nền trong Control UI cho các môi trường worker đám mây hỗ trợ màn hình nền.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Nhóm worker đám mây được chuẩn bị sẵn`},help:{"v1-rw51o5-6b":`Giới hạn cho các worker đám mây được chuẩn bị sẵn cho những phiên sau. Các máy dự phòng phát sinh phí vận hành cho đến khi nhà cung cấp hoàn tất việc dọn dẹp; thời hạn hết hiệu lực cố định của chúng tuân theo nhu cầu thực tế của dự án và chính sách hiện hành của nhà cung cấp về trạng thái nhàn rỗi.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Giới hạn worker đám mây dự phòng sẵn sàng`},help:{"v1-1mpd1dt-7u":`Giới hạn trên toàn Gateway đối với số worker đám mây đã chuẩn bị nhưng chưa được phân công trên tất cả các dự án và hồ sơ (mặc định: 4). Worker đang được chuẩn bị và worker dự phòng chưa được xác nhận là đã dọn dẹp đều được tính vào giới hạn này. Đặt thành 0 để giải phóng hết worker dự phòng chưa được phân công và tắt tính năng bổ sung, trong khi vẫn duy trì việc tái sử dụng ảnh chụp nhanh và các phiên đang hoạt động.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Hồ sơ worker đám mây`},help:{"v1-eii67l-3j":`Các hồ sơ worker đám mây được đặt tên. Mỗi hồ sơ chọn một nhà cung cấp worker do plugin đăng ký và chứa các thiết lập do nhà cung cấp quản lý.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Hồ sơ worker đám mây`},help:{"v1-1v2w7jl-4u":`Một hồ sơ worker đám mây được chọn theo tên khi tạo môi trường. Lưu thông tin xác thực của nhà cung cấp qua các tham chiếu được hỗ trợ thay vì nhúng dữ liệu bí mật vào khối này.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Phương thức cài đặt worker đám mây`},help:{"v1-blrtbf-74":`Phương thức cài đặt worker: "bundle" (mặc định) chuyển bản dựng đã cài đặt của gateway có mã băm nội dung và hỗ trợ các phiên bản đã phát hành, đang phát triển và chưa phát hành; "npm" cài đặt đúng phiên bản gateway và chỉ khả dụng khi phiên bản đó đã được phát hành.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Nhà cung cấp worker đám mây`},help:{"v1-1p4s4c1-44":`ID nhà cung cấp worker được đăng ký bởi một plugin. Plugin đã cấu hình phải cung cấp ID này trước khi Gateway có thể cấp phát môi trường từ hồ sơ.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Số lượng mục tiêu cho worker đám mây dự phòng sẵn sàng`},help:{"v1-1nwve9s-7w":`Số lượng mục tiêu của worker đã chuẩn bị nhưng chưa được phân công cho mỗi dự án đủ điều kiện sử dụng hồ sơ này (mặc định: 1), tuân theo giới hạn nhóm worker đã chuẩn bị trên toàn Gateway. Đặt thành 0 để tắt worker dự phòng của hồ sơ này, trong khi vẫn duy trì việc tái sử dụng ảnh chụp nhanh. Worker đang được chuẩn bị và worker dự phòng chưa được xác nhận là đã dọn dẹp đều được tính vào số lượng mục tiêu.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Cài đặt nhà cung cấp worker đám mây`},help:{"v1-mq7u32-4j":`Các cài đặt thuộc nhà cung cấp được plugin đã chọn xác thực. Sử dụng đối tượng SecretRef cho các giá trị chứa thông tin bí mật; các cài đặt không rõ cấu trúc sẽ không được tự động phân giải thông tin bí mật.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Thời gian chờ tạm dừng worker đám mây khi nhàn rỗi`},help:{"v1-1keuwgh-4w":`Tự động thu hồi worker đám mây nhàn rỗi sau khoảng thời gian này, chẳng hạn 45m hoặc 2h; tin nhắn tiếp theo sẽ cấp phát một worker thay thế. Tối thiểu: 1m. Để trống để duy trì hoạt động của các worker.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Hồ sơ worker đám mây theo dự án`},help:{"v1-1kkfrif-46":`Tên hồ sơ worker đám mây mặc định được ánh xạ theo định danh kho mã đã chuẩn hóa thành chữ thường (host/owner/repo). Các ID hồ sơ được chỉ định rõ khi điều phối sẽ được ưu tiên.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Hồ sơ worker đám mây của dự án`},help:{"v1-1mux5u0-30":`Tên hồ sơ worker đám mây được dùng mặc định khi origin của cây làm việc trong phiên khớp với định danh kho mã này.`}},commands:{label:{"v1-15x4mpf-8":`Lệnh`},help:{"v1-1gi0dr2-5a":`Kiểm soát các giao diện lệnh trò chuyện, giới hạn theo chủ sở hữu và hành vi truy cập lệnh với quyền nâng cao trên các nhà cung cấp. Giữ nguyên các giá trị mặc định trừ khi bạn cần kiểm soát người vận hành chặt chẽ hơn hoặc mở rộng phạm vi sử dụng lệnh.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Quy tắc truy cập lệnh với quyền nâng cao`},help:{"v1-7azkw-5g":`Xác định các quy tắc cho phép lệnh đặc quyền theo kênh và người gửi cho các giao diện lệnh cấp chủ sở hữu. Sử dụng danh tính cụ thể theo từng nhà cung cấp với phạm vi hẹp để tránh cho phép quá nhiều người trong cuộc trò chuyện truy cập các lệnh đặc quyền.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Cho phép lệnh Bash trong trò chuyện`},help:{"v1-83ah7w-36":"Cho phép lệnh bash trong trò chuyện (`!`; bí danh `/bash`) chạy các lệnh shell trên máy chủ (mặc định: false; yêu cầu tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Thời gian Bash chạy ở tiền cảnh (ms)`},help:{"v1-1o0o4dw-2c":`Thời gian bash chờ trước khi chuyển sang chạy nền (mặc định: 2000; 0 chuyển sang chạy nền ngay lập tức).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Cho phép /config`},help:{"v1-151bb7c-21":`Cho phép lệnh /config trong trò chuyện đọc/ghi cấu hình trên ổ đĩa (mặc định: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Cho phép /debug`},help:{"v1-y1lc3j-1y":`Cho phép lệnh /debug trong trò chuyện áp dụng các giá trị ghi đè chỉ trong thời gian chạy (mặc định: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Cho phép /mcp`},help:{"v1-1rtwcgd-2o":`Cho phép lệnh /mcp trong trò chuyện quản lý cấu hình máy chủ MCP của OpenClaw trong mcp.servers (mặc định: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Lệnh gốc`},help:{"v1-dighr2-5n":`Đăng ký các lệnh gốc dạng dấu gạch chéo/menu với các kênh hỗ trợ đăng ký lệnh (Discord, Slack, Telegram). Duy trì bật để người dùng dễ tìm thấy lệnh, trừ khi bạn chủ động sử dụng quy trình lệnh chỉ bằng văn bản.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Lệnh kỹ năng gốc`},help:{"v1-19gtqci-5h":`Đăng ký các lệnh kỹ năng gốc để người dùng có thể gọi kỹ năng trực tiếp từ menu lệnh của nhà cung cấp nếu được hỗ trợ. Đảm bảo phù hợp với chính sách kỹ năng của bạn để các lệnh được cung cấp đáp ứng đúng kỳ vọng của người vận hành.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Chủ sở hữu lệnh`},help:{"v1-1di38gv-3y":`Danh sách cho phép chỉ định rõ các chủ sở hữu được dùng lệnh dành riêng cho chủ sở hữu. Sử dụng ID gốc của kênh (có thể thêm tiền tố như "whatsapp:+15551234567"). '*' bị bỏ qua.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Cho phép /plugins`},help:{"v1-akwy9y-33":`Cho phép lệnh trò chuyện /plugins liệt kê các plugin được phát hiện và bật/tắt plugin trong cấu hình (mặc định: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Cho phép khởi động lại`},help:{"v1-m32fv2-27":`Cho phép /restart, /update và các yêu cầu khởi động lại SIGUSR2 từ bên ngoài (mặc định: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Lệnh văn bản`},help:{"v1-1utu76s-5j":`Bật phân tích lệnh văn bản trong nội dung nhập trò chuyện, bên cạnh các giao diện lệnh gốc nếu có. Giữ tùy chọn này bật để đảm bảo khả năng tương thích giữa các kênh không hỗ trợ đăng ký lệnh gốc.`}},cron:{label:{"v1-1qlte4b-b":`Tác vụ tự động`},help:{"v1-4md8ic-5u":`Cài đặt bộ lập lịch toàn cục cho các tác vụ tự động hóa đã lưu, số lượt chạy đồng thời, phương án gửi dự phòng và thời gian lưu giữ phiên chạy. Giữ cài đặt mặc định trừ khi bạn đang mở rộng quy mô tự động hóa hoặc tích hợp các hệ thống nhận webhook bên ngoài.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Bật tự động hóa`},help:{"v1-y8otx6-5i":`Bật thực thi tự động hóa cho các lịch đã lưu do Gateway quản lý. Giữ tùy chọn này bật cho các luồng nhắc nhở/tự động hóa thông thường và chỉ tắt để tạm dừng toàn bộ hoạt động tự động hóa mà không xóa tác vụ.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Thời gian lưu giữ phiên tự động hóa`},help:{"v1-4wagu6-7e":"Kiểm soát thời gian lưu giữ các phiên chạy tự động hóa đã hoàn tất trước khi dọn dẹp (`24h`, `7d`, `1h30m` hoặc `false` để tắt dọn dẹp; thời lượng bằng không như `0h` cũng tắt tính năng này; mặc định: `24h`). Dùng thời gian lưu giữ ngắn hơn để hạn chế mức tăng dung lượng lưu trữ khi lịch chạy có tần suất cao."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Bỏ qua các lượt tự động hóa định kỳ bị lỡ`},help:{"v1-w9wfmo-66":`Bỏ qua các mốc chạy cron/every định kỳ bị lỡ khi Gateway khởi động và lên lịch cho lần chạy tiếp theo trong tương lai thay vì chạy bù. Mặc định: false. Bật để tránh lời nhắc lỗi thời sau thời gian ngừng hoạt động; các tác vụ at chạy một lần vẫn chạy bù.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Chính sách SSRF cho webhook tự động hóa`},help:{"v1-1xlfqnu-5h":`Chính sách SSRF áp dụng cho mọi webhook tự động hóa gửi đi. Các đích riêng tư, loopback, link-local và nội bộ vẫn bị chặn trừ khi chính sách này cho phép rõ ràng. Để trống để áp dụng chế độ gửi nghiêm ngặt.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Tên máy chủ được phép cho webhook tự động hóa`},help:{"v1-1i94hyz-3n":`Tên máy chủ chính xác hoặc địa chỉ IP trực tiếp được phép dùng để gửi webhook tự động hóa, bao gồm cả những đích vốn bị chặn. Giữ danh sách ở mức tối thiểu.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Cho phép dải địa chỉ IPv6 cục bộ duy nhất cho webhook tự động hóa`},help:{"v1-rke0oj-3b":`Cho phép gửi webhook tự động hóa đến các địa chỉ IPv6 cục bộ duy nhất (fc00::/7). Chỉ sử dụng với môi trường proxy fake-IP đáng tin cậy.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Cho phép dải địa chỉ đo hiệu năng RFC 2544 cho webhook tự động hóa`},help:{"v1-x1usg4-3h":`Cho phép webhook tự động hóa gửi đến các IP trong dải đo kiểm RFC 2544 (198.18.0.0/15). Chỉ sử dụng với môi trường proxy IP giả đáng tin cậy.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Tên máy chủ bị chặn cho webhook tự động hóa`},help:{"v1-16cv1ic-6a":`Các mẫu tên máy chủ bị từ chối trước khi phân giải DNS và áp dụng quy tắc cho phép gửi webhook tự động hóa. Hỗ trợ tên máy chủ chính xác và "*.example.com" chỉ dành cho tên miền phụ; thêm riêng "example.com" để chặn tên miền gốc. Để trống hoặc không thiết lập sẽ không thêm mục từ chối nào.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Cho phép webhook tự động hóa truy cập mạng riêng (nguy hiểm)`},help:{"v1-1n9710c-3t":`Cho phép webhook tự động hóa gửi đến các đích trong mạng riêng và mạng nội bộ. Giữ tùy chọn này tắt trừ khi mọi đích webhook đã cấu hình đều đáng tin cậy.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Token Bearer cho webhook tự động hóa`},help:{"v1-1l90hxg-5l":`Token Bearer được đính kèm vào các yêu cầu POST gửi webhook tự động hóa khi sử dụng chế độ webhook. Ưu tiên thay thế bằng giá trị bí mật hoặc biến môi trường và thay mới token này thường xuyên nếu các điểm cuối webhook dùng chung có thể truy cập được từ internet.`}},desktop:{label:{"v1-rs698z-7":`Môi trường máy tính`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Màn hình cục bộ`},help:{"v1-99weio-30":`Quan sát màn hình của các nút đã ghép nối hoặc nguồn máy chủ Gateway thử nghiệm, thông qua máy chủ VNC cục bộ.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Chia sẻ màn hình`},help:{"v1-m9lbcj-83":`Bật nguồn màn hình máy tính của máy này. Các nút macOS, Windows và Linux đã ghép đôi được bật theo mặc định; tùy chọn chia sẻ được đặt rõ ràng trong ứng dụng máy tính sẽ được ưu tiên. Nguồn Labs trên máy chủ Gateway bị tắt theo mặc định và áp dụng thay đổi ngay lập tức. Hãy khởi động lại nút đã ghép đôi sau khi thay đổi cấu hình màn hình máy tính của nút đó.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Màn hình máy chủ Linux được quản lý`},help:{"v1-1r7n22m-49":`Chạy và giám sát môi trường desktop TigerVNC/XFCE không màn hình, chỉ truy cập qua loopback trên Linux. Cổng được chỉ định rõ ràng hoặc máy chủ VNC hiện có trên cổng mặc định vẫn được ưu tiên.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Tệp mật khẩu VNC cục bộ`},help:{"v1-1m5lsox-37":`Đường dẫn tuyệt đối đến tệp mật khẩu VNC. Bỏ qua trên macOS để nhập thông tin đăng nhập tài khoản khi mở trình xem màn hình.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Cổng VNC cục bộ`},help:{"v1-1ku4w9b-2b":`Cổng RFB loopback của máy chủ VNC đang chạy trên máy này (mặc định: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Chẩn đoán`},help:{"v1-1d5rnym-5p":`Các tùy chọn chẩn đoán để truy vết có mục tiêu, xuất dữ liệu đo từ xa và kiểm tra bộ nhớ đệm khi gỡ lỗi. Giữ hoạt động chẩn đoán cơ bản ở mức tối thiểu trong môi trường vận hành thực tế và chỉ bật các tín hiệu chuyên sâu khi điều tra sự cố.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Truy vết bộ nhớ đệm`},help:{"v1-10523zm-5b":`Cài đặt ghi nhật ký truy vết bộ nhớ đệm để quan sát các quyết định về bộ nhớ đệm và ngữ cảnh dữ liệu trong các lần chạy nhúng. Tạm thời bật để gỡ lỗi và tắt sau đó để giảm lượng dữ liệu nhạy cảm trong nhật ký.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Bật truy vết bộ nhớ đệm`},help:{"v1-2c1umi-1v":`Ghi nhật ký ảnh chụp trạng thái truy vết bộ nhớ đệm cho các lần chạy tác tử nhúng (mặc định: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Bật chẩn đoán`},help:{"v1-a46pxt-4h":`Công tắc tổng cho đầu ra của công cụ chẩn đoán trong nhật ký và các luồng kết nối đo từ xa. Mặc định được bật; chỉ đặt thành false trong các môi trường có giới hạn nghiêm ngặt.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Cờ chẩn đoán`},help:{"v1-x4w5ok-33":`Bật nhật ký chẩn đoán có mục tiêu theo cờ (ví dụ: ["telegram.http"]). Hỗ trợ ký tự đại diện như "telegram.*" hoặc "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Cài đặt xuất OpenTelemetry cho dấu vết, số liệu và nhật ký do các thành phần Gateway phát ra. Sử dụng khi tích hợp với các hệ thống giám sát tập trung và quy trình truy vết phân tán.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Thu thập nội dung OpenTelemetry`},help:{"v1-19tid4t-2t":`Thu thập nội dung span OTEL khi được bật chủ động. Mặc định tắt; true sẽ thu thập nội dung tin nhắn không phải của hệ thống và nội dung công cụ.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`Bật OpenTelemetry`},help:{"v1-193bm0-5b":`Bật quy trình xuất OpenTelemetry cho dấu vết, số liệu và nhật ký dựa trên cài đặt điểm cuối/giao thức đã cấu hình. Giữ ở trạng thái tắt trừ khi điểm cuối bộ thu thập và thông tin xác thực đã được cấu hình đầy đủ.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Điểm cuối OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL điểm cuối bộ thu thập dùng để truyền dữ liệu xuất OpenTelemetry, bao gồm lược đồ và cổng. Sử dụng điểm cuối bộ thu thập đáng tin cậy, có thể truy cập và theo dõi lỗi tiếp nhận dữ liệu sau khi triển khai.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Khoảng thời gian đẩy dữ liệu OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Khoảng thời gian tính bằng mili giây để định kỳ đẩy dữ liệu đo từ xa từ bộ đệm đến bộ thu thập. Tăng để giảm tần suất truyền dữ liệu xuất hoặc giảm để theo dõi nhanh hơn trong quá trình ứng phó sự cố.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`Tiêu đề OpenTelemetry`},help:{"v1-s26t2a-52":`Các tiêu đề yêu cầu HTTP bổ sung được gửi kèm yêu cầu xuất OpenTelemetry, thường dùng để xác thực bên thuê hoặc định tuyến. Lưu thông tin bí mật trong các giá trị lấy từ biến môi trường và tránh thêm quá nhiều tiêu đề không cần thiết.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Bật nhật ký OpenTelemetry`},help:{"v1-12wo6rv-4k":`Bật xuất tín hiệu nhật ký qua OpenTelemetry bên cạnh các đích ghi nhật ký cục bộ. Sử dụng khi cần đối chiếu nhật ký tập trung giữa các dịch vụ và tác tử.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Điểm cuối nhật ký OpenTelemetry`},help:{"v1-1vgzldu-40":`Điểm cuối nhật ký OTLP/HTTP dành riêng cho tín hiệu nhật ký. Khi được đặt, giá trị này ghi đè diagnostics.otel.endpoint và OTEL_EXPORTER_OTLP_ENDPOINT chỉ đối với việc xuất nhật ký.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Bộ xuất nhật ký OpenTelemetry`},help:{"v1-9bzywd-5q":`Đích xuất nhật ký cho diagnostics.otel.logs. Dùng "otlp" cho điểm cuối nhật ký OTLP đã cấu hình, "stdout" để xuất một bản ghi JSON trên mỗi dòng stdout trong các luồng xử lý nhật ký container, và "both" khi cần cả hai đích.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Tiền tố tên chỉ số OpenTelemetry`},help:{"v1-1epdpi9-b2":`Thay thế tiền tố mặc định "openclaw." trong tên các chỉ số thuộc OpenClaw. Dùng chuỗi rỗng để xóa tiền tố, hoặc dùng tối đa 128 ký tự gồm chữ cái ASCII, chữ số, dấu gạch dưới, dấu chấm, dấu gạch nối và dấu gạch chéo, bắt đầu bằng một chữ cái. Thêm dấu phân cách bạn cần, ví dụ "acme."; tên các chỉ số tiêu chuẩn gen_ai.* không thay đổi. Khi thay đổi giá trị này, bạn cần cập nhật các bảng điều khiển và cảnh báo đang truy vấn theo tên cũ.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Bật chỉ số OpenTelemetry`},help:{"v1-13r4cf4-4x":`Bật xuất tín hiệu chỉ số đến điểm cuối bộ thu thập OpenTelemetry đã cấu hình. Duy trì bật để phục vụ bảng điều khiển tình trạng hoạt động và chỉ tắt nếu cần giảm thiểu lượng chỉ số.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Điểm cuối chỉ số OpenTelemetry`},help:{"v1-qlfh7x-47":`Điểm cuối chỉ số OTLP/HTTP dành riêng cho loại tín hiệu này. Khi được thiết lập, giá trị này ghi đè diagnostics.otel.endpoint và OTEL_EXPORTER_OTLP_ENDPOINT chỉ khi xuất chỉ số.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Giao thức OpenTelemetry`},help:{"v1-17ine8s-5e":`Giao thức truyền tải OTel để xuất dữ liệu đo từ xa. Chỉ chấp nhận "http/protobuf"; chạy "openclaw doctor --fix" để sửa giá trị "grpc" cũ đã lưu hoặc nhận hướng dẫn chỉnh sửa thủ công theo từng nguồn.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Tỷ lệ lấy mẫu dấu vết OpenTelemetry`},help:{"v1-brcwep-50":`Tỷ lệ lấy mẫu dấu vết (0-1) kiểm soát lượng dữ liệu dấu vết được xuất đến các hệ thống phụ trợ giám sát. Tỷ lệ thấp hơn giúp giảm tải và chi phí, còn tỷ lệ cao hơn giúp tăng độ chính xác khi gỡ lỗi.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Tên dịch vụ OpenTelemetry`},help:{"v1-1hpiqon-5d":`Tên dịch vụ được báo cáo trong các thuộc tính tài nguyên của dữ liệu đo từ xa để nhận diện phiên bản gateway này trong các hệ thống phụ trợ giám sát. Sử dụng tên ổn định để bảng điều khiển và cảnh báo luôn nhất quán qua các lần triển khai.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Bật dấu vết OpenTelemetry`},help:{"v1-j7zrrp-4s":`Bật xuất tín hiệu dấu vết đến điểm cuối bộ thu thập OpenTelemetry đã cấu hình. Duy trì bật khi cần truy vết độ trễ hoặc gỡ lỗi và tắt nếu bạn chỉ muốn thu thập chỉ số hoặc nhật ký.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Điểm cuối dấu vết OpenTelemetry`},help:{"v1-8yw5p1-43":`Điểm cuối dấu vết OTLP/HTTP dành riêng cho loại tín hiệu. Khi được đặt, giá trị này ghi đè diagnostics.otel.endpoint và OTEL_EXPORTER_OTLP_ENDPOINT chỉ khi xuất dấu vết.`}},discovery:{label:{"v1-l2sr05-9":`Khám phá`},help:{"v1-1sqleij-4w":`Các thiết lập khám phá dịch vụ để quảng bá mDNS cục bộ và tùy chọn báo hiệu sự hiện diện trên mạng diện rộng. Giới hạn phạm vi khám phá trong các mạng dự kiến để tránh rò rỉ siêu dữ liệu dịch vụ.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Khám phá mDNS`},help:{"v1-vtbyyq-4w":`Nhóm cấu hình khám phá mDNS để tinh chỉnh hoạt động quảng bá và khám phá trên mạng cục bộ. Giữ chế độ tối thiểu cho hoạt động khám phá LAN thông thường, trừ khi cần thêm siêu dữ liệu.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Chế độ khám phá mDNS`},help:{"v1-1p28pd5-2m":`Chế độ quảng bá mDNS ("minimal" là mặc định, "full" bao gồm cliPath/sshPort, "off" tắt mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Khám phá trên mạng diện rộng`},help:{"v1-1akkqjm-53":`Nhóm cấu hình khám phá trên mạng diện rộng để công bố tín hiệu khám phá ra ngoài phạm vi liên kết cục bộ. Chỉ bật trong các triển khai có chủ đích tổng hợp thông tin hiện diện của gateway trên nhiều địa điểm.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Tên miền khám phá trên mạng diện rộng`},help:{"v1-rxrygo-4m":`Tên miền DNS-SD unicast tùy chọn để khám phá trên mạng diện rộng, chẳng hạn như openclaw.internal. Sử dụng khi bạn chủ động công bố thông tin khám phá gateway ra ngoài phạm vi mDNS cục bộ.`}},env:{label:{"v1-1zc80q-b":`Môi trường`},help:{"v1-1ao5po6-55":`Các thiết lập nhập và ghi đè môi trường dùng để cung cấp biến thời gian chạy cho tiến trình gateway. Sử dụng phần này để kiểm soát việc nạp môi trường shell và hành vi truyền biến tường minh.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Nhập môi trường shell`},help:{"v1-1gw487t-4y":`Các tùy chọn nhập môi trường shell để tải biến từ shell đăng nhập của bạn khi khởi động. Giữ bật nếu bạn phụ thuộc vào các giá trị bí mật được định nghĩa trong hồ sơ shell hoặc các tùy chỉnh PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Bật nhập môi trường shell`},help:{"v1-5tiuup-5u":`Cho phép tải biến môi trường từ hồ sơ shell của người dùng trong quá trình khởi tạo. Giữ bật trên máy dành cho nhà phát triển, hoặc tắt trong môi trường dịch vụ được kiểm soát chặt chẽ với cơ chế quản lý biến môi trường rõ ràng.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Thời gian chờ nhập môi trường shell (ms)`},help:{"v1-nsk2yf-5c":`Thời gian tối đa tính bằng mili giây để xác định môi trường shell trước khi áp dụng cơ chế dự phòng. Dùng thời gian chờ ngắn hơn để khởi động nhanh hơn, hoặc tăng nếu quá trình khởi tạo shell tốn nhiều thời gian.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Ghi đè biến môi trường`},help:{"v1-yxc3z7-5n":`Các giá trị ghi đè biến môi trường theo cặp khóa/giá trị được chỉ định rõ ràng và hợp nhất vào môi trường tiến trình đang chạy của OpenClaw. Dùng tùy chọn này để cấu hình môi trường một cách nhất quán thay vì chỉ dựa vào các tác động gián tiếp từ hồ sơ shell.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Các tùy chọn thời gian chạy của Gateway cho chế độ liên kết địa chỉ, xác thực, Control UI, truyền tải từ xa và các biện pháp kiểm soát an toàn vận hành. Giữ các giá trị mặc định thận trọng trừ khi bạn chủ động cho phép truy cập Gateway ngoài các giao diện mạng cục bộ đáng tin cậy.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Cho phép Gateway dùng x-real-ip dự phòng`},help:{"v1-1wr3qmw-4c":`Cho phép dùng x-real-ip làm phương án dự phòng khi thiếu x-forwarded-for trong các tình huống dùng proxy. Giữ tắt trừ khi hệ thống tiếp nhận lưu lượng của bạn yêu cầu cơ chế tương thích này.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Xác thực Gateway`},help:{"v1-70b6ni-50":`Chính sách xác thực cho quyền truy cập HTTP/WebSocket vào Gateway, bao gồm chế độ, thông tin xác thực, cách xử lý proxy đáng tin cậy và giới hạn tốc độ. Luôn bật xác thực cho mọi triển khai không giới hạn ở địa chỉ loopback.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Cho phép xác thực Gateway bằng danh tính Tailscale`},help:{"v1-vqtmgw-53":`Cho phép các luồng xác thực danh tính Tailscale đáng tin cậy đáp ứng yêu cầu kiểm tra xác thực của Gateway khi được cấu hình. Chỉ sử dụng tùy chọn này khi cơ chế bảo mật danh tính trong tailnet của bạn đủ vững chắc và quy trình vận hành phụ thuộc vào nó.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Cấp phạm vi quyền theo danh tính cho Gateway`},help:{"v1-1h0zxy7-5n":`Ánh xạ danh tính đã được xác minh qua proxy đáng tin cậy hoặc Tailscale sang các phạm vi quyền của người vận hành chỉ có hiệu lực trong kết nối. Các khóa email được đối chiếu không phân biệt chữ hoa, chữ thường; các quyền được cấp bổ sung vào phạm vi quyền của thiết bị trước khi áp dụng giới hạn phạm vi quyền của kết nối.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Chế độ xác thực Gateway`},help:{"v1-j8rodq-9t":`Chế độ xác thực Gateway: "none", "token", "password" hoặc "trusted-proxy", tùy thuộc vào kiến trúc biên của bạn. Chế độ token/password chọn giá trị bí mật đã cấu hình (gateway.auth.token hoặc gateway.auth.password); máy khách có thể gửi giá trị này trong một trong hai trường xác thực khi kết nối. Sử dụng token/password khi cho phép truy cập trực tiếp và chỉ sử dụng trusted-proxy phía sau các proxy nhận biết danh tính đã được gia cố bảo mật.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Mật khẩu Gateway`},help:{"v1-1ndt0u2-4g":`Giá trị bí mật dùng chung được chọn khi gateway.auth.mode=password. Máy khách có thể gửi giá trị này trong auth.token hoặc auth.password. Tailscale Funnel yêu cầu chế độ mật khẩu.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Giới hạn tốc độ xác thực Gateway`},help:{"v1-1kstr42-54":`Các tùy chọn giới hạn tần suất thử đăng nhập/xác thực để giảm nguy cơ dò thông tin đăng nhập tại ranh giới Gateway. Luôn bật trong môi trường có thể truy cập từ bên ngoài và điều chỉnh ngưỡng theo mức lưu lượng thông thường của bạn.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Token Gateway`},help:{"v1-16i7cxs-5q":`Bí mật dùng chung được chọn bởi gateway.auth.mode=token, là mặc định cho quy trình thiết lập cục bộ mới. Máy khách có thể gửi bí mật này trong auth.token hoặc auth.password. Việc liên kết với địa chỉ không phải loopback yêu cầu bật một chế độ xác thực.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Xác thực Gateway qua proxy tin cậy`},help:{"v1-12fsi5d-58":`Ánh xạ tiêu đề xác thực qua proxy tin cậy cho các nhà cung cấp danh tính phía trước có chèn thông tin xác nhận về người dùng. Chỉ sử dụng với các dải CIDR proxy đã biết và danh sách cho phép tiêu đề nghiêm ngặt để ngăn chặn tiêu đề danh tính giả mạo.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Danh tính GitHub qua Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Danh tính GitHub đã xác minh, không bắt buộc, từ một nhà cung cấp Cloudflare Access OIDC được chọn. Yêu cầu các tiêu đề email và xác nhận tiêu chuẩn của Access. Khi thiếu thuộc tính xác nhận, hồ sơ vẫn chỉ dùng email; các vai trò và tùy chọn đồng tác giả hiện có của hồ sơ được giữ nguyên.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Thuộc tính xác nhận ID tài khoản GitHub`},help:{"v1-pcaaw7-57":`Tên chính xác của thuộc tính xác nhận OIDC được chuyển tiếp, có giá trị là ID tài khoản GitHub đã xác minh ở dạng chuỗi số nguyên dương hệ thập phân. Cấu hình Access để chuyển tiếp thuộc tính này trong oidc_fields; không bao giờ dùng thuộc tính xác nhận chưa được xác minh mà người dùng có thể chỉnh sửa.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Bên phát hành Cloudflare Access`},help:{"v1-gykv03-56":`Địa chỉ gốc HTTPS chính xác của nhóm Cloudflare Access đáng tin cậy, chẳng hạn như https://example.cloudflareaccess.com, không có dấu gạch chéo ở cuối. Các khai báo từ bên phát hành khác không cung cấp danh tính GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`ID nhà cung cấp OIDC của Cloudflare Access`},help:{"v1-kbyo5w-44":`ID nhà cung cấp danh tính Access chính xác cho tích hợp OIDC đáng tin cậy. Chỉ có tên hiển thị của nhà cung cấp hoặc tên khai báo trùng khớp thì không đủ để xác lập độ tin cậy.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Tự động phê duyệt thiết bị qua proxy tin cậy`},help:{"v1-uh32ha-6z":`Chính sách tùy chọn để tự động phê duyệt thiết bị mới của người vận hành dùng giao diện trình duyệt hoặc ứng dụng gốc, cũng như việc mở rộng phạm vi quyền với cùng một khóa sau khi xác thực qua proxy tin cậy. Quyền được cấp bị giới hạn bởi deviceAutoApprove.scopes và tiêu đề x-openclaw-scopes của proxy nếu có.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Bật tự động phê duyệt thiết bị qua proxy tin cậy`},help:{"v1-1nntwls-78":`Tự động phê duyệt thiết bị mới của người vận hành dùng giao diện trình duyệt hoặc ứng dụng gốc, cũng như việc mở rộng phạm vi quyền với cùng một khóa sau khi proxy ngược xác thực người dùng được phép. Mặc định: false. Chỉ bật khi ranh giới xác thực danh tính của proxy đủ vững chắc để thay thế việc ghép nối thiết bị thủ công.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Phạm vi quyền tự động phê duyệt thiết bị qua proxy đáng tin cậy`},help:{"v1-raeila-g3":`Các phạm vi quyền tối đa được cấp cho thiết bị của người vận hành được tự động phê duyệt. Mặc định là operator.read, operator.write, operator.approvals và operator.questions. Các phạm vi quyền được yêu cầu bị giới hạn trong danh sách này; yêu cầu không chỉ định phạm vi quyền sẽ được cấp các quyền trong danh sách này. Khi chưa được thiết lập, tính năng tự động phê duyệt cũng thêm operator.questions cho các ứng dụng UI cũ; danh sách được chỉ định rõ ràng sẽ không bao giờ được mở rộng. Việc liệt kê rõ operator.admin cho phép mọi người dùng được xác thực qua proxy tự động được phê duyệt toàn quyền quản trị và khiến các yêu cầu không chỉ định phạm vi quyền tự động nhận toàn quyền quản trị; việc này cũng dẫn đến một phát hiện ở mức nghiêm trọng trong kiểm tra bảo mật và cảnh báo khi khởi động Gateway.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Chế độ liên kết mạng của Gateway`},help:{"v1-1unqude-4y":`Cấu hình liên kết mạng: "auto", "lan", "loopback", "custom" hoặc "tailnet" để kiểm soát khả năng truy cập qua các giao diện mạng. Giữ "loopback" để chỉ hoạt động cục bộ; "auto" có thể cho phép truy cập qua mọi giao diện mạng.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`Tác nhân CLI`},help:{"v1-1qqo8m2-5a":`Cho phép Control UI phát hiện các bộ máy phiên CLI bên ngoài do danh mục phiên của Gateway cung cấp. Mặc định bật; tắt để ngăn khởi chạy các bộ máy đó từ bộ chọn mô hình cho phiên mới.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`Bật tác nhân CLI`},help:{"v1-ufu7fx-8p":`Hiển thị các tác nhân CLI từ danh mục trong bộ chọn mô hình cho phiên mới của Control UI khi là true (mặc định: true). Đặt thành false để tắt tác nhân CLI và khả năng tạo phiên CLI gốc. Chỉ các danh mục công bố khả năng tạo phiên mới được liệt kê, và bộ chọn vẫn ẩn khi Gateway không công bố hỗ trợ danh mục phiên.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Cài đặt lưu trữ Control UI, bao gồm bật/tắt, định tuyến đường dẫn và tăng cường bảo mật nguồn gốc trình duyệt/xác thực. Hạn chế tối đa phạm vi truy cập UI và kết hợp với các biện pháp xác thực mạnh trước khi triển khai công khai trên internet.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Nguồn gốc được phép của Control UI`},help:{"v1-1stgitk-9i":`Các nguồn gốc trình duyệt được phép cho kết nối websocket của Control UI/WebChat (chỉ chấp nhận nguồn gốc đầy đủ, ví dụ: https://control.example.com). Bắt buộc đối với các bản triển khai Control UI ngoài địa chỉ loopback, trừ khi cơ chế dự phòng nguy hiểm dựa trên tiêu đề Host được bật rõ ràng. Đặt ["*"] có nghĩa là cho phép mọi nguồn gốc trình duyệt và nên tránh sử dụng ngoài môi trường kiểm thử cục bộ được kiểm soát chặt chẽ.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Cho phép URL nhúng bên ngoài trong Control UI`},help:{"v1-obwpfg-6s":`Tùy chọn NGUY HIỂM cho phép nội dung nhúng được lưu trữ tải các URL http(s) tuyệt đối bên ngoài. Hãy tắt tùy chọn này trừ khi Control UI của bạn chủ đích nhúng các trang bên thứ ba đáng tin cậy; các tài liệu /__openclaw__/canvas và /__openclaw__/a2ui được lưu trữ không cần tùy chọn này.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Tự động tải favicon của liên kết`},help:{"v1-bn9u34-ag":`Tải favicon của liên kết và bản xem trước trên mạng xã hội của các tab trình duyệt qua Gateway (mặc định bật). Các thẻ tab trình duyệt tải siêu dữ liệu công khai của trang và hình ảnh được khai báo mà không dùng cookie của trình duyệt hay thông tin xác thực của trang web. Tất cả yêu cầu đều được kiểm tra SSRF nghiêm ngặt, đồng thời việc xử lý HTML/hình ảnh được giới hạn. Đặt thành false để tắt tính năng tự động tải cả favicon lẫn bản xem trước trang; ảnh chụp màn hình trình duyệt trực tiếp không bị ảnh hưởng.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Đường dẫn cơ sở của Control UI`},help:{"v1-1dx68ar-1w":`Tiền tố URL tùy chọn nơi Control UI được cung cấp (ví dụ: /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Lời mời tham gia cộng đồng trong Control UI`},help:{"v1-1rz3zsx-73":`Hiển thị lời mời tham gia cộng đồng Discord trong Control UI do Gateway này cung cấp (mặc định bật). Đặt thành false để ẩn lời mời trên mọi trình duyệt sử dụng bản triển khai UI này. Thay đổi có hiệu lực sau khi làm mới trình duyệt hoặc kết nối lại; việc bật lại vẫn giữ nguyên trạng thái đóng lời mời đã lưu cục bộ trên trình duyệt.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Cho phép cơ chế dự phòng nguồn gốc dựa trên tiêu đề Host (nguy hiểm)`},help:{"v1-1t1qi4c-7v":`Tùy chọn NGUY HIỂM cho phép sử dụng cơ chế dự phòng nguồn gốc dựa trên tiêu đề Host khi kiểm tra websocket của Control UI/WebChat. Chế độ này được hỗ trợ khi bản triển khai của bạn chủ đích dựa vào chính sách nguồn gốc theo tiêu đề Host; cấu hình tường minh gateway.controlUi.allowedOrigins vẫn là lựa chọn mặc định được khuyến nghị để tăng cường bảo mật.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Chế độ sandbox cho nội dung nhúng trong Control UI`},help:{"v1-d54l3a-7c":'Chính sách sandbox của iframe cho nội dung nhúng được lưu trữ trong Control UI. "strict" vô hiệu hóa tập lệnh, "scripts" cho phép nội dung nhúng tương tác nhưng vẫn duy trì cách ly nguồn gốc (mặc định), còn "trusted" thêm `allow-same-origin` cho các tài liệu cùng trang web có chủ đích cần quyền cao hơn.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Bật Control UI`},help:{"v1-1hhyymc-4w":`Cho phép cung cấp Control UI của Gateway từ tiến trình HTTP của Gateway khi đặt thành true. Giữ tùy chọn này bật để quản trị cục bộ và tắt khi có giao diện điều khiển bên ngoài thay thế.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Môi trường Control UI`},help:{"v1-paarso-4n":`Thông tin nhận diện môi trường công khai, không bắt buộc, hiển thị trên dải màu của Control UI, ảnh đại diện của tác tử, nhãn dạng viên, tiêu đề trình duyệt và biểu tượng trang. Bỏ qua để giữ giao diện mặc định.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Màu môi trường của Control UI`},help:{"v1-mp6cta-2i":`Dải màu môi trường theo tên: teal, amber, purple, coral, pink, blue, green, red hoặc gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Nhãn môi trường của Control UI`},help:{"v1-1njve3z-3z":`Nhãn môi trường hiển thị trong Control UI và thẻ trình duyệt; khoảng trắng ở đầu và cuối sẽ bị loại bỏ và nhãn phải chứa từ 1 đến 24 ký tự.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Các tính năng thử nghiệm của Control UI`},help:{"v1-1qobi2m-3g":`Các tính năng thử nghiệm của Control UI cần chủ động bật để sử dụng. Những tính năng này có thể thay đổi giữa các bản phát hành và sẽ bị tắt trừ khi được bật rõ ràng.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Giao diện plugin tùy chỉnh`},help:{"v1-108u6ts-9e":`Cho phép các plugin do người dùng cài đặt thực thi JavaScript gốc trong Control UI (mặc định: false). Các chế độ xem của plugin đi kèm vẫn khả dụng. Giao diện tùy chỉnh dùng chung quyền Gateway của người vận hành đang đăng nhập; chỉ bật cho các plugin đáng tin cậy. Các thay đổi được áp dụng mà không cần khởi động lại Gateway. Tải lại các trang Control UI đang mở để xóa mã plugin đã tải trước đó.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Thông tin xác thực dịch vụ GitHub của Control UI`},help:{"v1-1p31phh-d6":`Thông tin xác thực dịch vụ dựa trên SecretRef để khám phá dự án trong Control UI và xem trước GitHub khi di chuột mà không cần danh tính được quản lý. Tính năng xem trước khi di chuột ưu tiên danh tính GitHub đã cấu hình của tác nhân được chọn, kế thừa danh tính hệ thống khi không có cấu hình ghi đè. Nên cấu hình tường minh để xác định rõ chủ sở hữu dịch vụ. Bỏ qua mục này để giữ cơ chế dự phòng GH_TOKEN/GITHUB_TOKEN từ môi trường tiến trình Gateway dùng chung. Nếu thông tin xác thực được cấu hình tường minh nhưng không khả dụng, quyền truy cập sẽ bị từ chối.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Thư mục gốc tài nguyên Control UI`},help:{"v1-elck04-25":`Thư mục gốc tùy chọn trên hệ thống tệp dành cho tài nguyên Control UI (mặc định là dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Trình quan sát phiên Control UI`},help:{"v1-1ahs80-8a":`Tạo bản tóm tắt trạng thái phiên theo thời gian thực cho các máy khách Control UI đã đăng ký bằng mô hình tiện ích của từng tác nhân (mặc định bật). Đặt thành false để tắt các lệnh gọi mô hình quan sát trên toàn bộ Gateway; đặt agents.defaults.utilityModel thành chuỗi rỗng sẽ tắt tính năng quan sát bằng mô hình tiện ích đối với các tác nhân không ghi đè thiết lập này.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Địa chỉ liên kết tùy chỉnh của Gateway`},help:{"v1-lwjcyo-4d":`Địa chỉ IPv4 dùng cho liên kết tùy chỉnh. Các địa chỉ IPv4 cụ thể cũng yêu cầu cùng cổng Gateway trên 127.0.0.1; tránh dùng 0.0.0.0 trừ khi cần cho phép truy cập qua tất cả giao diện mạng.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`API HTTP của Gateway`},help:{"v1-ebtex7-4j":`Cấu hình API HTTP của Gateway, tập hợp các tùy chọn bật/tắt điểm cuối và các biện pháp kiểm soát khả năng truy cập API ở lớp truyền tải. Chỉ bật các điểm cuối cần thiết để giảm bề mặt tấn công.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Các điểm cuối HTTP của Gateway`},help:{"v1-1a0r104-55":`Các tùy chọn bật/tắt tính năng điểm cuối HTTP trong API của Gateway dành cho các tuyến tương thích và các tích hợp tùy chọn. Chỉ bật các điểm cuối khi cần và theo dõi cách thức truy cập sau khi triển khai.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Điểm cuối OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Bật điểm cuối `POST /v1/chat/completions` tương thích với OpenAI (mặc định: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Giới hạn hình ảnh của OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Các tùy chọn kiểm soát việc tải và xác thực hình ảnh cho các phần `image_url` tương thích với OpenAI."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Danh sách loại MIME hình ảnh được phép của OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Các loại MIME được phép cho các phần `image_url` (danh sách không phân biệt chữ hoa và chữ thường)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Cho phép URL hình ảnh trong OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Cho phép phía máy chủ tải nội dung từ URL cho các phần `image_url` (mặc định: false; URI dữ liệu vẫn được hỗ trợ). Đặt giá trị này thành `false` để tắt hoàn toàn việc tải nội dung từ URL."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Số byte hình ảnh tối đa của OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Số byte tối đa cho mỗi hình ảnh `image_url` được tải hoặc giải mã (mặc định: 10MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Số lần chuyển hướng tối đa cho hình ảnh trong OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Số lần chuyển hướng HTTP tối đa được phép khi tải URL `image_url` (mặc định: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Thời gian chờ hình ảnh trong OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Thời gian chờ tính bằng mili giây khi tải URL `image_url` (mặc định: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Danh sách URL hình ảnh được phép trong OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Danh sách tên máy chủ được phép tùy chọn khi tải URL `image_url`; hỗ trợ tên máy chủ chính xác và ký tự đại diện `*.example.com`. Danh sách trống hoặc không được cung cấp có nghĩa là không áp dụng giới hạn theo danh sách tên máy chủ được phép."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Các tiêu đề bảo mật HTTP của Gateway`},help:{"v1-n8z1hb-44":`Các tiêu đề bảo mật phản hồi HTTP tùy chọn do chính tiến trình Gateway áp dụng. Nên thiết lập các tiêu đề này tại proxy ngược nếu TLS kết thúc tại đó.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Tiêu đề bảo mật truyền tải nghiêm ngặt`},help:{"v1-1buwhc3-3v":`Giá trị cho tiêu đề phản hồi Strict-Transport-Security. Chỉ đặt cho các nguồn HTTPS mà bạn kiểm soát hoàn toàn; dùng false để vô hiệu hóa một cách tường minh.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Chế độ Gateway`},help:{"v1-nfjirv-5m":`Chế độ hoạt động của Gateway: "local" chạy các kênh và môi trường thực thi tác nhân trên máy chủ này, còn "remote" kết nối qua cơ chế truyền tải từ xa. Giữ "local" trừ khi bạn chủ định triển khai mô hình Gateway từ xa tách biệt.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Bật Skills của nút Gateway`},help:{"v1-1xwu6at-3g":`Chấp nhận các kỹ năng do các nút đã ghép đôi công bố khi chúng đang kết nối (mặc định: true). Đặt thành false để bỏ qua các kỹ năng do nút công bố.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Chế độ trình duyệt của nút Gateway`},help:{"v1-oeu1nc-69":`Định tuyến trình duyệt qua nút ("auto" = ưu tiên trình duyệt trên máy chủ, sử dụng một nút trình duyệt đã kết nối khi không có khả năng chạy cục bộ; "manual" = yêu cầu chọn nút cụ thể hoặc có cấu hình ghim nút; "off" = tắt định tuyến qua nút).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Ghim nút trình duyệt Gateway`},help:{"v1-1cykty2-1p":`Ghim định tuyến trình duyệt vào một nút có ID hoặc tên cụ thể (không bắt buộc).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Danh sách cho phép của nút Gateway (lệnh bổ sung)`},help:{"v1-6l4otb-5m":"Các lệnh node.invoke bổ sung được phép ngoài các lệnh mặc định của Gateway (mảng chuỗi lệnh). Việc bật các lệnh nguy hiểm tại đây là một thiết lập ghi đè nhạy cảm về bảo mật và sẽ bị `openclaw security audit` gắn cờ."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Danh sách chặn của nút Gateway`},help:{"v1-u7c8wx-53":"Tên các lệnh của nút cần chặn ngay cả khi có trong thông tin khai báo của nút hoặc danh sách cho phép mặc định (chỉ khớp chính xác tên lệnh, ví dụ: `system.run`; không kiểm tra nội dung shell bên trong lệnh đó)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Ghép đôi nút Gateway`},help:{"v1-gldsi2-4s":`Cài đặt chính sách ghép nối nút. Tự động phê duyệt có xác minh SSH được bật theo mặc định; tự động phê duyệt theo CIDR vẫn bị tắt trừ khi danh sách cho phép CIDR/IP đáng tin cậy được cấu hình rõ ràng.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`Các CIDR tự động phê duyệt ghép nối nút Gateway`},help:{"v1-1m6jsxj-6x":`Danh sách cho phép CIDR/IP tùy chọn để tự động phê duyệt lần ghép nối đầu tiên của thiết bị có vai trò nút và không yêu cầu phạm vi quyền nào. Bị tắt khi chưa được thiết lập. Việc ghép nối của người vận hành, trình duyệt, Control UI và mọi trường hợp ghép nối để nâng cấp vai trò, phạm vi quyền, siêu dữ liệu hoặc khóa công khai vẫn cần được phê duyệt thủ công.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Tự động phê duyệt ghép nối nút Gateway cục bộ`},help:{"v1-glzm36-41":`Tự động phê duyệt ngầm việc ghép nối và nâng cấp quyền truy cập cục bộ đáng tin cậy (mặc định: true); đặt thành false để yêu cầu phê duyệt rõ ràng cho từng thiết bị thay vì ưu tiên sự tiện lợi.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Xác minh SSH khi ghép nối nút Gateway`},help:{"v1-1e4da92-ct":"Tự động phê duyệt có xác minh SSH cho lần ghép nối đầu tiên của thiết bị có vai trò nút (mặc định: bật). Gateway kết nối SSH ngược lại máy chủ đang ghép nối (BatchMode, kiểm tra nghiêm ngặt khóa máy chủ) và chỉ phê duyệt khi đầu ra của `openclaw node identity` từ xa khớp với khóa của thiết bị đang chờ phê duyệt. Đặt thành false để tắt xác minh SSH (độc lập với autoApproveCidrs, vốn vẫn hoạt động); để chỉ cho phép ghép nối thủ công, hãy bỏ thiết lập autoApproveCidrs. Truyền một đối tượng để ghi đè user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Công cụ plugin của nút Gateway`},help:{"v1-1c24iq3-28":`Kiểm soát việc các nút đã ghép nối có được phép công bố bản mô tả công cụ plugin mà tác nhân có thể thấy hay không.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Bật công cụ plugin của nút Gateway`},help:{"v1-14lgfu6-47":`Chấp nhận các bản mô tả công cụ plugin hiển thị cho tác nhân do các nút đã ghép đôi công bố (mặc định: true). Đặt thành false để bỏ qua và xóa tất cả công cụ plugin do các nút công bố.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Cổng Gateway`},help:{"v1-for8t5-54":`Cổng TCP mà trình lắng nghe của Gateway sử dụng cho API, Control UI và các đường dẫn tiếp nhận từ kênh. Sử dụng cổng riêng và tránh xung đột với proxy ngược hoặc các dịch vụ phát triển cục bộ.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Cổng thông tin Gateway`},help:{"v1-1v2lkw9-1c":`Cài đặt xuất bản cổng thông tin và điểm truy cập vào riêng tư.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Điểm truy cập vào cổng thông tin riêng tư`},help:{"v1-20w4gq-69":`Proxy ngược HTTPS ký tự đại diện riêng tư, tùy chọn, do người vận hành quản lý. Chuyển tiếp Host gốc, đường dẫn và yêu cầu nâng cấp WebSocket đến trình lắng nghe loopback chuyên dụng. Vẫn bắt buộc xác thực bằng mã thông báo bearer cho cổng thông tin. Cần khởi động lại Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Tên miền ký tự đại diện của cổng thông tin`},help:{"v1-1ipbfad-53":`Tên miền DNS thuần cho các tên miền phụ ngẫu nhiên của cổng thông tin (ví dụ previews.example.net). Cấu hình DNS ký tự đại diện và HTTPS ở chế độ riêng tư; không dùng chung không gian tên máy chủ của Gateway hoặc Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Cổng loopback cho điểm truy cập vào cổng thông tin`},help:{"v1-1mb98cv-4g":`Cổng HTTP loopback chuyên dụng nhận lưu lượng từ proxy HTTPS ký tự đại diện riêng tư. Phải khác với cổng Gateway. Đây là cổng backend, không phải cổng HTTPS công khai.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Origin công khai của Gateway`},help:{"v1-17vekvx-87":`Origin HTTPS của Gateway có thể truy cập từ bên ngoài. HTTP chỉ được phép dùng cho localhost, 127.0.0.1 hoặc [::1]. MCP OAuth cho từng bên yêu cầu sử dụng origin này để tạo URL gọi lại tại /oauth/mcp/callback; các liên kết phiên kênh và liên kết trình xem do plugin tạo sử dụng origin này để truy cập Control UI và các tuyến của Gateway.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Gửi thông báo đẩy qua Gateway`},help:{"v1-h23oz7-5s":`Cài đặt gửi thông báo đẩy được Gateway sử dụng khi cần đánh thức hoặc thông báo cho các thiết bị đã ghép đôi. Cấu hình APNs qua máy chủ chuyển tiếp tại đây cho các bản dựng iOS chính thức; xác thực APNs trực tiếp vẫn sử dụng biến môi trường cho các bản dựng cục bộ/thủ công.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Gửi qua APNs của Gateway`},help:{"v1-4bbafr-4e":`Cài đặt gửi qua APNs cho các thiết bị iOS đã ghép đôi với Gateway này. Sử dụng cài đặt máy chủ chuyển tiếp cho các bản dựng App Store chính thức đăng ký qua máy chủ chuyển tiếp thông báo đẩy bên ngoài.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Máy chủ chuyển tiếp APNs của Gateway`},help:{"v1-7glbel-6x":`Cài đặt dịch vụ chuyển tiếp bên ngoài để gửi APNs qua dịch vụ chuyển tiếp. Theo mặc định, Gateway dùng dịch vụ chuyển tiếp OpenClaw được lưu trữ sẵn, hoặc dùng dịch vụ chuyển tiếp tùy chỉnh này cho push.test, tín hiệu đánh thức và đánh thức để kết nối lại sau khi một bản dựng iOS chính thức đã ghép đôi công bố đăng ký sử dụng dịch vụ chuyển tiếp.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`URL cơ sở của dịch vụ chuyển tiếp APNs cho Gateway`},help:{"v1-1o8mgnq-69":`URL HTTPS cơ sở tùy chỉnh, không bắt buộc, cho dịch vụ chuyển tiếp APNs bên ngoài được các bản dựng iOS chính thức trên App Store sử dụng. Đảm bảo URL này khớp với URL dịch vụ chuyển tiếp được tích hợp sẵn trong bản dựng iOS để lưu lượng đăng ký và gửi đều đến cùng một bản triển khai.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Thời gian chờ dịch vụ chuyển tiếp APNs của Gateway (ms)`},help:{"v1-a0jkb1-4z":`Thời gian chờ tính bằng mili giây cho các yêu cầu gửi từ Gateway đến dịch vụ chuyển tiếp APNs (mặc định: 10000). Tăng giá trị này nếu dịch vụ chuyển tiếp hoặc mạng chậm, hoặc giảm để kết thúc các lần thử đánh thức không thành công sớm hơn.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Tải lại cấu hình`},help:{"v1-d02mvq-4w":`Chính sách tải lại cấu hình trực tiếp, quy định cách áp dụng các chỉnh sửa và thời điểm kích hoạt khởi động lại toàn bộ. Giữ chế độ kết hợp để cập nhật vận hành an toàn nhất, trừ khi đang gỡ lỗi cơ chế tải lại nội bộ.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Chế độ tải lại cấu hình`},help:{"v1-1q1etcf-3m":`Kiểm soát cách áp dụng các chỉnh sửa cấu hình: "off" bỏ qua các chỉnh sửa trực tiếp, còn "hybrid" áp dụng những thay đổi có thể cập nhật nóng an toàn rồi khởi động lại khi cần.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Gateway từ xa`},help:{"v1-6xv7gd-5a":`Cài đặt kết nối Gateway từ xa qua kết nối trực tiếp hoặc SSH khi phiên bản này làm proxy đến một máy chủ chạy khác. Chỉ dùng chế độ từ xa khi đã chủ động cấu hình hoạt động trên các máy chủ riêng biệt.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Header xác thực biên của Gateway từ xa`},help:{"v1-jg9p7d-5o":`Các header HTTP lấy giá trị từ bí mật, được gửi tới proxy nhận biết danh tính phía trước Gateway từ xa đã cấu hình. Các header chỉ được gửi tới đúng origin của gateway.remote.url qua WSS và không bao giờ đi theo chuyển hướng.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Mật khẩu Gateway từ xa`},help:{"v1-16jc0yx-7y":`Bí mật dùng chung được gửi trong trường mật khẩu để xác thực máy khách này với Gateway từ xa. gateway.auth.mode của máy chủ chọn bí mật đã cấu hình; cả trường token lẫn trường mật khẩu của máy khách đều được chấp nhận. Hãy quản lý bí mật này bên ngoài và tránh lưu giá trị dạng văn bản thuần trong cấu hình được commit.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Chính sách khóa máy chủ SSH của Gateway từ xa`},help:{"v1-7qoxtb-49":`Chính sách xác minh khóa máy chủ SSH trên macOS. "strict" yêu cầu khóa máy chủ đã được tin cậy; "openssh" ủy quyền rõ ràng cho cấu hình OpenSSH đang có hiệu lực.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Danh tính SSH của Gateway từ xa`},help:{"v1-hz2hsm-1f":`Đường dẫn tệp danh tính SSH tùy chọn (được truyền cho ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Đích SSH của Gateway từ xa`},help:{"v1-85w39w-2t":`Gateway từ xa qua SSH (tạo đường hầm từ cổng Gateway tới localhost). Định dạng: user@host hoặc user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Dấu vân tay TLS của Gateway từ xa`},help:{"v1-1ri16lk-23":`Dấu vân tay TLS sha256 dự kiến của Gateway từ xa (ghim để tránh tấn công MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token Gateway từ xa`},help:{"v1-1pb9q8w-7v":`Bí mật dùng chung được gửi trong trường token để xác thực máy khách này với Gateway từ xa. gateway.auth.mode của máy chủ chọn bí mật đã cấu hình; chấp nhận cả trường token lẫn trường password của máy khách. Lưu trữ bằng cơ chế thay thế bí mật/biến môi trường và luân chuyển khi thay đổi cấu hình xác thực của Gateway từ xa.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Phương thức truyền tải của Gateway từ xa`},help:{"v1-1acfs7m-54":`Phương thức truyền tải kết nối từ xa: "direct" sử dụng kết nối qua URL đã cấu hình, còn "ssh" tạo đường hầm qua SSH. Sử dụng SSH khi cần đường hầm mã hóa mà không để lộ các cổng từ xa.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL của Gateway từ xa`},help:{"v1-va7exe-1b":`URL WebSocket của Gateway từ xa (ws:// hoặc wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Vai trò người vận hành Gateway`},help:{"v1-b59sc5-6w":`Các vai trò người vận hành tùy chọn gắn với hồ sơ cho Gateway của nhóm. Mỗi vai trò được đặt tên kiểm soát quyền truy cập phiên của người khác, khả năng cô lập sandbox, các tác nhân dùng cho phiên và lượt chạy, cùng các phạm vi quyền được cấp cho người vận hành; bỏ qua phần này sẽ giữ nguyên hành vi hiện có của người vận hành.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Vai trò người vận hành mặc định`},help:{"v1-1v8add8-4u":`Vai trò bắt buộc được gán cho các hồ sơ đã xác thực nhưng chưa được gán vai trò cụ thể hợp lệ khi vai trò người vận hành được cấu hình. Tên vai trò này phải khớp với một định nghĩa vai trò đã cấu hình.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Định nghĩa vai trò người vận hành`},help:{"v1-uv91an-53":`Các định nghĩa vai trò không rỗng do quản trị viên đặt tên, tập hợp các chính sách thuộc bộ cố định về chia sẻ phiên, cô lập sandbox, truy cập tác nhân và phạm vi quyền của người vận hành được áp dụng cho hồ sơ người dùng đã xác thực.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Định nghĩa vai trò người vận hành`},help:{"v1-p8tfws-6q":`Một vai trò người vận hành có tên. Mỗi định nghĩa phải chỉ rõ chính sách chia sẻ phiên, các tác nhân được phép dùng cho phiên và lượt chạy, cùng giới hạn phạm vi quyền của người vận hành; đồng thời có thể yêu cầu cách ly trong sandbox cho các phiên mới tạo và một chính sách truy cập qua plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plugin chính sách truy cập cho vai trò người vận hành`},help:{"v1-1gq4q08-9n":`ID plugin chính xác, không bắt buộc, có chính sách truy cập Gateway phải cấp quyền cho vai trò này. Quyền truy cập bị từ chối khi plugin bị thiếu, bị tắt, không tải được hoặc không cung cấp thẩm quyền hiện hành. ID của các plugin không khả dụng vẫn được coi là cấu hình hợp lệ để các vai trò nhân viên độc lập và chủ sở hữu Gateway có thể khôi phục quyền truy cập. Bỏ qua trường này sẽ không tạo thêm sự phụ thuộc vào plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Tác nhân được phép cho vai trò người vận hành`},help:{"v1-fvun18-4v":`Các tác nhân khả dụng khi vai trò này tạo phiên hoặc bắt đầu lượt chạy: đặt "*" để cho phép mọi tác nhân, liệt kê ID tác nhân để chỉ cho phép các tác nhân đó, hoặc dùng danh sách trống để vô hiệu hóa cả hai thao tác.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Cách ly bằng sandbox cho vai trò người vận hành`},help:{"v1-sknx21-66":`Cách ly thực thi cho các phiên mới tạo: "inherit" (mặc định) dùng chính sách của tác nhân; "required" luôn bắt buộc dùng sandbox, ngay cả khi chế độ sandbox của tác nhân bị tắt, và chặn thực thi nếu hệ thống phụ trợ không khả dụng.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Giới hạn phạm vi quyền của vai trò người vận hành`},help:{"v1-1selr2i-4s":`Danh sách cố định các phạm vi quyền của người vận hành, xác định quyền hạn kết nối tối đa của vai trò này. Các phạm vi quyền được yêu cầu, được cấp qua ghép nối, được cấp theo danh tính và được nâng cấp đều được lấy giao với danh sách này.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Quyền truy cập phiên của vai trò người vận hành`},help:{"v1-hsoiop-45":`Các quyền chia sẻ phiên được cấp cho vai trò này đối với các phiên do những người đã xác thực khác tạo; mỗi người vẫn có quyền truy cập các phiên của chính mình với tư cách chủ sở hữu.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Quyền truy cập các phiên khác của vai trò người vận hành`},help:{"v1-vf8umx-5r":`Quyền truy cập vào phiên của người khác: "none" ẩn các phiên đó, "view" cho phép đọc, "suggest" cho phép thực hiện quy trình đề xuất và "write" cho phép tham gia. Tư cách thành viên được chỉ định rõ trong phiên có thể cấp thêm quyền truy cập.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale của Gateway`},help:{"v1-6ar9o-4x":`Cài đặt tích hợp Tailscale để cung cấp quyền truy cập qua Serve/Funnel và xử lý vòng đời khi Gateway khởi động/thoát. Giữ ở trạng thái tắt trừ khi hệ thống triển khai của bạn chủ đích sử dụng Tailscale cho lưu lượng truy cập vào.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Chế độ Tailscale của Gateway`},help:{"v1-6l2099-5a":`Chế độ công bố của Tailscale: "off", "serve" hoặc "funnel" để cung cấp đường truy cập riêng tư hoặc công khai. Dùng "serve" để chỉ cho phép truy cập trong tailnet và chỉ dùng "funnel" khi cần cho phép truy cập từ Internet công cộng.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Cơ chế bảo vệ khi chuyển đổi Funnel bên ngoài cho Tailscale của Gateway`},help:{"v1-1mntkor-7q":`Cơ chế bảo vệ khi chuyển đổi dành cho mode='serve', hiện không còn được khuyến nghị sử dụng. Nếu một Funnel bên ngoài vẫn trỏ đến trình lắng nghe Gateway thông thường, OpenClaw giữ nguyên cách cung cấp quyền truy cập và cảnh báo rằng chỉ các webhook được xác thực qua plugin còn dùng được cho đến khi cấu hình xác thực bằng mật khẩu và chuyển mode sang 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Terminal dành cho người vận hành`},help:{"v1-18f5rgm-8b":`Terminal dành cho người vận hành được cung cấp cho Control UI và ứng dụng di động: một shell dựa trên PTY trên máy chủ Gateway, chỉ dành cho các phiên của người vận hành có phạm vi quyền quản trị. Terminal khởi động trong không gian làm việc của tác tử đích và từ chối hoạt động với các tác tử được cách ly hoàn toàn trong sandbox (sandbox.mode 'all'), thay vì cung cấp một shell không bị giới hạn trên máy chủ.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Thời gian chờ hết hạn của phiên tách rời trong terminal dành cho người vận hành`},help:{"v1-k6qbgr-9e":`Số giây một phiên terminal tiếp tục tồn tại sau khi mất kết nối (máy tính xách tay chuyển sang chế độ ngủ, tải lại trang), vẫn có thể kết nối lại qua terminal.attach và phát lại đầu ra gần đây. Đặt thành 0 để kết thúc phiên ngay khi mất kết nối. Mặc định: 300 (5 phút). Các phiên đã ngắt kết nối vẫn tiếp tục chạy lệnh, vì vậy hãy rút ngắn thời gian này trên máy chủ dùng chung hoặc có thể truy cập từ bên ngoài.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Bật terminal cho người vận hành`},help:{"v1-1nez06v-7p":`Bật terminal cho người vận hành trên các máy khách có phạm vi quyền quản trị (mặc định: true). Tính năng này cung cấp shell trên trình duyệt/thiết bị di động với môi trường của tiến trình Gateway; đặt thành false để tắt trên các hệ thống triển khai mà người vận hành có quyền quản trị không nên được truy cập shell của máy chủ. Các thay đổi có hiệu lực mà không cần khởi động lại Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Shell của terminal cho người vận hành`},help:{"v1-19mfe6t-5i":`Tệp thực thi shell mà terminal cho người vận hành khởi chạy. Để trống để dùng shell đăng nhập của máy chủ ($SHELL trên Unix, %ComSpec% trên Windows), hoặc chỉ định cố định một trình thông dịch để có môi trường vận hành nhất quán.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS của Gateway`},help:{"v1-1dx77dq-4z":`Cài đặt chứng chỉ và khóa TLS để xử lý kết nối HTTPS trực tiếp trong tiến trình Gateway. Sử dụng chứng chỉ được chỉ định rõ ràng trong môi trường sản xuất và tránh để lộ dữ liệu dạng văn bản thuần trên các mạng không đáng tin cậy.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Tự động tạo chứng chỉ TLS cho Gateway`},help:{"v1-1ld6uiu-4w":`Tự động tạo cặp chứng chỉ/khóa TLS cục bộ khi chưa cấu hình các tệp cụ thể. Chỉ sử dụng cho thiết lập cục bộ/phát triển và thay bằng chứng chỉ thực cho lưu lượng trong môi trường sản xuất.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Đường dẫn CA TLS của Gateway`},help:{"v1-andqlu-52":`Đường dẫn tùy chọn đến gói CA để xác minh máy khách hoặc đáp ứng yêu cầu về chuỗi tin cậy tùy chỉnh tại biên Gateway. Sử dụng khi triển khai có PKI riêng hoặc chuỗi chứng chỉ tùy chỉnh.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Đường dẫn chứng chỉ TLS của Gateway`},help:{"v1-1wznaof-4q":`Đường dẫn trên hệ thống tệp đến tệp chứng chỉ TLS mà Gateway sử dụng khi bật TLS. Sử dụng đường dẫn chứng chỉ được quản lý và đảm bảo quy trình gia hạn tự động luôn dùng đúng vị trí này.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`Bật TLS cho Gateway`},help:{"v1-ykhwp0-4o":`Bật kết thúc TLS tại điểm lắng nghe của Gateway để máy khách kết nối trực tiếp qua HTTPS/WSS. Duy trì bật khi cho phép truy cập trực tiếp từ Internet hoặc tại bất kỳ ranh giới mạng không đáng tin cậy nào.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Đường dẫn khóa TLS của Gateway`},help:{"v1-15knri0-4i":`Đường dẫn trên hệ thống tệp đến tệp khóa riêng TLS mà Gateway sử dụng khi bật TLS. Hạn chế quyền truy cập vào tệp khóa này và luân chuyển khóa theo chính sách bảo mật của bạn.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Chính sách cung cấp công cụ của Gateway`},help:{"v1-1ffol26-5a":`Chính sách cho phép/từ chối cung cấp công cụ ở cấp Gateway, có thể giới hạn các công cụ khả dụng trong thời gian chạy, độc lập với hồ sơ tác nhân/công cụ. Sử dụng để kiểm soát khẩn cấp ở mức tổng thể và tăng cường bảo mật cho môi trường vận hành thực tế.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Danh sách công cụ được phép của Gateway`},help:{"v1-163khb1-4y":`Danh sách công cụ được phép chỉ định rõ ở cấp Gateway khi bạn chỉ muốn một nhóm công cụ hạn chế khả dụng trong thời gian chạy. Sử dụng cho các môi trường bị hạn chế nghiêm ngặt, nơi phạm vi công cụ phải được kiểm soát chặt chẽ.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Danh sách công cụ bị chặn của Gateway`},help:{"v1-1lhssnf-4o":`Danh sách từ chối công cụ tường minh ở cấp Gateway để chặn các công cụ rủi ro ngay cả khi chính sách cấp thấp hơn cho phép. Sử dụng quy tắc từ chối để ứng phó khẩn cấp và tăng cường bảo mật theo chiều sâu.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`Các CIDR proxy đáng tin cậy của Gateway`},help:{"v1-n5zcvf-4f":`Danh sách CIDR/IP cho phép của các proxy phía trước được phép cung cấp tiêu đề chuyển tiếp danh tính máy khách. Giới hạn danh sách này để các trạm trung chuyển không đáng tin cậy không thể mạo danh người dùng.`}},hooks:{label:{"v1-j9ywl7-5":`Hook`},help:{"v1-1mzh0ry-5v":`Giao diện tự động hóa webhook đầu vào để ánh xạ các sự kiện bên ngoài thành thao tác đánh thức hoặc hành động của tác tử trong OpenClaw. Hãy bảo vệ chặt chẽ giao diện này bằng các biện pháp kiểm soát token/phiên/tác tử tường minh trước khi cho phép truy cập từ bên ngoài các mạng đáng tin cậy.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Các ID tác tử được phép cho hook`},help:{"v1-hree88-7c":`Danh sách cho phép các ID tác tử thực tế mà yêu cầu và ánh xạ hook được phép nhắm đến, bao gồm cả việc định tuyến đến tác tử mặc định khi bỏ qua agentId. Sử dụng danh sách này để giới hạn các sự kiện tự động hóa vào các tác tử dịch vụ chuyên dụng và giảm phạm vi ảnh hưởng nếu token hook bị lộ.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Các tiền tố khóa phiên được phép cho hook`},help:{"v1-b346oh-4r":`Danh sách cho phép các tiền tố khóa phiên được chấp nhận cho yêu cầu hook đầu vào khi bật khóa do bên gọi cung cấp. Sử dụng các tiền tố có phạm vi hẹp để ngăn việc chèn khóa phiên tùy ý.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Cho phép khóa phiên trong yêu cầu hook`},help:{"v1-11n9ps-52":`Cho phép bên gọi cung cấp khóa phiên trong yêu cầu hook khi đặt thành true, nhờ đó bên gọi có thể kiểm soát việc định tuyến. Giữ giá trị false trừ khi bên tích hợp đáng tin cậy có nhu cầu rõ ràng về cách phân luồng phiên tùy chỉnh.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Khóa phiên mặc định cho hook`},help:{"v1-bzdgkn-57":`Khóa phiên dự phòng dùng để chuyển dữ liệu qua hook khi yêu cầu không cung cấp khóa qua các kênh được phép. Sử dụng khóa ổn định nhưng có phạm vi giới hạn để tránh trộn lẫn các cuộc hội thoại tự động hóa không liên quan.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Bật hook`},help:{"v1-1mixmjf-4n":`Bật điểm cuối hook và quy trình thực thi ánh xạ cho các yêu cầu webhook đến. Giữ ở trạng thái tắt trừ khi bạn đang chủ động định tuyến các sự kiện bên ngoài vào gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Hook Gmail`},help:{"v1-4cibmt-4r":`Cài đặt tích hợp thông báo đẩy Gmail dùng cho thông báo Pub/Sub và tùy chọn phục vụ yêu cầu gọi lại cục bộ. Nếu có thể, hãy giới hạn phạm vi này trong các tài khoản Gmail chuyên dùng cho tự động hóa.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Tài khoản hook Gmail`},help:{"v1-12l1h96-4v":`Mã định danh tài khoản Google dùng cho các thao tác theo dõi/đăng ký Gmail trong tích hợp hook này. Sử dụng tài khoản hộp thư chuyên dùng cho tự động hóa để tách biệt quyền vận hành.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Cho phép nội dung bên ngoài không an toàn trong hook Gmail`},help:{"v1-1w3gdvs-55":`Khi bật, cho phép đưa nội dung Gmail bên ngoài chưa được làm sạch kỹ vào quy trình xử lý. Giữ ở trạng thái tắt để có thiết lập mặc định an toàn hơn và chỉ bật cho các luồng thư đáng tin cậy có quy trình chuyển đổi được kiểm soát.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`URL gọi lại của hook Gmail`},help:{"v1-19fhn6q-4z":`URL gọi lại công khai mà Gmail hoặc các bên trung gian gọi để chuyển thông báo vào quy trình hook này. Bảo vệ URL này bằng cách xác thực token và hạn chế khả năng truy cập qua mạng.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Bao gồm nội dung thư trong hook Gmail`},help:{"v1-14cf1c3-52":`Khi đặt thành true, truy xuất và đưa nội dung email vào để ánh xạ hoặc xử lý bằng tác tử ở các bước sau. Giữ ở false trừ khi cần nội dung email, vì tùy chọn này làm tăng kích thước và độ nhạy cảm của dữ liệu gửi đi.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Nhãn hook Gmail`},help:{"v1-9zpdg8-4g":`Bộ lọc nhãn Gmail tùy chọn, giới hạn những thư có nhãn nào sẽ kích hoạt sự kiện hook. Giữ phạm vi lọc hẹp để tránh làm quá tải các quy trình tự động hóa bằng thư không liên quan trong hộp thư đến.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Số byte nội dung tối đa của hook Gmail`},help:{"v1-2aaxx1-4b":`Số byte dữ liệu Gmail tối đa được xử lý cho mỗi sự kiện khi bật includeBody. Đặt giới hạn vừa phải để giảm chi phí và rủi ro khi xử lý thư quá lớn.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Ghi đè mô hình cho hook Gmail`},help:{"v1-1var65t-59":`Tùy chọn ghi đè mô hình cho các lần chạy do Gmail kích hoạt khi quy trình tự động hóa hộp thư cần hành vi mô hình chuyên biệt. Để trống để kế thừa cài đặt mặc định của tác tử, trừ khi các tác vụ hộp thư cần được chuyên biệt hóa.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Mã thông báo đẩy của hook Gmail`},help:{"v1-h1vx01-4o":`Mã thông báo bí mật dùng chung, bắt buộc có trong các lệnh gọi lại của hook đẩy Gmail trước khi xử lý thông báo. Sử dụng phép thế biến môi trường và thay mã định kỳ nếu các điểm cuối gọi lại được công khai ra bên ngoài.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Khoảng thời gian gia hạn hook Gmail (phút)`},help:{"v1-pr1z9-49":`Chu kỳ gia hạn tính bằng phút cho các đăng ký theo dõi Gmail để tránh hết hạn. Đặt ngắn hơn thời hạn hết hạn của nhà cung cấp và theo dõi các lỗi gia hạn trong nhật ký.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Máy chủ cục bộ của hook Gmail`},help:{"v1-hom4wq-54":`Khối cài đặt máy chủ callback cục bộ để nhận trực tiếp thông báo Gmail mà không cần lớp tiếp nhận lưu lượng riêng. Chỉ bật khi tiến trình này cần tự tiếp nhận và xử lý lưu lượng webhook.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Địa chỉ lắng nghe của máy chủ hook Gmail`},help:{"v1-55bieu-4d":`Địa chỉ lắng nghe của máy chủ HTTP callback Gmail cục bộ khi phục vụ hook trực tiếp. Chỉ dùng địa chỉ loopback trừ khi chủ động yêu cầu tiếp nhận lưu lượng từ bên ngoài.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Đường dẫn máy chủ hook Gmail`},help:{"v1-1jqhcw4-4h":`Đường dẫn HTTP trên máy chủ callback Gmail cục bộ để tiếp nhận thông báo đẩy. Giữ đường dẫn này nhất quán với cấu hình đăng ký để tránh bỏ lỡ sự kiện.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Cổng máy chủ hook Gmail`},help:{"v1-1yku7dz-43":`Cổng cho máy chủ HTTP callback Gmail cục bộ khi bật chế độ phục vụ. Dùng cổng riêng để tránh xung đột với các giao diện Gateway/điều khiển.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Đăng ký hook Gmail`},help:{"v1-127h8vg-5b":`Đăng ký Pub/Sub được Gateway sử dụng để nhận thông báo thay đổi Gmail từ chủ đề đã cấu hình. Xác định rõ bên sở hữu đăng ký để tránh nhiều bên tiêu thụ tranh chấp ngoài dự kiến.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale cho hook Gmail`},help:{"v1-7jzidp-4l":`Khối cấu hình khả năng truy cập qua Tailscale để cung cấp callback Gmail qua các tuyến Serve/Funnel. Sử dụng các chế độ tailnet riêng tư trước khi bật bất kỳ đường tiếp nhận lưu lượng công khai nào.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Chế độ Tailscale cho hook Gmail`},help:{"v1-vhm395-4u":`Chế độ cung cấp quyền truy cập qua Tailscale cho các lệnh gọi lại Gmail: "off", "serve" hoặc "funnel". Dùng "serve" để chuyển tiếp trong tailnet riêng tư và chỉ dùng "funnel" khi cần nhận lưu lượng từ internet công cộng.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Đường dẫn Tailscale cho hook Gmail`},help:{"v1-fr8qi-4m":`Đường dẫn do Tailscale Serve/Funnel cung cấp để chuyển tiếp các lệnh gọi lại Gmail khi được bật. Đảm bảo đường dẫn này khớp với cấu hình webhook Gmail để yêu cầu đến đúng trình xử lý.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Đích Tailscale cho hook Gmail`},help:{"v1-1twwxge-47":`Đích dịch vụ cục bộ mà Tailscale Serve/Funnel chuyển tiếp đến (ví dụ: http://127.0.0.1:8787). Dùng đích loopback rõ ràng để tránh định tuyến không rõ ràng.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Ghi đè mức suy luận cho hook Gmail`},help:{"v1-17owk9q-4z":`Ghi đè mức độ suy luận cho các lần chạy tác nhân do Gmail kích hoạt: "off", "minimal", "low", "medium" hoặc "high". Duy trì mức mặc định vừa phải cho các quy trình tự động hóa hộp thư thường lệ để kiểm soát chi phí và độ trễ.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Chủ đề Pub/Sub cho hook Gmail`},help:{"v1-iled0e-4p":`Tên chủ đề Google Pub/Sub mà tính năng theo dõi Gmail dùng để phát thông báo thay đổi cho tài khoản này. Đảm bảo IAM của chủ đề cấp quyền phát thông báo cho Gmail trước khi bật tính năng theo dõi.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Hook nội bộ`},help:{"v1-piq9k-4v":`Cài đặt thực thi hook nội bộ cho các trình xử lý sự kiện đi kèm hoặc tùy chỉnh được tải từ đường dẫn mô-đun. Dùng cài đặt này cho các quy trình tự động hóa đáng tin cậy chạy trong cùng tiến trình và giới hạn chặt chẽ phạm vi tải trình xử lý.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Bật hook nội bộ`},help:{"v1-1wv0289-4c":`Bật xử lý các hook nội bộ và các mục đã cấu hình trong môi trường thực thi hook nội bộ. Giữ ở trạng thái tắt trừ khi bạn chủ động cấu hình các hook nội bộ.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Các mục hook nội bộ`},help:{"v1-1ovi38l-4o":`Các bản ghi mục hook nội bộ đã cấu hình, dùng để đăng ký các trình xử lý cụ thể trong môi trường thực thi cùng siêu dữ liệu. Khai báo rõ ràng các mục và quản lý phiên bản để có thể kiểm tra hành vi trong môi trường vận hành thực tế.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Trình nạp hook nội bộ`},help:{"v1-11re5ph-4p":`Cài đặt trình nạp hook nội bộ kiểm soát nơi tìm các mô-đun xử lý khi khởi động. Giới hạn các thư mục gốc dùng để nạp nhằm giảm xung đột hoặc che khuất mô-đun ngoài ý muốn.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Thư mục bổ sung cho hook nội bộ`},help:{"v1-1xfdqxg-4c":`Các thư mục bổ sung để tìm mô-đun hook nội bộ ngoài các đường dẫn nạp mặc định. Giữ số lượng thư mục ở mức tối thiểu và kiểm soát chặt chẽ để giảm việc che khuất mô-đun ngoài ý muốn.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Ánh xạ hook`},help:{"v1-frhp3v-5i":`Các quy tắc ánh xạ có thứ tự dùng để đối chiếu yêu cầu hook đến và chọn hành động đánh thức hoặc xử lý bằng tác nhân, kèm tùy chọn định tuyến gửi. Đặt các ánh xạ cụ thể lên trước để tránh các quy tắc mẫu quá rộng khớp với mọi yêu cầu.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Hành động ánh xạ hook`},help:{"v1-1r5zt5f-5f":`Loại hành động ánh xạ: "wake" kích hoạt luồng đánh thức tác nhân, còn "agent" chuyển trực tiếp đến tác nhân để xử lý. Dùng "agent" để thực thi ngay và "wake" khi muốn ưu tiên xử lý theo nhịp định kỳ.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`ID tác nhân ánh xạ hook`},help:{"v1-l0uioz-4y":`ID tác nhân đích để thực thi ánh xạ khi định tuyến hành động không nên dùng giá trị mặc định. Sử dụng các tác nhân tự động hóa chuyên biệt để tách biệt hoạt động của webhook khỏi các phiên tương tác của người vận hành.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Cho phép nội dung bên ngoài không an toàn trong ánh xạ hook`},help:{"v1-1np9426-57":`Khi đặt thành true, nội dung ánh xạ có thể đưa dữ liệu payload bên ngoài chưa được làm sạch kỹ vào các tin nhắn được tạo. Giữ giá trị mặc định là false và chỉ bật cho các nguồn đáng tin cậy có logic biến đổi đã được rà soát.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Kênh gửi của ánh xạ hook`},help:{"v1-oz7pu5-5s":`Giá trị ghi đè kênh gửi cho đầu ra của ánh xạ (ví dụ: "last", "telegram", "discord", "slack", "signal", "imessage" hoặc "msteams"). Chỉ định rõ các giá trị ghi đè kênh để tránh vô tình gửi nhầm sang kênh khác.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Gửi phản hồi của ánh xạ hook`},help:{"v1-12tbbam-5o":`Kiểm soát việc kết quả thực thi ánh xạ được gửi về một đích trên kênh hay chỉ được xử lý âm thầm. Tắt tính năng gửi đối với các quy trình tự động hóa chạy nền không nên đăng đầu ra cho người dùng.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Khóa phân nhánh của ánh xạ hook`},help:{"v1-1d593op-7e":`Khóa mảng ở cấp cao nhất trong payload mà ánh xạ dùng để phân nhánh: mỗi phần tử kích hoạt một hành động riêng, và các mẫu hoặc phép biến đổi nhận được payload có mảng chỉ chứa phần tử hiện tại. Cấu hình sẵn Gmail sử dụng forEach: messages để mỗi đợt thông báo đẩy theo lô kích hoạt một lượt chạy cho từng email.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID ánh xạ hook`},help:{"v1-q1t4zw-57":`Mã định danh ổn định, không bắt buộc cho một mục ánh xạ hook, dùng để kiểm toán, khắc phục sự cố và cập nhật có mục tiêu. Sử dụng các ID duy nhất để nhật ký và bản so sánh cấu hình có thể tham chiếu đến các ánh xạ một cách rõ ràng.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Điều kiện khớp ánh xạ hook`},help:{"v1-6u73k2-5a":`Đối tượng nhóm các điều kiện khớp ánh xạ như đường dẫn và nguồn trước khi áp dụng định tuyến hành động. Đặt tiêu chí khớp cụ thể để lưu lượng webhook không liên quan không kích hoạt các quy trình tự động hóa.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Đường dẫn khớp ánh xạ hook`},help:{"v1-1d7dc5j-4k":`Điều kiện khớp đường dẫn cho một ánh xạ hook, thường được so sánh với đường dẫn của yêu cầu đến. Sử dụng điều kiện này để phân chia hành vi tự động hóa theo các nhóm đường dẫn điểm cuối webhook.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Nguồn khớp ánh xạ hook`},help:{"v1-177zgy7-52":`Điều kiện khớp nguồn cho một ánh xạ hook, thường được thiết lập dựa trên siêu dữ liệu đáng tin cậy từ phía thượng nguồn hoặc logic của bộ điều hợp. Sử dụng mã định danh nguồn ổn định để định tuyến luôn nhất quán qua các lần thử lại.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Mẫu tin nhắn ánh xạ hook`},help:{"v1-ggqszl-5c":`Mẫu để tổng hợp dữ liệu đầu vào có cấu trúc của ánh xạ thành nội dung tin nhắn cuối cùng được gửi đến tuyến hành động đích. Giữ cho mẫu tạo ra kết quả nhất quán để việc phân tích cú pháp và hành vi ở phía hạ nguồn luôn ổn định.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Ghi đè mô hình ánh xạ hook`},help:{"v1-10qyo4j-5e":`Tùy chọn ghi đè mô hình cho các lượt chạy do ánh xạ kích hoạt khi quy trình tự động hóa cần dùng mô hình khác với mô hình mặc định của tác nhân. Hạn chế sử dụng để hành vi vẫn nhất quán và dễ dự đoán giữa các lần thực thi ánh xạ.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Tên ánh xạ hook`},help:{"v1-zrd9tn-4v":`Tên hiển thị dễ đọc của ánh xạ, dùng trong chẩn đoán và giao diện cấu hình dành cho người vận hành. Đặt tên ngắn gọn, rõ nghĩa để dễ nhận biết mục đích định tuyến khi xem xét sự cố.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Khóa phiên của ánh xạ hook`},help:{"v1-lfnt1n-58":`Giá trị ghi đè khóa phiên được chỉ định rõ cho các tin nhắn được gửi qua ánh xạ nhằm kiểm soát tính liên tục của luồng hội thoại. Dùng khóa ổn định, có phạm vi xác định để liên kết các sự kiện lặp lại mà không làm rò rỉ ngữ cảnh sang các cuộc hội thoại không liên quan.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Chế độ phiên của ánh xạ hook`},help:{"v1-1ggtdze-5k":`Kiểm soát tính liên tục của phiên ánh xạ: "isolated" bắt đầu một phiên chạy mới, còn "persistent" sử dụng lại sessionKey đã được xác định. Giữ chế độ isolated trừ khi tích hợp chủ đích yêu cầu ngữ cảnh được duy trì lâu dài.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Mẫu văn bản của ánh xạ hook`},help:{"v1-1rg732b-4y":`Mẫu dự phòng chỉ chứa văn bản, dùng khi không muốn hoặc không hỗ trợ hiển thị nội dung dữ liệu có định dạng phong phú. Dùng mẫu này để cung cấp chuỗi tóm tắt ngắn gọn, nhất quán cho các giao diện nhận tin nhắn trò chuyện.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Ghi đè chế độ suy luận của ánh xạ hook`},help:{"v1-17hq8me-57":`Tùy chọn ghi đè mức độ suy luận cho các lượt chạy do ánh xạ kích hoạt để cân bằng độ trễ và chiều sâu suy luận. Giữ ở mức thấp hoặc tối thiểu cho các hook có lưu lượng lớn, trừ khi thực sự cần suy luận sâu hơn.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Thời gian chờ của ánh xạ hook (giây)`},help:{"v1-1r44ox2-4i":`Thời gian chạy tối đa được phép để thực thi hành động ánh xạ trước khi áp dụng xử lý hết thời gian chờ. Sử dụng giới hạn ngắn hơn cho các nguồn webhook có lưu lượng lớn để tránh ùn tắc hàng đợi.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Đích gửi của ánh xạ hook`},help:{"v1-1p7928e-55":`Mã định danh đích trong kênh đã chọn khi cần định tuyến phản hồi của ánh xạ đến một đích cố định. Xác minh định dạng đích theo từng nhà cung cấp trước khi bật ánh xạ trong môi trường sản xuất.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Phép biến đổi của ánh xạ hook`},help:{"v1-14igxpm-5m":`Khối cấu hình phép biến đổi xác định mô-đun/hàm xuất dùng để tiền xử lý trước khi xử lý hành động ánh xạ. Chỉ sử dụng phép biến đổi từ các đường dẫn mã đã được kiểm duyệt và giữ hành vi nhất quán để tự động hóa có thể lặp lại với cùng kết quả.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Hàm xuất của phép biến đổi hook`},help:{"v1-atn8v-4b":`Hàm xuất có tên cần gọi từ mô-đun biến đổi; nếu bỏ qua, mặc định sử dụng hàm xuất mặc định của mô-đun. Đặt tùy chọn này khi một tệp chứa nhiều hàm xử lý biến đổi.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Mô-đun biến đổi hook`},help:{"v1-56futq-4v":`Đường dẫn tương đối đến mô-đun biến đổi được tải từ hooks.transformsDir để viết lại dữ liệu đầu vào trước khi chuyển đi. Giữ các mô-đun ở cục bộ, đã được rà soát và không chứa các mẫu đường dẫn cho phép truy cập ra ngoài thư mục.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Chế độ đánh thức của ánh xạ hook`},help:{"v1-1dzqfnw-59":`Chế độ lên lịch đánh thức: "now" đánh thức ngay lập tức, còn "next-heartbeat" trì hoãn đến chu kỳ nhịp tim tiếp theo. Sử dụng chế độ trì hoãn cho các tác vụ tự động hóa có mức ưu tiên thấp hơn và có thể chấp nhận độ trễ nhỏ.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Đường dẫn điểm cuối hook`},help:{"v1-1l9ijzv-4u":"Đường dẫn HTTP mà điểm cuối hook sử dụng (ví dụ `/hooks`) trên máy chủ điều khiển gateway. Sử dụng đường dẫn khó đoán và kết hợp với việc xác thực token để bảo vệ nhiều lớp."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Các bộ thiết lập sẵn cho hook`},help:{"v1-dp8m0l-4v":`Các gói thiết lập sẵn cho hook có tên, được áp dụng khi tải để khởi tạo các ánh xạ tiêu chuẩn và hành vi mặc định. Chỉ định rõ các bộ thiết lập sẵn được sử dụng để người vận hành có thể kiểm tra những tác vụ tự động hóa đang hoạt động.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Token xác thực hook`},help:{"v1-1ihf6mv-82":`Token bearer dùng chung được đầu vào hook kiểm tra để xác thực yêu cầu trước khi chạy các ánh xạ. Xem người giữ token là bên gọi được tin cậy hoàn toàn đối với giao diện đầu vào hook, không phải là một vai trò riêng biệt không thuộc chủ sở hữu. Sử dụng cơ chế thay thế bằng biến môi trường và luân chuyển token thường xuyên khi các điểm cuối webhook có thể được truy cập từ internet.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Thư mục biến đổi hook`},help:{"v1-1ayj9p0-4t":`Thư mục gốc cho các mô-đun biến đổi hook được tham chiếu bằng đường dẫn transform.module trong ánh xạ. Sử dụng thư mục kho mã được kiểm soát để việc nhập mô-đun động luôn có thể được rà soát và dự đoán.`}},logging:{label:{"v1-rq08xq-7":`Ghi nhật ký`},help:{"v1-11an9pb-5e":`Các tùy chọn kiểm soát hành vi ghi nhật ký về mức độ nghiêm trọng, đích đầu ra, định dạng và che dữ liệu nhạy cảm. Duy trì mức ghi nhật ký và chế độ che dữ liệu đủ nghiêm ngặt cho môi trường sản xuất mà vẫn giữ lại thông tin chẩn đoán hữu ích.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Sổ kiểm toán`},help:{"v1-1lauvy2-6w":`Lịch sử kiểm toán có giới hạn, chỉ chứa siêu dữ liệu để người vận hành xem xét. Bản ghi lượt chạy và công cụ được bật theo mặc định; siêu dữ liệu vòng đời tin nhắn là tùy chọn riêng cần chủ động bật do nhạy cảm về quyền riêng tư. Trình ghi nền hoạt động theo khả năng tốt nhất, không phải kho lưu trữ tuân thủ bảo đảm không mất dữ liệu.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Bật sổ kiểm toán`},help:{"v1-snknxb-4v":`Ghi lại các sự kiện kiểm toán mới về lượt chạy, công cụ và tin nhắn đã được bật ghi nhận. Mặc định: true. Thay đổi có hiệu lực ngay; các thao tác ghi đã được chấp nhận sẽ hoàn tất và các bản ghi được lưu giữ vẫn có thể truy vấn cho đến khi hết hạn.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Kiểm toán danh tính thực thi`},help:{"v1-1ucirwv-5b":`Lưu giữ thông tin quy thuộc danh tính thực thi trong phạm vi giới hạn để kiểm tra chính xác từng lượt chạy. Mặc định: false. Yêu cầu logging.audit.enabled và áp dụng cho các lượt chạy mới được tiếp nhận; các ngữ cảnh hiện có không thay đổi.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Phạm vi kiểm toán tin nhắn`},help:{"v1-1yg4lc3-76":`Kiểm soát các bản ghi vòng đời tin nhắn không chứa nội dung: "off" (mặc định), "direct" chỉ dành cho các cuộc trò chuyện trực tiếp đã xác định, hoặc "all" dành cho các cuộc trò chuyện trực tiếp, nhóm, kênh và chưa xác định loại. Yêu cầu logging.audit.enabled. Thay đổi áp dụng cho các sự kiện vòng đời tiếp theo.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Mức ghi nhật ký trên bảng điều khiển`},help:{"v1-16badbd-5u":`Ngưỡng ghi nhật ký riêng cho bảng điều khiển: "silent", "fatal", "error", "warn", "info", "debug" hoặc "trace" để kiểm soát đầu ra của terminal. Dùng tùy chọn này để giảm lượng nhật ký trên bảng điều khiển cục bộ nhưng vẫn ghi nhật ký chi tiết hơn vào tệp nếu cần.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Kiểu nhật ký bảng điều khiển`},help:{"v1-d7u0iq-3q":`Kiểu định dạng đầu ra của bảng điều khiển: "pretty" hoặc "json". Dùng json cho các quy trình phân tích cú pháp tự động và pretty cho các quy trình làm việc trên terminal ưu tiên khả năng đọc của người dùng.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Đường dẫn tệp nhật ký`},help:{"v1-16gaitv-4w":`Đường dẫn tệp tùy chọn để lưu đầu ra nhật ký lâu dài, bổ sung hoặc thay thế việc ghi nhật ký trên bảng điều khiển. Dùng đường dẫn có quyền ghi được quản lý và điều chỉnh việc lưu giữ/luân chuyển nhật ký cho phù hợp với chính sách vận hành của bạn.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Mức nhật ký`},help:{"v1-1r5yku0-5o":`Ngưỡng mức nhật ký chính cho đầu ra của bộ ghi nhật ký khi chạy: "silent", "fatal", "error", "warn", "info", "debug" hoặc "trace". Giữ "info" hoặc "warn" trong môi trường sản xuất và chỉ dùng debug/trace khi điều tra sự cố.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Mẫu che dữ liệu tùy chỉnh`},help:{"v1-1esa6eg-7k":`Các chuỗi biểu thức chính quy tùy chỉnh thay thế danh sách chuỗi mặc định cho đầu ra nhật ký/bản ghi hội thoại và bổ sung vào các quy tắc bảo vệ an toàn cho giao diện người dùng/công cụ/chẩn đoán. Các biện pháp bảo vệ tích hợp cho phần thân biểu mẫu, dữ liệu xác thực có cấu trúc và khóa AWS đứng riêng luôn được áp dụng. Dùng tùy chọn này để che các token và mã định danh đặc thù của từng triển khai.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Các định nghĩa máy chủ MCP toàn cục do OpenClaw quản lý. OpenClaw nhúng và các bộ điều hợp môi trường chạy khác có thể sử dụng những máy chủ này mà không cần lưu chúng trong phần cài đặt dự án thuộc môi trường chạy.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`Ứng dụng MCP`},help:{"v1-amyd91-38":`Hỗ trợ giao diện MCP Apps. Khi được bật, các máy chủ MCP đã cấu hình có thể cung cấp chế độ xem HTML tương tác cho kết quả công cụ của chúng.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`Bật MCP Apps`},help:{"v1-ghqy98-3w":`Tùy chọn bật hiển thị MCP Apps và cầu nối giữa ứng dụng với máy chủ. Giữ ở trạng thái tắt trừ khi bạn tin tưởng các máy chủ MCP đã cấu hình cung cấp tài nguyên giao diện ứng dụng.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Nguồn gốc sandbox MCP Apps`},help:{"v1-1sxv3mf-6v":`Nguồn gốc HTTP(S) công khai chuyên dụng tùy chọn cho MCP Apps. Sử dụng nguồn gốc này phía sau proxy ngược hoặc điểm kết thúc TLS và chỉ chuyển tiếp đến cổng sandbox MCP Apps đã cấu hình. Nguồn gốc này phải khác với nguồn gốc của Control UI và không được phục vụ nội dung yêu cầu xác thực.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Cổng sandbox MCP Apps`},help:{"v1-1b8n71l-4p":`Cổng lắng nghe chuyên dụng cho sandbox MCP Apps. Mặc định là cổng Gateway cộng một. Đặt một cổng chưa sử dụng nếu một dịch vụ cục bộ hoặc hồ sơ Gateway khác đang dùng cổng đó.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`Máy chủ MCP`},help:{"v1-157ozoz-42":`Các định nghĩa máy chủ MCP có tên. OpenClaw lưu chúng trong cấu hình riêng của mình và các bộ điều hợp thời gian chạy quyết định những phương thức truyền tải nào được hỗ trợ khi thực thi.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Xác thực máy chủ MCP`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Chứng chỉ máy khách MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Khóa máy khách MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Chứng chỉ máy khách MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Khóa máy khách MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Ánh xạ MCP cho Codex`},help:{"v1-slcmq1-6x":`Siêu dữ liệu ánh xạ của OpenClaw chỉ dành cho các luồng Codex app-server. Siêu dữ liệu này không ảnh hưởng đến các phiên ACP hay cấu hình harness Codex chung. Bỏ qua khối này để mọi tác nhân Codex app-server đều có thể sử dụng máy chủ với cơ chế phê duyệt MCP mặc định của Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Tác nhân MCP của Codex`},help:{"v1-8q98n8-67":`Danh sách tùy chọn gồm các ID tác nhân OpenClaw không rỗng cần được cấp máy chủ MCP này trong cấu hình luồng Codex app-server. Danh sách rỗng, chỉ chứa khoảng trắng hoặc không hợp lệ sẽ bị từ chối theo nguyên tắc an toàn; nếu bỏ qua, máy chủ sẽ được ánh xạ cho tất cả tác nhân Codex app-server.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Phê duyệt công cụ MCP của Codex`},help:{"v1-1xql0qr-3d":`Cách viết theo quy ước gốc của Codex cho cùng chế độ phê duyệt công cụ MCP theo từng máy chủ. Ưu tiên dùng defaultToolsApprovalMode trong cấu hình OpenClaw.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Phê duyệt công cụ MCP của Codex`},help:{"v1-y5vsqq-3s":`Chế độ phê duyệt công cụ MCP của Codex tùy chọn cho máy chủ này: "auto", "prompt" hoặc "approve". Chỉ dùng cho các máy chủ MCP mà bạn chủ động tin cậy.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Thời gian chờ kết nối MCP (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Bật máy chủ MCP`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Hồ sơ xác thực OAuth MCP`},help:{"v1-fcrb4u-5z":`ID hồ sơ xác thực có khả năng làm mới, dùng để chèn token bearer hiện tại vào máy chủ MCP từ xa này. Khi được đặt, OpenClaw sẽ tra cứu và làm mới hồ sơ trong thời gian chạy, đồng thời không chuyển dữ liệu dùng để làm mới xuống các thành phần phía sau.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL siêu dữ liệu ứng dụng khách OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Danh tính OAuth MCP`},help:{"v1-1ie6ys7-59":`Quyền sở hữu thông tin xác thực OAuth cho máy chủ này. Bỏ qua trường này hoặc dùng "shared" cho thông tin xác thực do người vận hành quản lý; dùng "per-requester" để cho phép mỗi người gửi đã xác thực kết nối tài khoản riêng của họ.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`URL chuyển hướng OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Phạm vi OAuth MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Thời gian chờ yêu cầu MCP (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Xác minh TLS MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Xác minh TLS MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Lệnh gọi công cụ MCP song song`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Lệnh gọi công cụ MCP song song`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Lựa chọn công cụ MCP`},help:{"v1-10poyzb-4v":`Lựa chọn công cụ MCP cho từng máy chủ. Dùng include để chỉ cung cấp những công cụ MCP có tên được chọn, hoặc exclude để ẩn những công cụ MCP có tên được chọn. Các mục chấp nhận tên chính xác và mẫu glob đơn giản có ký tự '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Công cụ MCP bị loại trừ`},help:{"v1-ijrc5y-1u":`Tên chính xác của công cụ MCP hoặc mẫu glob đơn giản dùng '*' để ẩn công cụ từ máy chủ này.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Công cụ MCP được đưa vào`},help:{"v1-89fdfq-3o":`Tên chính xác của công cụ MCP hoặc mẫu glob đơn giản dùng '*' để cung cấp công cụ từ máy chủ này. Khi bỏ qua, tất cả công cụ của máy chủ vẫn đủ điều kiện sử dụng trừ khi bị loại trừ.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL khi nhàn rỗi của phiên MCP (ms)`},help:{"v1-j9si74-87":`Thời gian tùy chọn để thu hồi môi trường chạy MCP của phiên OpenClaw khi nhàn rỗi, tính bằng mili giây. Không đặt hoặc đặt thành 0 sẽ giữ môi trường chạy hoạt động cho đến khi dọn dẹp phiên hoặc tắt Gateway. Giá trị dương được làm tròn xuống; các quyền sử dụng đang có hiệu lực và yêu cầu cấp quyền đang chờ sẽ ngăn việc thu hồi. Môi trường chạy thuộc một lượt chạy vẫn ngừng hoạt động khi lượt chạy một lần đó kết thúc.`}},memory:{label:{"v1-oopaku-6":`Bộ nhớ`},help:{"v1-1wlx40m-13":`Cấu hình bộ nhớ tích hợp (toàn cục).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Chế độ trích dẫn bộ nhớ`},help:{"v1-1q6dxr5-4u":`Kiểm soát việc hiển thị trích dẫn trong câu trả lời: "auto" hiển thị trích dẫn khi hữu ích, "on" luôn hiển thị và "off" ẩn trích dẫn. Giữ "auto" làm mặc định để cân bằng giữa thông tin hữu ích và thông tin gây nhiễu.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Tìm kiếm bộ nhớ`},help:{"v1-1ukbud1-25":`Tìm kiếm vectơ trên MEMORY.md và memory/*.md (hỗ trợ ghi đè cấu hình cho từng tác nhân).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Bộ nhớ đệm embedding cho tìm kiếm bộ nhớ`},help:{"v1-d8h2e4-5b":`Lưu các embedding đã tính toán của từng đoạn vào bộ nhớ đệm trong SQLite để tăng tốc lập chỉ mục lại và cập nhật gia tăng (mặc định: true). Giữ tùy chọn này bật trừ khi đang kiểm tra tính chính xác của bộ nhớ đệm hoặc muốn giảm thiểu dung lượng ổ đĩa sử dụng.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Loại đầu vào tài liệu cho tìm kiếm bộ nhớ`},help:{"v1-1ui33sv-5f":"Giá trị `input_type` tùy chọn theo từng nhà cung cấp cho các biểu diễn nhúng của tài liệu và dữ liệu lập chỉ mục bộ nhớ. Dùng với các điểm cuối nhúng bất đối xứng tương thích với OpenAI yêu cầu nhãn đoạn văn hoặc tài liệu."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Bật tìm kiếm bộ nhớ`},help:{"v1-14f11b9-4t":`Công tắc tổng điều khiển việc lập chỉ mục và truy xuất khi tìm kiếm bộ nhớ trên hồ sơ tác tử này. Giữ bật để gợi nhớ theo ngữ nghĩa và tắt khi muốn phản hồi hoàn toàn không lưu trạng thái.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Chỉ mục phiên cho tìm kiếm bộ nhớ (Thử nghiệm)`},help:{"v1-qvhv8z-3i":`Lập chỉ mục bản ghi phiên để tìm kiếm trong bộ nhớ. Giữ thiết lập ghi đè nâng cao này khi cơ chế kế thừa khả năng gợi nhớ ở cấp gốc và theo từng tác tử khác nhau.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Đường dẫn bộ nhớ bổ sung`},help:{"v1-ojqokq-7i":`Thêm các thư mục hoặc tệp .md bổ sung vào chỉ mục bộ nhớ ngoài các tệp bộ nhớ mặc định. Mỗi mục có thể là chuỗi đường dẫn hoặc đối tượng chứa mẫu glob tương đối so với thư mục gốc. Khi bật bộ nhớ đa phương thức, các tệp hình ảnh/âm thanh khớp trong những đường dẫn này cũng có thể được lập chỉ mục.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Đường dẫn bộ nhớ bổ sung`},help:{"v1-b9mbq8-3m":`Đặt thư mục hoặc tệp bộ nhớ bổ sung. Đường dẫn tương đối được xác định từ không gian làm việc của tác tử; các mục trỏ trực tiếp đến tệp được lập chỉ mục đúng theo tệp đã chỉ định.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Mẫu đường dẫn bộ nhớ bổ sung`},help:{"v1-j8br1v-4e":`Giới hạn một mục thư mục ở các tệp được hỗ trợ khớp với mẫu glob tương đối so với thư mục gốc này, ví dụ "runbooks/**/*.md". Bỏ qua để quét đệ quy tất cả các tệp được hỗ trợ.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Nhà cung cấp dự phòng cho tìm kiếm bộ nhớ`},help:{"v1-1r6368w-6p":`Nhà cung cấp dự phòng được dùng khi quá trình tạo embedding chính thất bại: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" hoặc "none". Hãy thiết lập một nhà cung cấp dự phòng thực sự để đảm bảo độ tin cậy trong môi trường vận hành thực tế; chỉ dùng "none" nếu bạn muốn lỗi được báo rõ ràng.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Loại đầu vào cho tìm kiếm bộ nhớ`},help:{"v1-26vbwe-5u":"Chỉ dùng giá trị `input_type` tùy chọn dành riêng cho nhà cung cấp này khi cần áp dụng cùng một nhãn cho cả yêu cầu tạo embedding truy vấn và tài liệu. Với các nhà cung cấp bất đối xứng, nên dùng queryInputType và documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Đường dẫn mô hình embedding cục bộ`},help:{"v1-13ymbnt-5q":"Chỉ định nguồn mô hình embedding cục bộ để tìm kiếm bộ nhớ cục bộ, chẳng hạn như đường dẫn tệp GGUF hoặc URI `hf:`. Chỉ dùng tùy chọn này khi provider là `local` và xác minh tính tương thích của mô hình trước khi xây dựng lại chỉ mục quy mô lớn."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Mô hình tìm kiếm bộ nhớ`},help:{"v1-11pohrl-59":`Mô hình embedding thay thế mà nhà cung cấp bộ nhớ đã chọn sử dụng khi cần một mô hình khác với mặc định. Chỉ thiết lập tùy chọn này khi bạn cần tinh chỉnh cụ thể chất lượng truy xuất hoặc chi phí ngoài các giá trị mặc định của nhà cung cấp.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Tìm kiếm bộ nhớ đa phương thức`},help:{"v1-1jn02s-9e":'Các cài đặt bộ nhớ đa phương thức tùy chọn để lập chỉ mục các tệp hình ảnh và âm thanh từ những đường dẫn bổ sung đã cấu hình. Giữ tùy chọn này ở trạng thái tắt trừ khi mô hình embedding của bạn có hỗ trợ rõ ràng cho embedding liên phương thức, và đặt `memory.search.fallback` thành "none" khi bật tùy chọn này. Các tệp phù hợp sẽ được tải lên nhà cung cấp embedding từ xa đã cấu hình trong quá trình lập chỉ mục.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Bật tìm kiếm bộ nhớ đa phương thức`},help:{"v1-1dk5d7o-7e":`Bật lập chỉ mục bộ nhớ cho hình ảnh/âm thanh từ extraPaths. Tính năng này hiện yêu cầu Gemini embedding-2, giữ các thư mục gốc bộ nhớ mặc định chỉ dành cho Markdown, vô hiệu hóa các nhà cung cấp dự phòng cho tìm kiếm bộ nhớ và tải nội dung nhị phân phù hợp lên nhà cung cấp embedding từ xa đã cấu hình.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Số byte tối đa mỗi tệp đa phương thức trong tìm kiếm bộ nhớ`},help:{"v1-1mmdrvk-5d":`Đặt số byte tối đa được phép cho mỗi tệp đa phương thức; tệp vượt giới hạn sẽ bị bỏ qua khi lập chỉ mục bộ nhớ. Dùng thiết lập này để giới hạn chi phí tải lên và độ trễ lập chỉ mục, hoặc tăng giới hạn cho các đoạn âm thanh ngắn chất lượng cao.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Các phương thức trong tìm kiếm bộ nhớ đa phương thức`},help:{"v1-alp4vh-4l":`Chọn các loại tệp đa phương thức được lập chỉ mục từ extraPaths: "image", "audio" hoặc "all". Nên giới hạn phạm vi này để tránh vô tình lập chỉ mục các tập dữ liệu nhị phân lớn.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Số chiều đầu ra của tìm kiếm bộ nhớ`},help:{"v1-1f7zu53-93":`Ghi đè kích thước vectơ đầu ra cho embedding bộ nhớ theo từng nhà cung cấp. Các mô hình Gemini hỗ trợ 128-3072 chiều và khuyến nghị 768, 1536 hoặc 3072; các dòng mô hình Bedrock như Titan V2, Cohere V4 và Nova có các kích thước được phép riêng. Khi thay đổi thiết lập này, toàn bộ dữ liệu sẽ cần được lập chỉ mục lại vì số chiều của các vectơ đã lưu phải nhất quán.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Nhà cung cấp tìm kiếm bộ nhớ`},help:{"v1-5evseb-71":`Chọn dịch vụ embedding dùng để tạo/truy vấn các vectơ bộ nhớ. Mặc định là "openai"; đặt thành "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" hoặc "local" khi bạn muốn dùng dịch vụ khác.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Số kết quả tìm kiếm bộ nhớ tối đa`},help:{"v1-13ekath-4x":`Số kết quả bộ nhớ tối đa được trả về từ tìm kiếm trước khi được xếp hạng lại và đưa vào lời nhắc ở các bước tiếp theo. Tăng để truy xuất rộng hơn hoặc giảm để lời nhắc gọn hơn và phản hồi nhanh hơn.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Điểm tìm kiếm bộ nhớ tối thiểu`},help:{"v1-1ww231l-4v":`Ngưỡng điểm liên quan tối thiểu để đưa kết quả bộ nhớ vào đầu ra truy xuất cuối cùng. Tăng để giảm các kết quả khớp yếu hoặc nhiễu, hoặc giảm khi bạn cần truy xuất với tiêu chí rộng hơn.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Loại đầu vào truy vấn tìm kiếm bộ nhớ`},help:{"v1-831yrv-4q":"Giá trị `input_type` tùy chọn, dành riêng cho từng nhà cung cấp, cho embedding bộ nhớ tại thời điểm truy vấn. Dùng với các điểm cuối embedding bất đối xứng tương thích với OpenAI có yêu cầu nhãn truy vấn."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Ghi nhớ giữa các cuộc trò chuyện`},help:{"v1-k1itm8-7y":`Sử dụng ngữ cảnh liên quan từ các cuộc trò chuyện riêng tư khác của tác nhân này thông qua cơ chế truy xuất bản ghi trò chuyện có bảo vệ. Chỉ bật theo mặc định khi session.dmScope toàn cục chưa được đặt hoặc là "main" và không có liên kết nào ghi đè phạm vi tin nhắn trực tiếp; mọi cấu hình cách ly tin nhắn trực tiếp đều khiến tính năng này mặc định tắt. Giá trị true hoặc false được đặt tường minh luôn được ưu tiên.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Khóa API embedding từ xa`},help:{"v1-nfuuu-62":`Cung cấp khóa API riêng cho các lệnh gọi tạo embedding từ xa dùng để lập chỉ mục bộ nhớ và tạo embedding khi truy vấn. Sử dụng tùy chọn này khi embedding bộ nhớ cần dùng thông tin xác thực khác với giá trị mặc định toàn cục hoặc biến môi trường.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`URL cơ sở cho embedding từ xa`},help:{"v1-1ugvqgt-5p":`Ghi đè điểm cuối API tạo embedding, chẳng hạn như proxy tương thích với OpenAI hoặc URL cơ sở tùy chỉnh của Gemini. Chỉ sử dụng tùy chọn này khi định tuyến qua cổng kết nối riêng hoặc điểm cuối của nhà cung cấp; nếu không, hãy giữ giá trị mặc định của nhà cung cấp.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Bật tạo embedding từ xa theo lô`},help:{"v1-1fehqi-5x":`Bật API xử lý theo lô của nhà cung cấp cho các tác vụ tạo embedding khi được hỗ trợ (OpenAI/Gemini), giúp tăng thông lượng trong các lần lập chỉ mục lớn. Giữ tùy chọn này bật trừ khi cần gỡ lỗi xử lý theo lô của nhà cung cấp hoặc chạy khối lượng công việc rất nhỏ.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Tiêu đề HTTP cho embedding từ xa`},help:{"v1-1uic0kd-5i":`Thêm tiêu đề HTTP tùy chỉnh vào các yêu cầu tạo embedding từ xa, kết hợp với giá trị mặc định của nhà cung cấp. Sử dụng tùy chọn này cho các tiêu đề xác thực proxy và định tuyến đối tượng thuê, đồng thời chỉ cung cấp các giá trị tối thiểu cần thiết để tránh rò rỉ siêu dữ liệu nhạy cảm.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Nguồn tìm kiếm bộ nhớ`},help:{"v1-btxtzg-57":`Chọn các nguồn được lập chỉ mục: "memory" đọc MEMORY.md + các tệp bộ nhớ, còn "sessions" bao gồm lịch sử bản ghi hội thoại. Giữ ["memory"] trừ khi bạn cần truy xuất thông tin từ các bản ghi trò chuyện trước đó.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Chỉ mục vectơ cho tìm kiếm bộ nhớ`},help:{"v1-fbybkj-37":`Kiểm soát chỉ mục ngữ nghĩa sqlite-vec. Giữ thiết lập ghi đè nâng cao này khi chính sách vectơ ở cấp gốc và theo từng tác tử khác nhau.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Đường dẫn tiện ích mở rộng vectơ cho tìm kiếm bộ nhớ`},help:{"v1-1hysv5q-58":"Ghi đè đường dẫn thư viện tiện ích mở rộng sqlite-vec được tự động phát hiện (`.dylib`, `.so` hoặc `.dll`). Dùng thiết lập này khi môi trường chạy không thể tự động tìm thấy sqlite-vec hoặc khi bạn cố định một bản dựng đã được xác nhận là hoạt động tốt."}},messages:{label:{"v1-1wwzqad-8":`Tin Nhắn`},help:{"v1-i5k0iw-5k":`Hạ tầng tin nhắn và các giá trị mặc định dùng chung cho các tác tử. Các mục ngang hàng ở cấp gốc quản lý hạ tầng và các giá trị mặc định dùng chung cho các tác tử; agents.defaults quản lý hành vi vòng lặp của tác tử; các mục cấu hình tác tử có thể ghi đè cả hai loại này khi được hỗ trợ.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji phản ứng xác nhận`},help:{"v1-1iip0zs-1x":`Emoji phản ứng dùng để xác nhận đã nhận tin nhắn đến (để trống để tắt).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Phạm vi phản ứng xác nhận`},help:{"v1-1jvdg5n-7s":`Thời điểm gửi phản ứng xác nhận ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" xác nhận các tin nhắn nhóm có nhắc đến tác tử, bất kể nhóm có yêu cầu nhắc tên hay không; "group-all" xác nhận mọi tin nhắn nhóm. "off"/"none" tắt hoàn toàn phản ứng xác nhận.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Quy tắc trò chuyện nhóm`},help:{"v1-chqsvh-4l":`Các thiết lập kiểm soát việc xử lý tin nhắn nhóm, bao gồm điều kiện kích hoạt khi được nhắc tên và kích thước cửa sổ lịch sử. Giữ các mẫu nhận diện lượt nhắc tên ở phạm vi hẹp để các kênh nhóm không kích hoạt với mọi tin nhắn.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Giới hạn lịch sử nhóm`},help:{"v1-1mkbpw-9k":`Số lượng tối đa tin nhắn nhóm trước đó được tải làm ngữ cảnh mỗi lượt trong các phiên nhóm. Dùng giá trị cao hơn để duy trì mạch hội thoại đầy đủ hơn, hoặc giá trị thấp hơn để phản hồi nhanh hơn và tiết kiệm chi phí hơn. Lịch sử tự động đưa vào lời nhắc được giới hạn ở 200 tin nhắn. Giá trị số nguyên tối đa của JSON sẽ chọn phạm vi lịch sử mặc định của kênh (50 tin nhắn đối với lịch sử nhóm dùng chung), chứ không phải phạm vi không giới hạn.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Mẫu phát hiện lượt nhắc trong nhóm`},help:{"v1-i7h7qc-6f":`Các mẫu biểu thức chính quy an toàn, không phân biệt chữ hoa chữ thường, dùng để phát hiện lượt nhắc trực tiếp/cụm từ kích hoạt trong cuộc trò chuyện nhóm. Dùng các mẫu chính xác để giảm nhận diện nhầm trong các kênh có lượng tin nhắn lớn; các mẫu không hợp lệ hoặc có phép lặp lồng nhau không an toàn sẽ bị bỏ qua.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Tin nhắn đến trong nhóm không có lượt nhắc`},help:{"v1-17wef8h-5f":`Kiểm soát cách gửi nội dung trò chuyện nhóm không có lượt nhắc khi chế độ luôn hoạt động được bật. "user_request" coi nội dung đó là yêu cầu của người dùng; "room_event" gửi nội dung đó dưới dạng ngữ cảnh thầm lặng, trong đó đầu ra hiển thị yêu cầu dùng công cụ message.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Phản hồi hiển thị trong nhóm`},help:{"v1-qa4z1s-aa":`Ghi đè cách xử lý phản hồi nguồn do mô hình tạo cho các cuộc trò chuyện nhóm/kênh. Mặc định là "automatic" khi chưa đặt chính sách phản hồi hiển thị toàn cục. "message_tool" yêu cầu dùng message(action=send) cho đầu ra thông thường của trợ lý và nội dung đa phương tiện thông thường từ công cụ; đầu ra thời gian chạy được xác định rõ là do hệ thống chủ quản lý vẫn có thể được chuyển đi, ngoại trừ các sự kiện nền trong phòng. "automatic" đăng phản hồi thông thường như trước.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Gộp tin nhắn đến liên tiếp`},help:{"v1-ebyu5x-4a":`Cài đặt gộp tin nhắn đến trực tiếp, được áp dụng trước khi bắt đầu xử lý hàng đợi/lượt. Cấu hình mục này để xử lý các đợt tin nhắn gửi nhanh từ cùng một người gửi, tùy theo nhà cung cấp.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Gộp tin nhắn đến liên tiếp theo kênh (ms)`},help:{"v1-wbz54j-4g":`Các giá trị ghi đè thời gian chờ gộp tin nhắn đến theo từng kênh, tính bằng mili giây và được xác định bằng ID nhà cung cấp. Dùng khi một số nhà cung cấp gửi các phần tin nhắn liên tiếp nhanh hơn những nhà cung cấp khác.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Thời gian chờ gộp tin nhắn đến (ms)`},help:{"v1-1616yo2-7w":`Khoảng chờ không có tin nhắn mới (ms) để gom các tin nhắn đến liên tiếp từ cùng một người gửi. Telegram mặc định dùng 300ms khi không có giá trị ghi đè ở cấp toàn cục hoặc cấp kênh; các kênh khác mặc định dùng 0. Giá trị 0 tắt tính năng gom tin nhắn liên tiếp thông thường, nhưng Telegram vẫn ghép lại các đoạn của tin nhắn dài gần chạm giới hạn.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Hàng đợi tin nhắn đến`},help:{"v1-hm2o31-48":`Chiến lược xếp hàng cho các tin nhắn đến trong khi một lượt chạy của phiên đang hoạt động. Dùng để điều chỉnh việc định hướng, trì hoãn xử lý tiếp, gộp tin nhắn hoặc ngắt lượt chạy.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Chế độ hàng đợi theo kênh`},help:{"v1-4rf8z8-54":`Các giá trị ghi đè chế độ hàng đợi theo từng kênh, được xác định bằng ID nhà cung cấp (ví dụ: telegram, discord, slack). Dùng khi đặc điểm lưu lượng của một kênh cần cách xử lý khác với mặc định chung.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Sức chứa hàng đợi`},help:{"v1-16ql8c7-4j":`Số mục tin nhắn đến tối đa được giữ trong hàng đợi trước khi áp dụng chính sách loại bỏ. Mặc định là 20; nên giới hạn sức chứa ở các kênh có nhiều tin nhắn để mức sử dụng bộ nhớ vẫn có thể dự đoán được.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Thời gian chờ gộp dự phòng của hàng đợi theo kênh (ms)`},help:{"v1-4tpyt7-4e":`Các giá trị ghi đè thời gian chờ gộp cho hoạt động của hàng đợi theo từng kênh, được xác định bằng ID nhà cung cấp. Dùng để điều chỉnh riêng cách xử lý các đợt tin nhắn dồn dập trên những giao diện trò chuyện có nhịp độ khác nhau.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Chiến lược loại bỏ trong hàng đợi`},help:{"v1-ydb2rw-6m":`Chiến lược loại bỏ khi vượt quá giới hạn hàng đợi. "summarize" loại bỏ các mục cũ nhất nhưng giữ lại bản tóm tắt ngắn gọn; "old" loại bỏ các mục cũ nhất mà không giữ bản tóm tắt; "new" từ chối mục mới nhất. Dùng "summarize" cho các cuộc trò chuyện kéo dài cần giữ ngữ cảnh.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Chế độ hàng đợi`},help:{"v1-19k7gy1-67":`Chế độ hàng đợi cho các lượt chạy đang hoạt động. Dùng "steer" để chèn lời nhắc vào lượt chạy hiện tại, "followup" để chạy sau, "collect" để gom các tin nhắn tương thích thành lô xử lý sau, hoặc "interrupt" để hủy lượt chạy hiện tại trước khi bắt đầu xử lý lời nhắc mới nhất.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Tiền tố phản hồi gửi đi`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Chế độ chân trang mức sử dụng mặc định`},help:{"v1-l3shsx-dv":`Chế độ chân trang mức sử dụng mặc định cho mỗi phản hồi ("off"|"tokens"|"full"), được áp dụng ban đầu cho các phiên chưa chọn chế độ qua /usage. Cũng chấp nhận "on" làm bí danh cũ của "tokens". Chấp nhận một giá trị chế độ đơn lẻ hoặc ánh xạ theo kênh với giá trị dự phòng "default". Thứ tự ưu tiên: giá trị của phiên -> mục của kênh -> default -> off; lựa chọn rõ ràng qua /usage (kể cả off) được lưu lại và ghi đè giá trị mặc định. Dùng /usage reset (bí danh: inherit, clear, default) để xóa giá trị ghi đè của phiên và kế thừa lại giá trị mặc định đã cấu hình này.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Biểu cảm trạng thái`},help:{"v1-193764l-3s":`Các biểu cảm trạng thái theo vòng đời cập nhật emoji trên tin nhắn kích hoạt khi tác nhân xử lý (đang chờ → đang suy nghĩ → công cụ → hoàn tất/lỗi).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Bật biểu cảm trạng thái`},help:{"v1-1qnmmnc-7x":`Bật phản ứng trạng thái vòng đời trên các kênh được hỗ trợ. Discord coi giá trị chưa được đặt là đã bật khi phản ứng xác nhận đang hoạt động; Slack, Signal, Telegram và WhatsApp yêu cầu giá trị này là true trước khi sử dụng phản ứng vòng đời. Theo mặc định, Slack dùng trạng thái luồng trợ lý tích hợp sẵn để hiển thị tiến độ.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Mẫu chân trang mức sử dụng`},help:{"v1-1xibc23-47":`Mẫu chân trang tùy chỉnh cho /usage full, dưới dạng đối tượng nội tuyến hoặc đường dẫn tệp JSON. Nếu mẫu không hợp lệ hoặc không khả dụng, hệ thống sẽ dùng dòng mức sử dụng tích hợp sẵn.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Phản hồi hiển thị`},help:{"v1-7yfwc2-8t":`Kiểm soát các phản hồi nguồn do mô hình tạo trong cuộc trò chuyện trực tiếp, nhóm và kênh. "message_tool" yêu cầu message(action=send) cho đầu ra thông thường của trợ lý và nội dung đa phương tiện chung từ công cụ; đầu ra thời gian chạy được xác định rõ là do máy chủ quản lý vẫn có thể được gửi, ngoại trừ các sự kiện nền trong phòng. "automatic" đăng phản hồi thông thường như trước.`}},meta:{label:{"v1-1xpfxac-m":`Siêu dữ liệu tương thích`},help:{"v1-1owqhgn-2w":`Siêu dữ liệu tương thích mà phiên bản cũ có thể đọc, được giữ lại để các tệp thực thi cũ có thể từ chối việc hạ cấp cấu hình không an toàn.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Phiên bản cập nhật cấu hình gần nhất`},help:{"v1-qykpv1-1i":`Phiên bản OpenClaw đã ghi cấu hình này gần đây nhất.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Dấu mốc di chuyển cấu hình`},help:{"v1-burt8q-1q":`Các dấu mốc tương thích có giới hạn cho những lần di chuyển cấu hình đã hoàn tất.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Di chuyển danh sách cho phép của chính sách mô hình`},help:{"v1-5psop1-1z":`Ghi nhận rằng các hạn chế trong ánh xạ mô hình cũ đã được giữ nguyên hoặc đánh giá.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Di chuyển để tách riêng mô hình tiện ích`},help:{"v1-vzdfqx-2t":`Ghi nhận rằng các mô hình chính ngầm định kiểu cũ đã được giữ nguyên trước khi tách riêng việc chọn mô hình tiện ích.`}},models:{label:{"v1-hzmwb-6":`Mô hình`},help:{"v1-1h1niol-5q":`Mục gốc của danh mục mô hình, chứa các định nghĩa nhà cung cấp, hành vi hợp nhất/thay thế và tùy chọn tích hợp khám phá Bedrock. Hãy đảm bảo các định nghĩa nhà cung cấp rõ ràng và đã được xác thực trước khi dựa vào các cơ chế chuyển đổi dự phòng trong môi trường vận hành thực tế.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Làm mới danh mục mô hình`},help:{"v1-1hess4t-40":`Kiểm soát việc cập nhật ngầm danh mục mô hình đi kèm. Các mục từ xa có thể cập nhật siêu dữ liệu mô hình nhưng không thể thay đổi điểm cuối hoặc tiêu đề của nhà cung cấp.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Bật làm mới danh mục mô hình`},help:{"v1-1fogpjj-3j":`Tải ngầm các bản cập nhật danh mục mô hình được lưu trữ trực tuyến (mặc định: true). Đặt thành false để tắt toàn bộ lưu lượng truy cập danh mục mô hình từ xa.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL làm mới danh mục mô hình`},help:{"v1-e02ai2-44":`Ghi đè URL danh mục mô hình được lưu trữ trực tuyến để sử dụng bản sao HTTPS tự lưu trữ (cho phép HTTP trên localhost để thử nghiệm). Các thay đổi có hiệu lực sau khi khởi động lại Gateway.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Chế độ danh mục mô hình`},help:{"v1-1ofrnsp-es":`Kiểm soát hành vi của danh mục nhà cung cấp: "merge" giữ lại các nhà cung cấp tích hợp sẵn và áp dụng các nhà cung cấp tùy chỉnh của bạn lên trên, còn "replace" chỉ sử dụng các nhà cung cấp bạn đã cấu hình. Trong "merge", các ID nhà cung cấp trùng khớp sẽ giữ nguyên các giá trị baseUrl không rỗng trong models.json của tác nhân, còn các giá trị apiKey chỉ được giữ nguyên khi nhà cung cấp không do SecretRef quản lý trong ngữ cảnh cấu hình/hồ sơ xác thực hiện tại; các nhà cung cấp do SecretRef quản lý sẽ làm mới apiKey từ các dấu chỉ nguồn hiện tại, và contextWindow/maxTokens của mô hình trùng khớp sẽ dùng giá trị cao hơn giữa các mục khai báo tường minh và ngầm định.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Nhà cung cấp mô hình`},help:{"v1-1y5jg0v-8p":`Bản đồ nhà cung cấp dùng ID nhà cung cấp làm khóa, chứa các thiết lập kết nối/xác thực và định nghĩa mô hình cụ thể. Có thể tinh chỉnh các nhà cung cấp tích hợp sẵn bằng các lớp ghi đè ở cấp nhà cung cấp; nhà cung cấp tùy chỉnh phải có baseUrl và models. Hãy dùng khóa nhà cung cấp ổn định để các tham chiếu từ tác nhân và công cụ vẫn dùng được trên nhiều môi trường.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Môi trường thực thi của nhà cung cấp mô hình`},help:{"v1-1luy4fb-5o":`Chính sách môi trường thực thi tác nhân cấp thấp, không bắt buộc, dành cho nhà cung cấp này. Hãy dùng chính sách môi trường thực thi ở cấp nhà cung cấp/mô hình thay vì cố định môi trường thực thi cho toàn bộ tác nhân; khi bỏ qua hoặc dùng mặc định, OpenClaw sẽ chọn môi trường thực thi cho nhà cung cấp đã chọn.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`ID môi trường thực thi của nhà cung cấp mô hình`},help:{"v1-1gusd9s-69":`ID môi trường thực thi tác nhân của nhà cung cấp: "openclaw", "auto", ID bộ điều phối plugin đã đăng ký như "codex", hoặc bí danh backend CLI được hỗ trợ như "claude-cli". Khi bỏ qua, OpenAI trên điểm cuối chính thức sẽ mặc định dùng bộ điều phối Codex.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Bộ điều hợp API của nhà cung cấp mô hình`},help:{"v1-16c28rb-57":`Lựa chọn bộ điều hợp API của nhà cung cấp, kiểm soát cách xử lý tính tương thích của yêu cầu/phản hồi khi gọi mô hình. Hãy dùng bộ điều hợp khớp với giao thức của nhà cung cấp thượng nguồn để tránh tình trạng không tương thích tính năng.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Khóa API của nhà cung cấp mô hình`},help:{"v1-1p84k96-54":`Thông tin xác thực của nhà cung cấp dùng để xác thực bằng khóa API khi nhà cung cấp yêu cầu xác thực trực tiếp bằng khóa. Hãy dùng cơ chế thay thế bằng giá trị bí mật/biến môi trường và tránh lưu khóa thật trong các tệp cấu hình được đưa vào hệ thống quản lý phiên bản.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Chế độ xác thực của nhà cung cấp mô hình`},help:{"v1-1l1lwxr-5p":`Chọn kiểu xác thực của nhà cung cấp: "api-key" để xác thực bằng khóa API, "token" để xác thực bằng bearer token, "oauth" để dùng thông tin xác thực OAuth và "aws-sdk" để phân giải thông tin xác thực AWS. Chọn kiểu phù hợp với yêu cầu của nhà cung cấp.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Header Authorization của nhà cung cấp mô hình`},help:{"v1-1gn3lt3-59":`Khi là true, thông tin xác thực được gửi qua header HTTP Authorization ngay cả khi có thể dùng phương thức xác thực khác. Chỉ dùng tùy chọn này khi nhà cung cấp hoặc proxy của bạn yêu cầu rõ ràng việc chuyển tiếp Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`URL cơ sở của nhà cung cấp mô hình`},help:{"v1-1ku88v8-53":`URL cơ sở cho điểm cuối của nhà cung cấp, dùng để phục vụ các yêu cầu mô hình cho mục nhà cung cấp đó. Sử dụng điểm cuối HTTPS và giữ URL riêng cho từng môi trường bằng mẫu cấu hình khi cần.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Header của nhà cung cấp mô hình`},help:{"v1-chg59u-4x":`Các header HTTP tĩnh được hợp nhất vào yêu cầu gửi đến nhà cung cấp để định tuyến theo bên thuê, xác thực proxy hoặc đáp ứng yêu cầu của cổng kết nối tùy chỉnh. Hạn chế sử dụng tùy chọn này và lưu các giá trị header nhạy cảm trong kho bí mật.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Chèn num_ctx cho nhà cung cấp mô hình (tương thích OpenAI)`},help:{"v1-53rmcr-6n":"Kiểm soát việc OpenClaw có chèn `options.num_ctx` cho các nhà cung cấp Ollama được cấu hình bằng bộ điều hợp tương thích OpenAI (`openai-completions`) hay không. Mặc định là true. Chỉ đặt thành false nếu proxy hoặc dịch vụ phía trên của bạn từ chối các trường `options` không xác định trong dữ liệu gửi đi."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Dịch vụ cục bộ của nhà cung cấp mô hình`},help:{"v1-19zkcow-4y":`Tiến trình máy chủ mô hình cục bộ tùy chọn, chạy theo nhu cầu cho nhà cung cấp này. OpenClaw kiểm tra healthUrl, chạy lệnh khi cần, đợi máy chủ sẵn sàng rồi gửi yêu cầu đến mô hình.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Đối số dịch vụ cục bộ của nhà cung cấp mô hình`},help:{"v1-t12wib-27":`Danh sách đối số được truyền cho lệnh máy chủ mô hình cục bộ mà không thực hiện khai triển qua shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Lệnh dịch vụ cục bộ của nhà cung cấp mô hình`},help:{"v1-1x6hz64-4j":`Đường dẫn tuyệt đối đến tệp thực thi cho tiến trình máy chủ mô hình cục bộ. Hãy chỉ định rõ đường dẫn này để việc khởi động nhà cung cấp được xác định chính xác và không phụ thuộc vào việc tra cứu PATH của shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Thư mục làm việc của dịch vụ cục bộ của nhà cung cấp mô hình`},help:{"v1-fi3xlx-1h":`Thư mục làm việc cho tiến trình máy chủ mô hình cục bộ.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Môi trường dịch vụ cục bộ của nhà cung cấp mô hình`},help:{"v1-1lwb9k1-3k":`Các biến môi trường bổ sung cho tiến trình máy chủ mô hình cục bộ. Những giá trị có vẻ là thông tin bí mật sẽ bị che trong bản chụp cấu hình.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL kiểm tra tình trạng dịch vụ cục bộ của nhà cung cấp mô hình`},help:{"v1-jv7aw-35":`URL được kiểm tra để xác nhận trạng thái sẵn sàng trước khi gửi yêu cầu đến mô hình. Nếu bỏ qua, OpenClaw sử dụng baseUrl của nhà cung cấp và nối thêm /models.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Dừng dịch vụ cục bộ của nhà cung cấp mô hình khi không hoạt động`},help:{"v1-1efg054-3z":`Số mili giây duy trì hoạt động của máy chủ mô hình cục bộ do OpenClaw khởi động sau khi yêu cầu cuối cùng hoàn tất. Đặt thành 0 để duy trì hoạt động cho đến khi OpenClaw thoát.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Thời gian chờ dịch vụ cục bộ của nhà cung cấp mô hình sẵn sàng`},help:{"v1-4gp0f0-2r":`Số mili giây tối đa chờ kiểm tra trạng thái sẵn sàng của máy chủ mô hình cục bộ sau khi khởi động tiến trình.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Số token tối đa của nhà cung cấp mô hình`},help:{"v1-fnj50y-38":`Giới hạn token đầu ra tối đa mặc định áp dụng cho các mô hình thuộc nhà cung cấp này khi mục mô hình không đặt maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Danh sách mô hình của nhà cung cấp mô hình`},help:{"v1-1vbm0gt-63":`Danh sách mô hình được khai báo cho một nhà cung cấp, bao gồm mã định danh, siêu dữ liệu, tham số riêng của nhà cung cấp và các gợi ý tùy chọn về khả năng tương thích/chi phí. Giữ ID khớp chính xác với các giá trị trong danh mục của nhà cung cấp để việc lựa chọn và chuyển sang phương án dự phòng hoạt động chính xác.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Môi trường thực thi mô hình`},help:{"v1-1k70g2n-3g":`Chính sách môi trường thực thi tác tử cấp thấp tùy chọn cho mô hình cụ thể này. Chính sách môi trường thực thi của mô hình ghi đè chính sách môi trường thực thi của nhà cung cấp.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`ID môi trường thực thi mô hình`},help:{"v1-1llzv33-42":`ID môi trường thực thi tác tử của mô hình: "openclaw", "auto", ID bộ điều phối plugin đã đăng ký như "codex", hoặc bí danh backend CLI được hỗ trợ như "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Đầu vào đa phương tiện của mô hình`},help:{"v1-wxtj8e-2x":`Siêu dữ liệu tùy chọn về khả năng xử lý đa phương tiện của mô hình, được các công cụ dùng để chọn thiết lập nén ảnh mặc định theo hướng thận trọng.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Đầu vào hình ảnh của mô hình`},help:{"v1-1nviirq-3c":`Các giới hạn đầu vào hình ảnh tùy chọn cho mô hình này, chẳng hạn như độ dài cạnh tối đa, số điểm ảnh tối đa và độ dài cạnh ưu tiên khi nén.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Số byte hình ảnh tối đa của mô hình`},help:{"v1-c2469j-23":`Kích thước dữ liệu hình ảnh đã mã hóa tối đa mà nhà cung cấp chấp nhận cho mô hình này.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Số điểm ảnh tối đa của mô hình`},help:{"v1-9d6yqp-1u":`Số điểm ảnh tối đa trong hình ảnh mà nhà cung cấp chấp nhận cho mô hình này.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Độ dài cạnh hình ảnh tối đa của mô hình`},help:{"v1-1gbci08-1y":`Chiều rộng hoặc chiều cao hình ảnh tối đa mà nhà cung cấp chấp nhận cho mô hình này.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Độ dài cạnh hình ảnh ưu tiên của mô hình`},help:{"v1-1u1mpcg-2x":`Độ dài cạnh ưu tiên khi đổi kích thước hình ảnh để cân bằng mức nén. Để trống để dùng giá trị mặc định thận trọng của OpenClaw.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Chế độ tính token hình ảnh của mô hình`},help:{"v1-1oy6z7v-1z":`Cách nhà cung cấp tính token hình ảnh: "tile", "detail" hoặc "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Tham số thời gian chạy của nhà cung cấp mô hình`},help:{"v1-464sgu-4t":`Các tham số thời gian chạy riêng của nhà cung cấp, do plugin của nhà cung cấp diễn giải. Chỉ dùng các khóa được nêu trong tài liệu của nhà cung cấp và ưu tiên hướng dẫn rõ ràng trong tài liệu đó thay vì các giả định chung mang tính tùy tiện.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Khu vực của nhà cung cấp mô hình`},help:{"v1-yq7rxk-5h":`Khu vực triển khai/API tùy chọn của nhà cung cấp, được diễn giải bởi các nhà cung cấp có điểm cuối theo khu vực. Xem tài liệu của nhà cung cấp để biết các giá trị được hỗ trợ; thiết lập ghi đè baseUrl thường được ưu tiên khi cả hai đều được đặt.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Thiết lập ghi đè yêu cầu của nhà cung cấp mô hình`},help:{"v1-1lkxryk-87":`Các thiết lập ghi đè tùy chọn cho yêu cầu gửi đến nhà cung cấp mô hình, bao gồm tiêu đề bổ sung, ghi đè xác thực, định tuyến qua proxy, cài đặt máy khách TLS và tùy chọn allowPrivateNetwork cho các điểm cuối tự lưu trữ đáng tin cậy. Chỉ dùng các thiết lập này khi dịch vụ thượng nguồn hoặc đường truyền mạng doanh nghiệp của bạn yêu cầu tùy chỉnh tầng truyền tải.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Cho phép yêu cầu của nhà cung cấp mô hình truy cập mạng riêng`},help:{"v1-1nbtcjk-fo":`Khi đặt thành true, cho phép các yêu cầu HTTP đến nhà cung cấp mô hình truy cập các dải địa chỉ riêng, CGNAT hoặc tương tự thông qua cơ chế bảo vệ truy xuất HTTP của nhà cung cấp (fetchWithSsrFGuard). Các URL cơ sở của nhà cung cấp tùy chỉnh/cục bộ đã tin cậy chính xác nguồn gốc được cấu hình, ngoại trừ các nguồn gốc siêu dữ liệu, liên kết cục bộ và NAT64 dùng cục bộ (64:ff9b:1::/48); đặt thành false để vô hiệu hóa sự tin cậy đó. OpenAI Responses WebSocket tái sử dụng request cho các tiêu đề/TLS nhưng không sử dụng luồng truy xuất có bảo vệ SSRF đó. Chỉ dùng true cho các điểm cuối tự lưu trữ do người vận hành kiểm soát và cần truy cập các nguồn gốc riêng ngoài nguồn gốc baseUrl đã cấu hình.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Ghi đè xác thực yêu cầu đến nhà cung cấp mô hình`},help:{"v1-ucdgnf-1w":`Ghi đè cách thức xác thực yêu cầu cho nhà cung cấp này.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Tên tiêu đề xác thực yêu cầu đến nhà cung cấp mô hình`},help:{"v1-1881nqr-1i":`Tên tiêu đề xác thực tùy chỉnh được dùng khi chế độ xác thực là header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Chế độ xác thực yêu cầu đến nhà cung cấp mô hình`},help:{"v1-1lhv8hs-24":`Chế độ ghi đè xác thực: "provider-default", "authorization-bearer" hoặc "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Tiền tố tiêu đề xác thực yêu cầu đến nhà cung cấp mô hình`},help:{"v1-1rbm9lz-21":`Tiền tố tùy chọn được thêm vào trước request.auth.value khi chế độ xác thực là header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Token Bearer cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-6rcasw-1l":`Token Bearer được dùng khi chế độ xác thực là authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Giá trị tiêu đề xác thực cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-1v69ej-1j":`Giá trị tiêu đề xác thực tùy chỉnh được dùng khi chế độ xác thực là header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Tiêu đề yêu cầu đến nhà cung cấp mô hình`},help:{"v1-zj3orj-2i":`Các tiêu đề bổ sung được hợp nhất vào yêu cầu đến nhà cung cấp sau khi xác định thông tin ghi nhận nguồn mặc định và thông tin xác thực.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-md5uj8-4j":`Cấu hình ghi đè proxy tùy chọn cho yêu cầu đến nhà cung cấp mô hình. Dùng "env-proxy" để tuân theo cài đặt proxy của môi trường hoặc "explicit-proxy" để định tuyến qua một URL proxy cụ thể.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Chế độ proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-1dx0ozg-29":`Chế độ ghi đè proxy cho yêu cầu đến nhà cung cấp mô hình: "env-proxy" hoặc "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS của proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-rdx62w-1v":`Cài đặt TLS tùy chọn được dùng khi kết nối đến proxy đã cấu hình.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`CA TLS của proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-11pg2fd-1s":`Bộ chứng chỉ CA tùy chỉnh được dùng để xác minh chuỗi chứng chỉ TLS của proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Chứng chỉ TLS của proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-x8nk2q-22":`Chứng chỉ TLS của máy khách được gửi đến proxy khi cần TLS hai chiều.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Bỏ qua xác minh TLS của proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-12vjdm9-2j":`Bỏ qua xác minh chứng chỉ TLS của proxy. Chỉ sử dụng trong môi trường phát triển được kiểm soát.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Khóa TLS của proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-1skyr56-1w":`Khóa riêng tương ứng với request.proxy.tls.cert để dùng TLS hai chiều với proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Cụm mật khẩu TLS của proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-wjvoxd-1m":`Cụm mật khẩu tùy chọn dùng để giải mã request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Tên máy chủ TLS của proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-b4oabu-22":`Giá trị ghi đè SNI/tên máy chủ tùy chọn được dùng khi thiết lập kết nối TLS đến proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`URL proxy cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-kvbgou-48":`URL proxy được chỉ định rõ ràng, dùng khi request.proxy.mode là explicit-proxy. Thông tin xác thực được nhúng trong URL được coi là nhạy cảm và được che đi trong các bản chụp trạng thái.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-16u7v7h-2b":`Các thiết lập TLS tùy chọn được dùng khi kết nối trực tiếp đến điểm cuối mô hình thượng nguồn.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`CA TLS cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-ny8y3e-1v":`Bộ chứng chỉ CA tùy chỉnh dùng để xác minh chuỗi chứng chỉ TLS của máy chủ thượng nguồn.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Chứng chỉ TLS cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-1lltmhw-2e":`Chứng chỉ TLS của máy khách được gửi đến điểm cuối thượng nguồn khi yêu cầu xác thực TLS hai chiều.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Bỏ qua xác minh TLS cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-1006cuy-2m":`Bỏ qua xác minh chứng chỉ TLS của máy chủ thượng nguồn. Chỉ sử dụng trong môi trường phát triển được kiểm soát.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Khóa TLS cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-w2agir-1t":`Khóa riêng ghép cặp với request.tls.cert để xác thực TLS hai chiều với máy chủ thượng nguồn.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Cụm mật khẩu TLS cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-10ds42f-1g":`Cụm mật khẩu tùy chọn dùng để giải mã request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Tên máy chủ TLS cho yêu cầu đến nhà cung cấp mô hình`},help:{"v1-18yt7x9-1y":`Giá trị ghi đè SNI/tên máy chủ tùy chọn được dùng khi thiết lập kết nối TLS với máy chủ thượng nguồn.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Thời gian chờ yêu cầu đến nhà cung cấp mô hình`},help:{"v1-t3yn8l-ih":`Thời gian chờ tùy chọn cho yêu cầu mô hình theo từng nhà cung cấp, tính bằng giây. Cài đặt yêu cầu ở cấp nhà cung cấp ảnh hưởng đến các mục mô hình được khai báo rõ ràng thuộc nhà cung cấp đó; chúng không tạo mô hình ngầm định. Với nhà cung cấp tùy chỉnh, hãy đặt giá trị này cùng với baseUrl và models của nhà cung cấp. Áp dụng cho các yêu cầu HTTP đến nhà cung cấp, bao gồm kết nối, tiêu đề, nội dung và việc xử lý hủy toàn bộ yêu cầu, đồng thời nâng ngưỡng giám sát trạng thái nhàn rỗi/luồng dữ liệu của LLM cho nhà cung cấp này lên trên mức mặc định ngầm định khoảng 120 giây. Dùng cài đặt này cho máy chủ mô hình cục bộ hoặc tự lưu trữ có tốc độ chậm, hoặc cho nhà cung cấp đám mây âm thầm lưu đệm token suy luận mà không gửi qua kết nối (Gemini preview, Claude/Opus với tải dữ liệu công cụ lớn), thay vì thay đổi thời gian chờ chung của tác tử.`}},nodeHost:{label:{"v1-nb8lk1-9":`Máy chủ nút`},help:{"v1-8recuz-4z":`Các tùy chọn điều khiển máy chủ nút cho những tính năng được cung cấp từ nút Gateway này cho các nút hoặc máy khách khác. Giữ nguyên giá trị mặc định trừ khi bạn chủ động dùng proxy để chia sẻ các khả năng cục bộ trên mạng nút của mình.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Lượt chạy tác tử trên nút`},help:{"v1-4uz5ur-2k":`Cho phép các lượt tác tử gốc cần phê duyệt trên máy chủ nút không có giao diện này. Mặc định bị tắt.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Lượt chạy tác tử Claude trên nút`},help:{"v1-g8az5y-2l":`Kiểm soát việc máy chủ nút không có giao diện này có được thông báo khả năng thực hiện các lượt tác tử Claude CLI cho Gateway hay không.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Bật lượt chạy tác tử Claude trên nút`},help:{"v1-1ke804l-44":`Thông báo khả năng tiếp tục phiên Claude trên nút đã ghép đôi khi có tệp nhị phân claude cục bộ (mặc định: false). Các lượt chạy vẫn cần phê duyệt thực thi trên nút.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Cập nhật nút tự động`},help:{"v1-16xjk4e-5n":`Kiểm soát việc cập nhật tự động môi trường thực thi riêng cho các máy chủ nút không có giao diện đã đóng gói. Kiểm tra mỗi giờ và chờ mọi công việc của nút hoàn tất trước khi khởi động lại; các lần khởi động lại tự động cách nhau ít nhất 12 giờ.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Bật cập nhật nút tự động`},help:{"v1-1sa0yeg-7w":`Bật cập nhật tự động từ kênh stable hoặc beta cho các nút không có giao diện đã đóng gói và chạy dài hạn (mặc định: true). Đặt thành false để tắt. Tính năng này cũng bị tắt khi đặt update.checkOnStart=false hoặc OPENCLAW_NO_AUTO_UPDATE=1; các bản lấy từ mã nguồn, ứng dụng gốc, tiến trình xử lý riêng, dev và extended-stable không tự động áp dụng bản cập nhật.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Proxy trình duyệt của nút`},help:{"v1-2xrew7-4f":`Nhóm các cài đặt proxy trình duyệt để cung cấp khả năng điều khiển trình duyệt cục bộ thông qua định tuyến nút. Chỉ bật khi quy trình làm việc trên nút từ xa cần dùng hồ sơ trình duyệt cục bộ của bạn.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Hồ sơ được phép dùng qua proxy trình duyệt của nút`},help:{"v1-1ew5dkm-8b":`Danh sách cho phép tùy chọn gồm tên các hồ sơ trình duyệt được cung cấp thông qua định tuyến proxy của nút. Để trống để giữ nguyên toàn bộ chức năng hồ sơ mặc định, bao gồm các tuyến tạo/xóa hồ sơ. Khi được thiết lập, OpenClaw áp dụng quyền truy cập hồ sơ theo nguyên tắc đặc quyền tối thiểu và chặn việc tạo/xóa hồ sơ lưu lâu dài qua proxy.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Bật proxy trình duyệt của nút`},help:{"v1-pa04pd-5b":`Cung cấp máy chủ điều khiển trình duyệt cục bộ thông qua định tuyến proxy của nút để các máy khách từ xa có thể sử dụng chức năng trình duyệt của máy chủ này. Giữ ở trạng thái tắt trừ khi tác vụ tự động hóa từ xa thực sự phụ thuộc vào chức năng này.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP của máy chủ nút`},help:{"v1-1mdhrwl-48":`Sử dụng các máy chủ MCP do máy chủ nút không có giao diện khởi động và công bố tới Gateway đã ghép đôi làm công cụ cho tác nhân. Khởi động lại máy chủ nút sau khi thay đổi phần này.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Các máy chủ MCP của máy chủ nút`},help:{"v1-19m002f-3x":`Các định nghĩa máy chủ MCP có tên, nằm cục bộ trên nút này. Sử dụng cùng cấu trúc máy chủ như mcp.servers; máy chủ nút không hỗ trợ máy chủ OAuth.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills của máy chủ nút`},help:{"v1-v8txza-41":`Sử dụng phần này để công bố các kỹ năng được cài đặt trong ~/.openclaw/skills từ máy chủ nút không có giao diện. Khởi động lại máy chủ nút sau khi thay đổi các tệp kỹ năng.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Bật Skills của máy chủ nút`},help:{"v1-1ggpkqb-36":`Quét và công bố các kỹ năng được lưu trữ trên nút sau khi kết nối (mặc định: true). Đặt thành false để tắt việc công bố kỹ năng của nút.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Lượt chạy worker trên nút`},help:{"v1-1w83rox-2p":`Cho phép lưu trữ đầy đủ các phiên worker OpenClaw từ các gói do Gateway quản lý. Mặc định bị tắt.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Số lượt chạy worker tối đa trên nút`},help:{"v1-10nvk8f-3w":`Số phiên worker đồng thời tối đa được lưu trữ trên nút này (mặc định: số lõi CPU khả dụng). Phải là số nguyên từ 1 đến 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Ảnh container cho lượt chạy worker trên nút`},help:{"v1-1oqx50o-5t":`Ảnh Node 24.16+ hoặc 26.1+ tùy chọn cho các worker được cô lập bằng container (mặc định: "node:24.19.0-slim"). Khi cần, hãy dùng ảnh được ghim theo mã băm, ảnh từ kho riêng hoặc ảnh đã tải sẵn; ảnh còn thiếu sẽ được tải về khi sử dụng lần đầu.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Bật lượt chạy worker trên nút`},help:{"v1-b3t0xp-2t":`Cho phép nút đã ghép đôi này lưu trữ các phiên từ đúng các gói do Gateway của nó cài đặt (mặc định: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Cô lập lượt chạy worker trên nút`},help:{"v1-19i6swo-58":`Chọn ranh giới tiến trình cho phiên worker: "none" chạy trực tiếp trên máy chủ của nút (mặc định); "container" yêu cầu một bộ máy tương thích với Docker đang hoạt động và không bao giờ chuyển sang chạy trên máy chủ.`}},plugins:{label:{"v1-10renyj-7":`Tiện ích mở rộng`},help:{"v1-1qbev2k-5c":`Các tùy chọn điều khiển hệ thống plugin để bật tiện ích mở rộng, giới hạn phạm vi tải, cấu hình các mục và theo dõi việc cài đặt. Trong môi trường vận hành thực tế, hãy duy trì chính sách plugin rõ ràng và tuân theo nguyên tắc đặc quyền tối thiểu.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Danh sách plugin được phép`},help:{"v1-pupwbe-7z":`Danh sách ID plugin được phép, không bắt buộc; khi được thiết lập, chỉ các plugin trong danh sách mới đủ điều kiện tải. Các kênh trò chuyện tích hợp đã được cấu hình vẫn có thể kích hoạt plugin đi kèm khi kênh được bật rõ ràng trong cấu hình. Sử dụng tùy chọn này để đảm bảo chỉ dùng các tiện ích mở rộng đã được phê duyệt trong môi trường có kiểm soát.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Danh sách plugin bị chặn`},help:{"v1-4gyt4z-4i":`Danh sách ID plugin bị chặn, không bắt buộc, ngay cả khi chúng có trong danh sách được phép hoặc các đường dẫn. Sử dụng quy tắc chặn để khôi phục khẩn cấp về trạng thái trước đó và chặn hoàn toàn các plugin có rủi ro.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Bật plugin`},help:{"v1-pnygd7-50":`Bật hoặc tắt việc tải plugin/tiện ích mở rộng trên toàn hệ thống khi khởi động và tải lại cấu hình (mặc định: true). Chỉ bật khi việc triển khai của bạn cần đến các chức năng của tiện ích mở rộng.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Các mục plugin`},help:{"v1-cn74rf-54":`Cài đặt riêng cho từng plugin, lấy ID plugin làm khóa, bao gồm trạng thái bật và dữ liệu cấu hình thời gian chạy riêng của plugin. Sử dụng mục này để tinh chỉnh từng plugin mà không thay đổi chính sách tải toàn hệ thống.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Khóa API của plugin`},help:{"v1-ctytg2-53":`Trường khóa API không bắt buộc, được sử dụng bởi các plugin hỗ trợ cấu hình khóa trực tiếp trong cài đặt mục. Sử dụng cơ chế thay thế bằng bí mật/biến môi trường và tránh đưa thông tin xác thực thật vào các tệp cấu hình được lưu trong kho mã nguồn.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Cấu hình plugin`},help:{"v1-1he672p-51":`Dữ liệu cấu hình do plugin định nghĩa, được diễn giải theo lược đồ và quy tắc xác thực riêng của plugin đó. Chỉ sử dụng các trường được nêu trong tài liệu của plugin để tránh cài đặt bị bỏ qua hoặc không hợp lệ.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Bật plugin`},help:{"v1-12soc0h-9a":`Ghi đè trạng thái bật cho một mục plugin cụ thể, được áp dụng trên chính sách plugin toàn cục. Với chế độ tải lại kết hợp mặc định, các thay đổi sẽ tải lại nóng môi trường chạy plugin cho các lượt tác nhân mới mà không cần khởi động lại Gateway, trừ khi plugin yêu cầu khởi động lại cho đường dẫn này. Dùng tùy chọn này để triển khai plugin từng bước trên các môi trường.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Biến môi trường của plugin`},help:{"v1-p39pu4-52":`Ánh xạ biến môi trường riêng cho từng plugin, chỉ được đưa vào ngữ cảnh chạy của plugin đó. Dùng tùy chọn này để giới hạn thông tin xác thực nhà cung cấp trong một plugin thay vì dùng chung môi trường tiến trình toàn cục.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Chính sách hook của plugin`},help:{"v1-1oslnrf-4c":`Các tùy chọn kiểm soát chính sách hook có định kiểu cho từng plugin, dành cho các chốt kiểm soát an toàn do hệ thống lõi thực thi. Dùng tùy chọn này để hạn chế các nhóm hook có tác động lớn mà không tắt toàn bộ plugin.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Cho phép hook truy cập cuộc trò chuyện`},help:{"v1-xqz31z-7e":"Kiểm soát việc plugin này có được phép đọc nội dung cuộc trò chuyện thô từ các hook có định kiểu như `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` và `agent_end` hay không. Các plugin không đi kèm sẵn phải chủ động bật quyền này."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Cho phép hook chèn lời nhắc`},help:{"v1-7y6cny-32":"Kiểm soát việc plugin này có được phép sửa đổi lời nhắc thông qua các hook có định kiểu hay không. Đặt thành false để chặn `before_prompt_build`."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Thời gian chờ hook của plugin (ms)`},help:{"v1-4ra6b7-74":`Thời gian chờ mặc định tính bằng mili giây cho các hook có định kiểu của plugin này, tối đa là 600000. Khi không được đặt, mỗi hook sử dụng thời gian chờ do plugin khai báo hoặc chính sách theo từng hook của Gateway; không có một giá trị mặc định cố định chung. Các giá trị theo từng hook trong hooks.timeouts được ưu tiên.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Ghi đè thời gian chờ hook của plugin`},help:{"v1-yphl9b-5s":`Các giá trị ghi đè thời gian chờ cho từng hook tính bằng mili giây, với khóa là tên hook có kiểu, tối đa là 600000. Chỉ ghi đè cho các hook đã biết là chạy chậm như before_prompt_build hoặc agent_end thay vì tăng thời gian chờ cho mọi hook.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Chính sách LLM của plugin`},help:{"v1-dlca6c-4j":`Các tùy chọn kiểm soát api.runtime.llm.complete theo từng plugin về mức độ tin cậy khi ghi đè mô hình và tác tử. Để trống thiết lập này trừ khi plugin cần chủ động điều hướng các lệnh gọi hoàn tất do hệ thống chủ quản lý.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Cho phép plugin ghi đè tác tử LLM`},help:{"v1-k8c08b-4n":`Cho phép rõ ràng plugin này yêu cầu api.runtime.llm.complete với ID tác tử không phải mặc định. Giữ giá trị false trừ khi plugin được tin cậy để truy cập mô hình giữa các tác tử.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Cho phép plugin ghi đè hồ sơ xác thực LLM`},help:{"v1-9ityw9-4x":`Cho phép plugin này chọn hồ sơ xác thực không phải mặc định cho các yêu cầu hoàn tất trong môi trường thực thi tác tử biệt lập. Giữ giá trị false trừ khi plugin được tin cậy để chủ động định tuyến thông tin xác thực biệt lập.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Các mô hình hoàn tất LLM được phép dùng cho plugin`},help:{"v1-1ul08he-54":`Các mô hình đích được phép cho mọi lần hoàn thành văn bản bằng LLM của plugin, dưới dạng tham chiếu chuẩn "provider/model", bao gồm các giá trị mặc định do hệ thống chủ xác định và các giá trị ghi đè. Chỉ dùng "*" khi bạn chủ ý cho phép mọi mô hình.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Các mô hình LLM được phép cho plugin`},help:{"v1-154sk45-47":`Các mô hình đích được phép ghi đè cho các lệnh gọi LLM của plugin đáng tin cậy, dưới dạng tham chiếu chuẩn "provider/model". Chỉ dùng "*" khi bạn chủ ý cho phép ghi đè bằng bất kỳ mô hình nào.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Cho phép plugin ghi đè mô hình LLM`},help:{"v1-uw4jmc-47":`Cho phép rõ ràng plugin này yêu cầu ghi đè mô hình trong api.runtime.llm.complete. Giữ giá trị false trừ khi plugin được tin cậy để quyết định việc chọn mô hình.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Chính sách tác tử phụ của plugin`},help:{"v1-wbf4m1-4d":`Các thiết lập kiểm soát thời gian chạy của tác tử phụ cho từng plugin, bao gồm độ tin cậy khi ghi đè mô hình và danh sách cho phép. Để trống thiết lập này trừ khi plugin cần trực tiếp quyết định việc chọn mô hình cho tác tử phụ.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Các mô hình được phép cho tác tử phụ của plugin`},help:{"v1-2pvkow-42":`Các mô hình đích được phép ghi đè cho các lần chạy tác tử phụ của plugin đáng tin cậy, dưới dạng tham chiếu chuẩn "provider/model". Chỉ dùng "*" khi bạn chủ ý cho phép mọi mô hình.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Cho phép plugin ghi đè mô hình tác tử phụ`},help:{"v1-1r5tzm1-4g":`Cho phép rõ ràng plugin này yêu cầu ghi đè nhà cung cấp/mô hình trong các lượt chạy tác tử phụ ở chế độ nền. Giữ giá trị false trừ khi plugin được tin cậy để quyết định việc chọn mô hình.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Trình nạp plugin`},help:{"v1-1myjwbi-52":`Nhóm cấu hình trình nạp plugin để chỉ định các đường dẫn trong hệ thống tệp nơi plugin được tìm kiếm. Chỉ dùng các đường dẫn nạp được chỉ định rõ ràng và đã được kiểm tra để tránh vô tình nạp tiện ích mở rộng không đáng tin cậy.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Đường dẫn nạp plugin`},help:{"v1-o689p1-4z":`Các tệp hoặc thư mục plugin bổ sung được trình nạp quét ngoài các vị trí mặc định tích hợp sẵn. Sử dụng thư mục riêng cho tiện ích mở rộng và tránh các đường dẫn có phạm vi rộng chứa nội dung thực thi không liên quan.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Vị trí plugin`},help:{"v1-zx6crl-5f":`Chọn plugin sở hữu các vị trí độc quyền khi chạy, chẳng hạn như bộ nhớ, để chỉ một plugin cung cấp chức năng đó. Chỉ định rõ plugin sở hữu từng vị trí để tránh các thành phần cung cấp chức năng chồng chéo với hành vi xung đột.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Plugin bộ máy ngữ cảnh`},help:{"v1-4v13iw-2t":`Chọn plugin bộ máy ngữ cảnh đang hoạt động theo id để một plugin đảm nhiệm việc điều phối ngữ cảnh.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Plugin bộ nhớ`},help:{"v1-80ngcl-23":`Chọn plugin bộ nhớ đang hoạt động theo id hoặc "none" để tắt các plugin bộ nhớ.`}},presence:{label:{"v1-10fdwo4-8":`Trạng thái hiện diện`}},proxy:{label:{"v1-ji57pa-d":`Proxy được quản lý`},help:{"v1-vui6bx-58":`Định tuyến qua proxy chuyển tiếp do người vận hành quản lý cho lưu lượng HTTP, HTTPS, WebSocket và các đường truyền ra ngoài dạng thô được hỗ trợ khi OpenClaw chạy. Sử dụng khi việc kiểm soát tập trung lưu lượng ra ngoài thuộc phạm vi triển khai.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Bật proxy được quản lý`},help:{"v1-1456xdw-49":`Ghi đè tường minh chế độ proxy được quản lý. Khi có URL, tính năng định tuyến được bật theo mặc định; đặt thành false để bỏ qua các URL proxy đã cấu hình hoặc được đặt qua biến môi trường mà không xóa chúng.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Chế độ loopback của proxy được quản lý`},help:{"v1-1kaiuh0-3c":`Kiểm soát việc định tuyến mặt phẳng điều khiển qua loopback của Gateway khi chế độ proxy được quản lý đang hoạt động: "gateway-only", "proxy" hoặc "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL proxy được quản lý`},help:{"v1-p36b5l-3v":`URL proxy chuyển tiếp được quản lý. Dùng http:// cho proxy CONNECT thông thường hoặc https:// khi chính kết nối đến điểm cuối proxy phải sử dụng TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS của proxy được quản lý`},help:{"v1-6i0vu-3q":`Các cài đặt TLS được dùng khi kết nối đến điểm cuối proxy được quản lý. Các cài đặt này áp dụng cho TLS của proxy, không phải TLS của đích sau CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Tệp CA TLS của proxy được quản lý`},help:{"v1-1ntzjia-2p":`Đường dẫn trong hệ thống tệp đến bộ chứng chỉ CA tùy chỉnh dùng để xác minh chứng chỉ của điểm cuối proxy HTTPS được quản lý.`}},secrets:{label:{"v1-1sihgpy-7":`Thông tin bí mật`},help:{"v1-jgn0o9-2l":`Các nhà cung cấp tham chiếu bí mật, hành vi của kho lưu trữ dùng chung và cơ chế bảo vệ lưu lượng đi ra tùy chọn cho tiến trình con.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Proxy lưu lượng đi ra cho bí mật`},help:{"v1-1qfgid-4n":`Proxy loopback do Gateway sở hữu, chỉ thay thế các dấu giữ chỗ bí mật trong kho lưu trữ dùng chung tại thời điểm gửi yêu cầu ra ngoài. Khởi động lại Gateway sau khi thay đổi phần cấu hình chỉ được áp dụng lúc khởi động này.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Các máy chủ được phép của proxy lưu lượng đi ra cho bí mật`},help:{"v1-9ypodl-6t":`Danh sách cho phép lưu lượng tùy chọn dành cho các yêu cầu và đường hầm CONNECT. Khi được thiết lập, đích đến phải có trong danh sách này, trong liên kết máy chủ của từng bí mật hoặc trong bypassHosts. Danh sách trống chỉ cho phép các máy chủ đã được liên kết hoặc được bỏ qua. Khởi động lại Gateway sau khi thay đổi.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Máy chủ bỏ qua proxy đầu ra cho bí mật`},help:{"v1-1oiiomv-57":`Tên máy chủ chính xác sử dụng đường hầm CONNECT chuyển tiếp mù có xác thực cho các ứng dụng khách ghim chứng chỉ. Các giá trị sentinel vẫn ở dạng bản mã và sẽ không vượt qua xác thực của nhà cung cấp, thay vì làm lộ bản rõ.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Bật proxy đầu ra cho bí mật`},help:{"v1-u99b1i-2h":`Bật thay thế bí mật trong lưu lượng đầu ra cho các tiến trình con của tác nhân do Gateway lưu trú. Mặc định: false.`}},session:{label:{"v1-8yh9jr-7":`Phiên`},help:{"v1-j86s32-5d":`Các tùy chọn kiểm soát toàn cục về định tuyến phiên, đặt lại, chính sách phân phối và bảo trì để quản lý cách xử lý lịch sử hội thoại. Giữ nguyên giá trị mặc định trừ khi bạn cần các ràng buộc chặt chẽ hơn về cách ly, lưu giữ hoặc phân phối.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Phạm vi phiên tin nhắn trực tiếp`},help:{"v1-ql362c-5l":`Phạm vi phiên tin nhắn trực tiếp: "main" duy trì tính liên tục, còn "per-peer", "per-channel-peer" và "per-account-channel-peer" tăng mức độ cách ly. Sử dụng các chế độ cách ly cho hộp thư dùng chung hoặc triển khai nhiều tài khoản.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Phạm vi phiên nhóm`},help:{"v1-1fdezx2-6i":`Phạm vi phiên nhóm/kênh: "per-group" giữ các phòng tách biệt trong khi phiên chính của tác nhân theo dõi chúng ở chế độ nền, độc lập với dmScope; "main" gộp ngữ cảnh của phòng vào main và không cần theo dõi. Chỉ sử dụng "main" cho các phòng đáng tin cậy.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Liên kết danh tính phiên`},help:{"v1-1y5jnsm-5n":`Ánh xạ danh tính chuẩn sang ID của người dùng có tiền tố nhà cung cấp để cùng một người dùng được quy về một luồng tin nhắn trực tiếp (ví dụ: telegram:123456). Sử dụng khi cùng một người xuất hiện trên nhiều kênh hoặc tài khoản.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Khóa phiên chính`},help:{"v1-18p638h-3q":`Được chấp nhận nhưng bị bỏ qua: hậu tố phiên chính của mỗi tác tử luôn là "main". Hãy bỏ trường này; phạm vi phiên toàn cục sử dụng "global" thay thế.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Bảo trì phiên`},help:{"v1-imr441-66":`Các tùy chọn bảo trì tự động kho lưu trữ phiên, bao gồm lưu trữ phiên trên bảng điều khiển, thời hạn dọn bỏ, giới hạn số mục, thời gian giữ bản lưu trữ sau khi đặt lại và dọn dẹp theo hạn mức dung lượng đĩa. Bắt đầu ở chế độ warn để quan sát tác động, sau đó chuyển sang enforce khi đã tinh chỉnh các ngưỡng.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Lưu trữ phiên không hoạt động trên bảng điều khiển sau`},help:{"v1-1frdtub-5n":"Lưu trữ các phiên không hoạt động trên bảng điều khiển sau khoảng thời gian này (ví dụ: `7d`) để chúng vẫn có thể truy cập mà không làm đầy danh sách phiên đang hoạt động. Đặt thành `false` hoặc `0` để tắt tính năng tự động lưu trữ phiên trên bảng điều khiển."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Kho lưu trữ lạnh bản ghi`},help:{"v1-1kp9s9h-5s":`Chuyển các bản ghi không hoạt động vào tệp lưu trữ JSONL nén, đồng thời giữ lại siêu dữ liệu phiên. Các tệp lưu trữ trở thành lịch sử bắt buộc và phải được đưa vào bản sao lưu. Thay đổi được áp dụng mà không cần khởi động lại Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Số ngày không hoạt động trước khi lưu trữ`},help:{"v1-zay1q3-5b":`Lưu trữ bản ghi sau số ngày không hoạt động này (số nguyên dương, mặc định là 30). Công việc đang hoạt động được bảo vệ; thay đổi ngưỡng có hiệu lực trong lượt xử lý nền tiếp theo mà không cần khởi động lại Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Tự động lưu trữ bản ghi cũ`},help:{"v1-6p6vmb-5a":`Bật tính năng lưu trữ bản ghi hội thoại trong nền (mặc định là false). Một tiến trình nền kiểm tra các bản ghi hội thoại đủ điều kiện mỗi phút. Chính sách lưu trữ được thiết lập rõ ràng này tách biệt với việc xóa và dọn dẹp theo giới hạn dung lượng đĩa.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Ngưỡng dung lượng đĩa mục tiêu của phiên`},help:{"v1-143vh09-7z":`Dung lượng mục tiêu sau khi dọn dẹp theo hạn mức đĩa (ngưỡng cao). Mặc định là 80% của maxDiskBytes; đặt giá trị cụ thể để kiểm soát chặt chẽ hơn việc thu hồi dung lượng trên đĩa có dung lượng hạn chế. Giá trị được quy đổi thành 0 sẽ dùng giá trị mặc định; giá trị âm không hợp lệ. Để tắt hạn mức, hãy dùng maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Hạn mức dung lượng đĩa tối đa của phiên`},help:{"v1-147lxk3-cj":'Hạn mức dung lượng đĩa vật lý cho mỗi tác tử, bao gồm tệp chính/WAL của SQLite và các tệp trong thư mục phiên được tính vào hạn mức (ví dụ: `500mb`). Mặc định là `10gb`; dữ liệu được bảo vệ có thể khiến mức sử dụng vượt mục tiêu. Khi vượt hạn mức, chế độ warn báo cáo tình trạng thiếu dung lượng, còn chế độ enforce lần lượt xóa các tệp cũ từ thao tác đặt lại/xóa, lịch sử không được tham chiếu, rồi đến các bản lưu trữ được tạo do giới hạn số lượng. Các bản lưu trữ thủ công, theo chính sách lưu giữ dựa trên tuổi, từ bảng điều khiển, để khôi phục và từ phiên bản cũ vẫn được bảo vệ. Đặt thành `false`, `0` hoặc `"0"` để tắt.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Số mục phiên tối đa`},help:{"v1-1w2egrh-7u":`Giới hạn số mục phiên chưa được lưu trữ (mặc định là 5000). Các cuộc hội thoại cần lưu giữ lâu dài, đủ điều kiện và vượt giới hạn sẽ được lưu trữ cùng lịch sử; các mục tự động hóa không cần giữ lại sẽ bị xóa. Các bản lưu trữ hiện có không được tính vào giới hạn. Các mục đang hoạt động được bảo vệ vẫn được tính và có thể khiến kho dữ liệu vượt giới hạn.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Chế độ bảo trì phiên`},help:{"v1-bq39hk-6v":`Xác định xem các chính sách cắt tỉa và giới hạn dung lượng đĩa chỉ được báo cáo ("warn") hay được thực thi ("enforce"). Giữ "warn" trong quá trình triển khai và chuyển sang "enforce" sau khi xác nhận các ngưỡng an toàn. Lưu trữ lạnh có thiết lập enabled riêng, cần được đặt rõ ràng.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Giữ lại các phiên gần đây`},help:{"v1-138q5wx-89":"Bảo vệ các phiên tương tác có hoạt động trong khoảng thời gian này (ví dụ: `7d`) khỏi việc tự động loại bỏ lịch sử theo tuổi, số lượng và hạn mức dung lượng đĩa. Không đặt hoặc đặt thành `false` sẽ giữ chính sách thông thường là xử lý mục cũ nhất trước. Các bản ghi tổng hợp thuộc model-run, cron, hook, heartbeat, ACP và tác tử phụ vẫn đủ điều kiện được dọn dẹp trong giới hạn."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Thời gian chờ trước khi dọn dẹp phiên`},help:{"v1-1xn50w7-76":"Lưu trữ các cuộc hội thoại lâu dài đủ điều kiện và xóa các mục tự động hóa dùng một lần đã tồn tại lâu hơn khoảng thời gian này (mặc định là `30d`; ví dụ: `12h`). Các cuộc hội thoại được lưu trữ vẫn giữ nguyên lịch sử và có thể được khôi phục; các cuộc hội thoại được bảo vệ hoặc có thể định tuyến vẫn hoạt động."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Thời gian giữ bản lưu trữ khi đặt lại phiên`},help:{"v1-16amrs1-7r":"Chính sách giữ bản ghi hội thoại đã lưu trữ theo thời gian tồn tại (`*.reset.<timestamp>` và `*.deleted.<timestamp>`). Theo mặc định, giữ các bản lưu trữ cho đến khi giới hạn dung lượng ổ đĩa buộc phải xóa chúng theo thứ tự cũ nhất trước; đặt một khoảng thời gian (ví dụ: `30d`) để bật tính năng xóa theo thời gian thực đã trôi qua, hoặc đặt `false` để tắt rõ ràng tính năng này."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Thông báo cho Home khi tạo phiên`},help:{"v1-c4prn5-8b":`Đưa thông báo hệ thống vào hàng đợi trong phiên Home của tác nhân sở hữu khi một phiên được tạo (mặc định: true). Thông báo bao gồm tiêu đề và siêu dữ liệu về người tạo nếu có, đồng thời được đọc ở lượt Home hoặc nhịp kiểm tra định kỳ tiếp theo. Đặt thành false để tắt; không áp dụng cho bản nháp, phiên ẩn danh, phiên nội bộ và các lần chạy cron theo lịch.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Chính sách đặt lại phiên`},help:{"v1-1hmt7n3-6r":`Xác định đối tượng chính sách đặt lại mặc định được dùng khi không có thiết lập ghi đè riêng theo loại hoặc kênh. Theo mặc định, các phiên không tự động đặt lại; hãy dùng lịch hằng ngày hoặc lịch theo thời gian không hoạt động để bật tính năng này, còn /new và /reset luôn có thể dùng bất cứ lúc nào.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Giờ đặt lại phiên hằng ngày`},help:{"v1-wry8cv-59":`Đặt mốc giờ địa phương (0-23) cho chế độ đặt lại hằng ngày để các phiên chuyển sang phiên mới vào thời điểm có thể dự đoán. Dùng cùng mode=daily và điều chỉnh theo múi giờ mà người vận hành mong đợi để hành vi của hệ thống dễ hiểu.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Số phút không hoạt động trước khi đặt lại phiên`},help:{"v1-1kzj0id-5e":`Đặt khoảng thời gian không hoạt động trước khi đặt lại trong chế độ theo thời gian không hoạt động, đồng thời có thể đóng vai trò điều kiện bảo vệ bổ sung trong chế độ hằng ngày. Dùng giá trị lớn hơn để duy trì tính liên tục hoặc giá trị nhỏ hơn để có các luồng hội thoại ngắn hạn mới hơn.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Chế độ đặt lại phiên`},help:{"v1-e5ie4w-5b":`Chọn chiến lược đặt lại: "none" tắt tính năng tự động đặt lại (mặc định), "daily" đặt lại vào giờ đã cấu hình và "idle" đặt lại sau một khoảng thời gian không hoạt động. /new và /reset vẫn khả dụng trong mọi chế độ.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Đặt lại phiên theo kênh`},help:{"v1-1uxsulx-5h":`Cung cấp các thiết lập ghi đè việc đặt lại riêng cho từng kênh, với khóa là ID nhà cung cấp/kênh, để kiểm soát hành vi chi tiết. Chỉ sử dụng khi một kênh cần hành vi đặt lại đặc biệt ngoài các chính sách theo loại.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Đặt lại phiên theo loại trò chuyện`},help:{"v1-ypdr7u-52":`Ghi đè hành vi đặt lại theo loại trò chuyện (direct, group, thread) khi các thiết lập mặc định chưa đáp ứng nhu cầu. Sử dụng khi hoạt động trong nhóm/luồng cần tần suất đặt lại khác với tin nhắn trực tiếp.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Đặt lại phiên (Trực tiếp)`},help:{"v1-fjnlp5-56":`Xác định chính sách đặt lại cho các cuộc trò chuyện trực tiếp và thay thế cấu hình session.reset cơ sở cho loại này. Sử dụng thiết lập này làm thiết lập ghi đè chính thức cho tin nhắn trực tiếp thay vì bí danh dm cũ.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Đặt lại phiên (Nhóm)`},help:{"v1-hl1200-4u":`Xác định chính sách đặt lại cho các phiên trò chuyện nhóm, nơi tính liên tục và đặc điểm nhiễu khác với tin nhắn trực tiếp. Sử dụng khoảng thời gian chờ không hoạt động ngắn hơn cho các nhóm sôi động nếu tình trạng lệch ngữ cảnh trở thành vấn đề.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Đặt lại phiên (Luồng)`},help:{"v1-1hgpeke-4w":`Xác định chính sách đặt lại cho các phiên trong phạm vi luồng, bao gồm các quy trình làm việc tập trung trong luồng của kênh. Sử dụng khi phiên luồng cần hết hạn nhanh hơn hoặc chậm hơn các loại trò chuyện khác.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Tác nhân kích hoạt đặt lại phiên`},help:{"v1-rcabsw-5a":`Liệt kê các tác nhân kích hoạt trong tin nhắn buộc đặt lại phiên khi khớp với nội dung đến. Chỉ nên dùng cho các cụm từ đặt lại rõ ràng để tránh mất ngữ cảnh ngoài ý muốn trong cuộc trò chuyện thông thường.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Phạm vi phiên`},help:{"v1-axt4ds-5z":`Đặt chiến lược nhóm phiên cơ bản: "per-sender" tách riêng theo người gửi, còn "global" dùng chung một phiên cho mỗi ngữ cảnh kênh. Giữ "per-sender" để hoạt động an toàn hơn khi có nhiều người dùng, trừ khi bạn chủ đích cần dùng chung ngữ cảnh.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Chính sách gửi giữa các phiên`},help:{"v1-17qpipb-5l":`Kiểm soát quyền gửi giữa các phiên bằng các quy tắc cho phép/từ chối được đánh giá dựa trên channel, chatType và tiền tố khóa. Dùng tùy chọn này để giới hạn nơi các công cụ phiên có thể gửi tin nhắn trong môi trường phức tạp.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Hành động mặc định của chính sách gửi giữa các phiên`},help:{"v1-15plhut-53":`Đặt hành động dự phòng khi không có quy tắc sendPolicy nào khớp: "allow" hoặc "deny". Giữ "allow" cho các thiết lập đơn giản hơn, hoặc chọn "deny" khi bạn yêu cầu quy tắc cho phép rõ ràng cho từng đích đến.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Quy tắc chính sách gửi giữa các phiên`},help:{"v1-o217za-5h":'Các quy tắc cho phép/từ chối được đánh giá theo thứ tự trước hành động mặc định, ví dụ `{ action: "deny", match: { channel: "discord" } }`. Đặt các quy tắc cụ thể nhất lên trước để các quy tắc rộng không che khuất ngoại lệ.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Hành động của quy tắc gửi giữa các phiên`},help:{"v1-178vm80-54":`Xác định quyết định của quy tắc là "allow" hoặc "deny" khi các tiêu chí khớp tương ứng được đáp ứng. Đặt các quy tắc từ chối trước khi thực thi các giới hạn nghiêm ngặt với những ngoại lệ cho phép được chỉ định rõ ràng.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Điều kiện khớp của quy tắc gửi trong phiên`},help:{"v1-18qh5qg-5d":`Xác định các điều kiện khớp tùy chọn của quy tắc, có thể kết hợp các ràng buộc về channel, chatType và tiền tố khóa. Giữ phạm vi khớp hẹp để ý định của chính sách luôn dễ hiểu và việc gỡ lỗi vẫn đơn giản.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Kênh của quy tắc gửi trong phiên`},help:{"v1-u5erwx-50":`Áp dụng quy tắc khi khớp với ID kênh/nhà cung cấp cụ thể (ví dụ: discord, telegram, slack). Dùng tùy chọn này khi một kênh cần cho phép hoặc từ chối gửi độc lập với các kênh khác.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Loại trò chuyện của quy tắc gửi trong phiên`},help:{"v1-7cv4f9-4z":`Áp dụng quy tắc khi khớp với loại trò chuyện (direct, group, thread) để hành vi thay đổi theo hình thức hội thoại. Dùng tùy chọn này khi đích gửi tin nhắn riêng và nhóm cần các giới hạn an toàn khác nhau.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Tiền tố khóa của quy tắc gửi trong phiên`},help:{"v1-ac4dee-5n":`Khớp với tiền tố khóa phiên đã chuẩn hóa sau các bước chuẩn hóa khóa nội bộ trong những thành phần sử dụng chính sách. Dùng tùy chọn này để kiểm soát tiền tố nói chung và ưu tiên rawKeyPrefix khi cần khớp chính xác với toàn bộ khóa.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Tiền tố khóa thô của quy tắc gửi trong phiên`},help:{"v1-1g9w044-5e":`Khớp với tiền tố khóa phiên thô, chưa chuẩn hóa để áp dụng chính sách chính xác theo khóa đầy đủ. Dùng tùy chọn này khi keyPrefix đã chuẩn hóa quá rộng và bạn cần độ chính xác theo tiền tố tác tử hoặc theo phương thức truyền tải.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Chế độ chia sẻ phiên`},help:{"v1-xbh52d-5a":`Kiểm soát những chế độ cộng tác mà chủ sở hữu phiên và quản trị viên có thể chọn. Các giá trị boolean bị bỏ qua mặc định là bật; đặt một chế độ thành false để loại bỏ chế độ đó khỏi bộ chọn và từ chối các lựa chọn mới.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Cho phép phiên nháp`},help:{"v1-1lzap27-2p":`Cho phép chế độ hiển thị nháp, giúp ẩn phiên khỏi những người vận hành không phải chủ sở hữu hoặc quản trị viên. Mặc định: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Cho phép phiên chỉ đọc`},help:{"v1-upl3nu-21":`Cho phép đặt phiên ở chế độ chỉ đọc đối với những người không tham gia. Mặc định: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Cho phép phiên đề xuất`},help:{"v1-4i8owu-4g":`Cho phép chế độ hiển thị đề xuất. Ở giai đoạn này, chế độ này áp dụng cùng chính sách cho phép tham gia như chế độ chỉ đọc; hàng đợi đề xuất sẽ được cấu hình bằng một tính năng ra mắt sau. Mặc định: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Đường dẫn kho lưu trữ phiên`},help:{"v1-hreznz-56":`Đặt đường dẫn tệp lưu trữ phiên dùng để duy trì các bản ghi phiên qua những lần khởi động lại. Chỉ dùng đường dẫn cụ thể khi bạn cần bố cục ổ đĩa tùy chỉnh, định tuyến sao lưu hoặc lưu trữ trên ổ đĩa đã gắn kết.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Liên kết luồng hội thoại của phiên`},help:{"v1-zbzihu-4s":`Các giá trị mặc định dùng chung để tạo và định tuyến phiên gắn với luồng trên các kênh được hỗ trợ. Thiết lập giá trị mặc định toàn cục tại đây và chỉ ghi đè cho từng kênh khi cần hành vi khác.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Ngữ cảnh tạo phiên trong luồng`},help:{"v1-1set6nw-4c":`Ngữ cảnh mặc định của tác tử phụ gốc cho các lần tạo phiên gắn với luồng. Dùng "fork" để bắt đầu từ lịch sử hội thoại của bên yêu cầu hoặc "isolated" để tạo phiên con hoàn toàn mới. Mặc định: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Bật liên kết luồng`},help:{"v1-foomtc-3f":`Công tắc chính toàn cục cho việc tạo, định tuyến và chuyển giao phiên gắn với luồng. Tắt để vô hiệu hóa liên kết luồng trên toàn hệ thống.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Thời gian chờ không hoạt động của liên kết luồng (giờ)`},help:{"v1-gffnx3-3h":`Khoảng thời gian không hoạt động mặc định, tính bằng giờ, cho các phiên gắn với luồng trên các nhà cung cấp/kênh (0 tắt việc hết hạn do không hoạt động). Mặc định: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Thời gian tồn tại tối đa của liên kết luồng (giờ)`},help:{"v1-1xfcyhw-39":`Giới hạn cứng tùy chọn về thời gian tồn tại tối đa, tính bằng giờ, cho các phiên gắn với luồng trên các nhà cung cấp/kênh (0 tắt giới hạn cứng). Mặc định: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Tạo phiên gắn với luồng`},help:{"v1-1lqwbdl-46":`Thiết lập mặc định toàn cục cho phép tạo phiên làm việc gắn với luồng từ sessions_spawn và các lần tạo luồng ACP. Mặc định: true khi liên kết luồng được bật.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Đích liên kết tượng trưng được phép của kỹ năng`},help:{"v1-xzybiq-4t":`Các thư mục gốc đích thực được tin cậy mà liên kết tượng trưng của kỹ năng có thể trỏ tới khi đích nằm ngoài thư mục gốc nguồn đã cấu hình. Hãy giới hạn phạm vi này, chẳng hạn chỉ cho phép thư mục kỹ năng trong kho mã ngang hàng.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Thư mục kỹ năng bổ sung`},help:{"v1-11o7opu-53":`Các thư mục gốc kỹ năng dùng chung bổ sung cần quét với mức ưu tiên thấp nhất. Dùng tùy chọn này cho các kho mã ngang hàng hoặc gói kỹ năng dùng chung cần có sẵn mà không phải sao chép vào không gian làm việc OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Theo dõi Skills`},help:{"v1-1ckr2l5-5d":`Bật tính năng theo dõi hệ thống tệp để phát hiện thay đổi trong định nghĩa kỹ năng, cho phép áp dụng bản cập nhật mà không cần khởi động lại toàn bộ tiến trình. Nên bật trong quy trình phát triển và tắt trong các ảnh triển khai bất biến ở môi trường sản xuất.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Chế độ tự chủ của Skill Workshop`},help:{"v1-1s3kgit-6j":`Điều khiển việc học trong nền: "off" chỉ giữ lời nhắc gợi ý, "propose" tạo các đề xuất chờ xử lý, còn "auto" áp dụng các đề xuất đã ghi nhận và rà soát hằng tuần các kỹ năng do Workshop quản lý thông qua thao tác chỉnh sửa tệp thông thường. Mặc định: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Chính sách bề mặt`},help:{"v1-vgtjbs-50":`Các thiết lập ghi đè chính sách tin nhắn cho từng bề mặt, được lập khóa theo id bề mặt phân phối đã phân giải. Chỉ dùng khi một bề mặt đã triển khai cần xử lý phản hồi im lặng nghiêm ngặt hơn so với mặc định của tác nhân.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Chính sách phản hồi im lặng của bề mặt`},help:{"v1-12zgc3n-60":`Ghi đè chính sách phản hồi im lặng cho một bề mặt phân phối đã phân giải. Các trường chưa đặt sẽ kế thừa agents.defaults.silentReply; hãy dùng id bề mặt có phạm vi hẹp để hành vi nội bộ hoặc dành riêng cho nhóm không ảnh hưởng đến các đích khác.`}},talk:{label:{"v1-15ukbjj-4":`Đàm thoại`},help:{"v1-1gx10xa-5g":`Cài đặt tổng hợp giọng nói ở chế độ Talk, bao gồm đặc trưng giọng nói, lựa chọn mô hình, định dạng đầu ra và hành vi ngắt lời. Sử dụng phần này để tinh chỉnh trải nghiệm giọng nói cho người dùng, đồng thời kiểm soát độ trễ và chi phí.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Tác nhân Talk`},help:{"v1-iee5l9-2b":`Tác nhân sở hữu các phiên Talk được tạo mà không chỉ định rõ khóa phiên thuộc phạm vi tác nhân.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Chế độ nhanh cho tham vấn Talk`},help:{"v1-syf3xk-2o":`Sử dụng tùy chọn này để đặt chế độ nhanh thành true hoặc false cho lượt chạy tác nhân thông thường phục vụ các tham vấn thời gian thực của Talk.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Mức độ suy nghĩ cho tham vấn Talk`},help:{"v1-1ft5njw-2o":`Sử dụng tùy chọn này để ghi đè mức độ suy nghĩ cho lượt chạy tác nhân thông thường phục vụ các tham vấn thời gian thực của Talk.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Ngắt lời Talk khi người dùng nói`},help:{"v1-8n9q4o-3l":`Nếu là true (mặc định), dừng lời nói của trợ lý khi người dùng bắt đầu nói ở chế độ Talk. Giữ tùy chọn này bật để luân phiên lượt nói trong hội thoại.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Nhà cung cấp Talk đang hoạt động`},help:{"v1-wgnxhg-1g":`ID nhà cung cấp Talk đang hoạt động (ví dụ: "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Cài đặt nhà cung cấp Talk`},help:{"v1-oh0yuv-30":`Cài đặt Talk riêng cho từng nhà cung cấp, với ID nhà cung cấp làm khóa. Trong quá trình chuyển đổi, ưu tiên dùng cài đặt này thay cho các khóa talk.* cũ.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Cấu hình nhà cung cấp Talk`},help:{"v1-36pblg-1r":`Các trường cấu hình Talk do nhà cung cấp quy định cho ID nhà cung cấp tương ứng.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Khóa API của nhà cung cấp Talk`},help:{"v1-1a1p9wp-v":`Khóa API của nhà cung cấp cho chế độ Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk thời gian thực`},help:{"v1-c2re7j-3z":`Nhà cung cấp, mô hình, giọng nói, chế độ, phương thức truyền tải và chiến lược suy luận cho Talk thời gian thực. Giữ cấu hình nhà cung cấp giọng nói/TTS trong talk.provider và talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Bộ suy luận Talk thời gian thực`},help:{"v1-opsatw-37":`Chiến lược suy luận của Talk: agent-consult để nhận hỗ trợ từ tác nhân qua Gateway, direct-tools để gọi công cụ cục bộ hoặc none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Định tuyến tham vấn Talk thời gian thực`},help:{"v1-10qjcvk-5f":`Cơ chế chuyển tiếp dự phòng qua Gateway cho bản chép lời hoàn chỉnh của người dùng khi nhà cung cấp thời gian thực bỏ qua openclaw_agent_consult. provider-direct giữ nguyên phản hồi của nhà cung cấp; force-agent-consult định tuyến qua OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Chỉ dẫn Talk thời gian thực`},help:{"v1-1jaaj84-5p":`Các chỉ dẫn hệ thống bổ sung được nối vào câu lệnh nhắc Talk thời gian thực tích hợp sẵn của OpenClaw. Dùng mục này để thiết lập phong cách giọng nói, giọng điệu và các hành vi thời gian thực khác dành cho nhà cung cấp, đồng thời giữ nguyên hướng dẫn agent-consult.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Chế độ Talk thời gian thực`},help:{"v1-1u2xui1-1l":`Chế độ thực thi Talk: realtime, stt-tts hoặc transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Mô hình Talk thời gian thực`},help:{"v1-amou5a-27":`Giá trị ghi đè ID mô hình của nhà cung cấp thời gian thực cho các phiên Talk trên trình duyệt hoặc do Gateway quản lý.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Khoảng đệm đầu Talk thời gian thực (ms)`},help:{"v1-1cwg07n-22":`Số mili giây âm thanh được giữ lại trước khi phát hiện hoạt động giọng nói theo thời gian thực.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Nhà cung cấp Talk thời gian thực`},help:{"v1-wwsmpt-1o":`ID nhà cung cấp giọng nói thời gian thực đang hoạt động, chẳng hạn như openai hoặc google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Cài đặt nhà cung cấp Talk thời gian thực`},help:{"v1-ruagcu-1r":`Cài đặt giọng nói thời gian thực riêng cho từng nhà cung cấp, với khóa là ID nhà cung cấp.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Cấu hình nhà cung cấp Talk thời gian thực`},help:{"v1-edfpxm-1u":`Cấu hình giọng nói thời gian thực do nhà cung cấp quản lý, ứng với ID nhà cung cấp tương ứng.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Khóa API của nhà cung cấp Talk thời gian thực`},help:{"v1-1fbmgpx-z":`Khóa API của nhà cung cấp dùng cho Talk thời gian thực.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Mức độ suy luận của Talk thời gian thực`},help:{"v1-157xd3e-2t":`Mức độ suy luận riêng của nhà cung cấp cho các phiên Talk thời gian thực, chẳng hạn như minimal, low, medium hoặc high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Thời lượng im lặng của Talk thời gian thực (ms)`},help:{"v1-1grnu06-1y":`Số mili giây im lặng trước khi lượt nói của người dùng trong Talk thời gian thực được chốt.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Giọng nói đầu ra của Talk thời gian thực`},help:{"v1-1kgb166-2h":`Tên giọng nói đầu ra dùng để ghi đè giọng nói của nhà cung cấp thời gian thực cho các phiên Talk trên trình duyệt hoặc do Gateway quản lý.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`ID giọng nói đầu ra của Talk thời gian thực`},help:{"v1-1k8w6vk-2f":`ID giọng nói đầu ra dùng để ghi đè giọng nói của nhà cung cấp thời gian thực cho các phiên Talk trên trình duyệt hoặc do Gateway quản lý.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Phương thức truyền tải của Talk thời gian thực`},help:{"v1-2otjgn-2g":`Phương thức truyền byte/phiên của Talk: webrtc, provider-websocket, gateway-relay hoặc managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Ngưỡng VAD thời gian thực của Talk`},help:{"v1-nf5l2t-2j":`Ngưỡng phát hiện hoạt động giọng nói thời gian thực từ 0 (nhạy nhất) đến 1 (ít nhạy nhất).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Thời gian chờ im lặng của Talk (ms)`},help:{"v1-1kim32f-59":`Số mili giây người dùng im lặng trước khi chế độ Talk hoàn tất và gửi bản chép lời hiện tại. Để trống để giữ khoảng dừng mặc định của nền tảng (700 ms trên macOS và Android, 900 ms trên iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Mã ngôn ngữ và khu vực cho giọng nói của Talk`},help:{"v1-1un3x4l-4c":`Mã ngôn ngữ và khu vực BCP 47 dùng cho nhận dạng giọng nói của Talk trên các nút thiết bị và phương án dự phòng bằng giọng nói hệ thống iOS, ví dụ "ru-RU". Để trống để dùng mặc định của từng thiết bị.`}},telemetry:{label:{"v1-sqprmo-9":`Dữ liệu đo từ xa`},help:{"v1-1o5tru3-55":`Sự đồng ý rõ ràng đối với số liệu thống kê tính năng ẩn danh được gửi kèm khi kiểm tra bản cập nhật hằng ngày. Số liệu thống kê tính năng bị tắt theo mặc định và không bao giờ bao gồm tin nhắn, thông tin xác thực hoặc mã định danh.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Dấu thời gian đồng ý với số liệu thống kê tính năng`},help:{"v1-1t051az-3t":`Dấu thời gian ISO ghi lại thời điểm người vận hành chấp nhận hoặc từ chối số liệu thống kê tính năng ẩn danh. Ngăn trình hướng dẫn thiết lập hỏi lại.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Số liệu thống kê tính năng ẩn danh`},help:{"v1-1ptrwuq-4r":`Chia sẻ tên các kênh và nhà cung cấp đã bật, số lượng plugin và số phiên gần đây khi kiểm tra bản cập nhật hằng ngày. Tắt theo mặc định và luôn tắt khi DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Công cụ`},help:{"v1-1el54kl-5h":`Hạ tầng công cụ và các thiết lập mặc định giữa các tác tử. Các mục ngang hàng ở cấp gốc quản lý hạ tầng và các thiết lập mặc định giữa các tác tử; agents.defaults quản lý hành vi vòng lặp tác tử; các mục tác tử có thể ghi đè cả hai loại thiết lập nếu được hỗ trợ.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Quyền truy cập công cụ giữa các tác tử`},help:{"v1-1ynpa5f-cf":`Chính sách cho các lệnh gọi công cụ phiên giữa các tác tử: gửi, liệt kê, xem lịch sử, tìm kiếm và đọc trạng thái (mặc định: bật). Dùng allow để giới hạn các cặp tác tử; enabled=false chặn quyền truy cập thông thường giữa các tác tử. Các phiên tác tử con gốc và phiên con ACP thuộc tác tử yêu cầu vẫn có thể được truy cập khi phạm vi hiển thị là tree hoặc all. Để phân tách nghiêm ngặt, đặt tools.sessions.visibility thành agent hoặc self (tree vẫn cho phép truy cập các phiên con gốc/ACP thuộc tác tử yêu cầu), hoặc dùng các gateway riêng biệt.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Danh sách đích được phép giữa các tác tử`},help:{"v1-1jt2ari-76":`ID tác tử hoặc mẫu * được phép tham gia các lệnh gọi giữa các tác tử; cả tác tử yêu cầu lẫn tác tử đích đều phải khớp. Quyền truy cập giữa các tác tử được bật theo mặc định; nếu bỏ qua hoặc để trống allow, mọi cặp tác tử đều được phép. Đặt danh sách cụ thể để giới hạn quyền truy cập; các mục trống sẽ từ chối quyền truy cập.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Bật công cụ giữa các tác tử`},help:{"v1-w950oq-ba":`Bật quyền truy cập công cụ phiên giữa các tác tử (mặc định: true); nếu bỏ qua hoặc để trống allow, mọi cặp tác tử đều được phép. Đặt thành false để chặn quyền truy cập thông thường giữa các tác tử; các phiên tác tử con gốc và phiên con ACP thuộc tác tử yêu cầu vẫn có thể được truy cập khi phạm vi hiển thị là tree hoặc all. Để phân tách nghiêm ngặt, đặt tools.sessions.visibility thành agent hoặc self (tree vẫn cho phép truy cập các phiên con gốc/ACP thuộc tác tử yêu cầu), hoặc dùng các gateway riêng biệt.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Danh sách công cụ được phép`},help:{"v1-1is3eaq-4v":`Danh sách công cụ được phép tuyệt đối, thay thế các giá trị mặc định từ hồ sơ trong môi trường có yêu cầu nghiêm ngặt. Chỉ dùng tùy chọn này khi bạn chủ ý sử dụng một tập con chức năng công cụ được chọn lọc chặt chẽ.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Mục bổ sung vào danh sách công cụ được phép`},help:{"v1-1xw9zp8-57":`Các mục bổ sung vào danh sách công cụ được phép, được hợp nhất với hồ sơ công cụ đã chọn và chính sách mặc định. Giữ danh sách này ngắn gọn và rõ ràng để quá trình kiểm tra có thể nhanh chóng xác định các ngoại lệ chính sách có chủ đích.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Chính sách công cụ theo nhà cung cấp`},help:{"v1-1ecljob-4y":`Các thiết lập ghi đè cho phép/từ chối công cụ theo từng nhà cung cấp, dùng ID kênh/nhà cung cấp làm khóa để điều chỉnh chức năng theo từng giao diện. Dùng tùy chọn này khi một nhà cung cấp cần được kiểm soát chặt chẽ hơn chính sách công cụ toàn cục.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Chế độ mã`},help:{"v1-1ecc39k-6k":'Chế độ mã OpenClaw tổng quát. Khi không được thiết lập ở cấp toàn cục, mặc định là `"auto"`; một đối tượng được khai báo mà không có `enabled` vẫn ở trạng thái tắt. Các lượt chạy tác nhân có bật chế độ này chỉ cung cấp `exec` và `wait` cho mô hình và truy cập các công cụ thông thường thông qua cầu nối danh mục.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Bật chế độ mã`},help:{"v1-rgstxz-aj":'Kích hoạt chế độ mã OpenClaw ở cấp toàn cục. Nếu hoàn toàn không có thiết lập toàn cục, mặc định là `"auto"`; một đối tượng được khai báo mà không có `enabled` vẫn ở trạng thái tắt. `"auto"` bật chế độ này cho các mô hình ưu tiên danh mục, còn `true` bật cho các lượt chạy có khả năng dùng công cụ. Các thiết lập ghi đè việc kích hoạt ở cấp tác nhân và mô hình được ưu tiên. Nếu môi trường thực thi không khả dụng, lượt chạy có bật chế độ này sẽ dừng để bảo đảm an toàn thay vì cung cấp toàn bộ danh sách công cụ.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Trình thực thi chế độ mã`},help:{"v1-l8nlk2-6x":`Trình thực thi JavaScript: "node" (mặc định) dùng Node vm cho mã đáng tin cậy và không phải là môi trường cô lập bảo mật; "quickjs" dùng plugin QuickJS WASM đi kèm để thực thi mã khách với bảo mật tăng cường. Quyền sử dụng công cụ áp dụng cho cả hai. Nếu thiếu trình thực thi đã chọn, hệ thống sẽ chặn thực thi để bảo đảm an toàn.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Giới hạn đầu ra của chế độ mã`},help:{"v1-1hmij9q-1n":`Số byte tối đa sau khi tuần tự hóa được trả về qua đầu ra của chế độ mã.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Giới hạn lệnh gọi công cụ đang chờ trong chế độ mã`},help:{"v1-3b5tyd-2i":`Số lệnh gọi công cụ lồng nhau đồng thời tối đa mà một máy ảo ở chế độ mã có thể bắt đầu trước khi phải tạm dừng để tiếp tục sau.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Số kết quả tìm kiếm tối đa trong chế độ mã`},help:{"v1-1gpue5r-28":`Số kết quả tìm kiếm tối đa từ danh mục ẩn mà một chương trình ở chế độ mã có thể yêu cầu.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Giới hạn bản chụp trạng thái trong chế độ mã`},help:{"v1-1mmgkqy-1x":`Số byte đã tuần tự hóa tối đa được lưu giữ cho một bản chụp trạng thái QuickJS đang tạm dừng.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Giới hạn bộ nhớ trong chế độ mã`},help:{"v1-xetora-6n":`Giới hạn heap của môi trường khách QuickJS hoặc ngân sách heap V8 cho worker Node theo cơ chế nỗ lực tối đa, tính bằng byte. Chi phí tài nguyên của môi trường chạy Node và mức cấp phát tối thiểu của engine ảnh hưởng đến ngân sách thực tế; không bao gồm bộ đệm bên ngoài và RSS của tiến trình. Đây không phải là biện pháp bảo đảm an toàn.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Giao diện chế độ mã`},help:{"v1-dsp2b9-2x":'Giao diện dành cho mô hình. Chỉ hỗ trợ "only": cung cấp `exec` và `wait` của chế độ mã và ẩn các công cụ thông thường.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Số kết quả tìm kiếm mặc định trong chế độ mã`},help:{"v1-1io42lu-2m":"Số kết quả tìm kiếm mặc định từ danh mục ẩn do `catalog.search` trả về trong chế độ mã."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`Thời gian tồn tại của bản chụp trạng thái trong chế độ mã`},help:{"v1-1nxfczz-28":"Khoảng thời gian có thể tiếp tục các lượt chạy Code Mode đang tạm dừng bằng `wait` trước khi chúng hết hạn."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Thời gian chờ của chế độ mã`},help:{"v1-8csycm-1p":"Số mili giây tối đa cho một lệnh gọi `exec` hoặc `wait` trong chế độ mã."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Danh sách công cụ bị chặn`},help:{"v1-wilr1b-4p":`Danh sách chặn công cụ toàn cục, chặn các công cụ được liệt kê ngay cả khi quy tắc của hồ sơ hoặc nhà cung cấp cho phép chúng. Sử dụng quy tắc chặn để khóa khẩn cấp và phòng thủ nhiều lớp lâu dài.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Quyền truy cập công cụ nâng cao`},help:{"v1-ehcm0r-5a":`Các biện pháp kiểm soát quyền truy cập công cụ nâng cao dành cho những giao diện lệnh đặc quyền mà chỉ người gửi đáng tin cậy mới được truy cập. Giữ ở trạng thái tắt trừ khi quy trình làm việc của người vận hành yêu cầu rõ ràng các thao tác nâng cao.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Quy tắc cho phép dùng công cụ nâng cao`},help:{"v1-1u9bhih-54":`Quy tắc cho phép người gửi sử dụng công cụ nâng cao, thường dùng định dạng định danh của kênh/nhà cung cấp làm khóa. Sử dụng các định danh cụ thể với phạm vi hẹp để người dùng ngoài dự kiến không thể kích hoạt lệnh nâng cao.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Bật quyền truy cập công cụ nâng cao`},help:{"v1-1n8oyal-4l":`Bật luồng thực thi công cụ nâng cao khi vượt qua các bước kiểm tra người gửi và chính sách. Giữ ở trạng thái tắt trong các kênh công khai/dùng chung và chỉ bật trong môi trường đáng tin cậy do chủ sở hữu vận hành.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Công cụ exec`},help:{"v1-p5piic-56":`Nhóm chính sách của công cụ exec dành cho máy chủ thực thi shell, chế độ bảo mật, hành vi phê duyệt và các liên kết lúc chạy. Giữ các giá trị mặc định thận trọng trong môi trường sản xuất và siết chặt các luồng thực thi nâng cao.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Danh sách mô hình được phép dùng apply_patch`},help:{"v1-4q5ovf-1x":`Danh sách ID mô hình được phép, không bắt buộc (ví dụ: "gpt-5.4" hoặc "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Bật apply_patch`},help:{"v1-1erkir4-31":`Bật hoặc tắt apply_patch cho các mô hình OpenAI và OpenAI Codex khi chính sách công cụ cho phép (mặc định: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`Giới hạn apply_patch trong không gian làm việc`},help:{"v1-x2z207-3o":`Giới hạn các đường dẫn apply_patch trong thư mục không gian làm việc (mặc định: true). Đặt thành false để cho phép ghi bên ngoài không gian làm việc (nguy hiểm).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Độ trễ thông báo đang chạy sau khi phê duyệt exec (ms)`},help:{"v1-1gwwann-4z":`Độ trễ tính bằng mili giây trước khi hiển thị thông báo đang chạy sau khi exec được phê duyệt. Tăng để giảm nhấp nháy với các lệnh chạy nhanh, hoặc giảm để người vận hành nhận phản hồi sớm hơn.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Hỏi trước khi thực thi`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Tô sáng lệnh exec`},help:{"v1-kyxd4o-4n":`Hiển thị lệnh được tô sáng dựa trên kết quả phân tích cú pháp trong lời nhắc phê duyệt exec (mặc định: false). Bật tùy chọn này để hiển thị văn bản lệnh được tô sáng mà không thay đổi chính sách phê duyệt exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Thời hạn cấp quyền thường trực (ngày)`},help:{"v1-5uxe2j-6r":`Thời hạn mặc định, tính bằng ngày (1-3650), cho các quyền thường trực được tạo bằng allow-always khi phê duyệt tác vụ tự động hóa. Nếu không đặt, quyền vẫn có hiệu lực cho đến khi bị thu hồi hoặc tác vụ tự động hóa sở hữu quyền thay đổi. Các điều khoản được cố định khi cấp quyền, nên thay đổi này chỉ ảnh hưởng đến các quyền được cấp trong tương lai.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Đích thực thi`},help:{"v1-rno1mf-5q":`Chọn chiến lược xác định đích thực thi cho các lệnh shell. Dùng "auto" để điều chỉnh theo môi trường chạy (sandbox nếu có, nếu không thì dùng gateway), hoặc chỉ định rõ sandbox/gateway/node khi cần một môi trường cố định.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Chế độ thực thi`},help:{"v1-1wi6t4l-5q":`Bộ chọn chính sách thực thi chuẩn hóa. Dùng "auto" để bộ phân loại xét duyệt các trường hợp chưa được phê duyệt, "ask" để con người xét duyệt các trường hợp đó, "allowlist" để chỉ cho phép các lệnh an toàn được xác định sẵn, hoặc "full" cho hoạt động cục bộ đáng tin cậy.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Liên kết nút thực thi`},help:{"v1-rfnz54-4s":`Cấu hình liên kết nút cho công cụ thực thi khi việc thực thi lệnh được ủy quyền qua các nút đã kết nối. Chỉ chỉ định rõ liên kết nút khi cần định tuyến qua nhiều nút.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Thông báo khi kết thúc thực thi`},help:{"v1-1ounlvx-3q":`Khi là true (mặc định), các phiên thực thi nền khi kết thúc và các sự kiện vòng đời thực thi trên nút sẽ đưa một sự kiện hệ thống vào hàng đợi và yêu cầu một nhịp kiểm tra định kỳ.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Thông báo khi thực thi thành công mà không có đầu ra`},help:{"v1-1wx4xxd-3d":`Khi là true, các phiên thực thi nền kết thúc thành công mà không có đầu ra vẫn đưa một sự kiện hệ thống báo hoàn tất vào hàng đợi (mặc định: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Thêm vào đầu PATH khi thực thi`},help:{"v1-s1aimc-1r":`Các thư mục cần thêm vào đầu PATH cho các lần thực thi (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Bên xét duyệt thực thi`},help:{"v1-12y548k-4x":`Bộ xét duyệt thực thi dùng mô hình, được chế độ tự động sử dụng trước khi chuyển sang yêu cầu con người phê duyệt. Cấu hình ghi đè mô hình riêng tại đây nếu bạn muốn tách việc xét duyệt thực thi khỏi mô hình của tác tử chính.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Chế độ nhanh của trình xét duyệt thực thi`},help:{"v1-175bx14-8u":`Chế độ nhanh tùy chọn cho việc xét duyệt phê duyệt của OpenClaw: true yêu cầu xử lý ưu tiên trên các tuyến OpenAI Responses và ChatGPT/OAuth được hỗ trợ; false yêu cầu xử lý tiêu chuẩn. Bỏ qua để giữ nguyên mặc định của nhà cung cấp. Chế độ nhanh có thể tốn nhiều chi phí hơn và phụ thuộc vào khả năng cung cấp của nhà cung cấp. Không cấu hình Codex Guardian tích hợp sẵn.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Mô hình xét duyệt thực thi`},help:{"v1-1lltiy5-3i":`Tùy chọn ghi đè nhà cung cấp/mô hình cho tác tử xét duyệt thực thi. Bỏ qua để dùng lại mô hình chính đã cấu hình cho tác tử đích.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Mức độ suy luận của trình xét duyệt thực thi`},help:{"v1-yg2gby-6u":`Mức độ suy luận tùy chọn cho việc xét duyệt phê duyệt bằng mô hình của OpenClaw: minimal, low, medium, high, xhigh hoặc max. Bỏ qua để giữ nguyên mặc định của nhà cung cấp. Các mức được hỗ trợ sẽ được chuẩn hóa cho mô hình đã chọn. Không cấu hình Codex Guardian tích hợp sẵn.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Thời gian chờ xét duyệt thực thi (ms)`},help:{"v1-1o30chi-3w":`Thời gian chờ của bộ xét duyệt thực thi cho từng giai đoạn chuẩn bị mô hình và tạo phản hồi, tính bằng mili giây, trước khi chuyển sang yêu cầu con người phê duyệt (mặc định: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Hồ sơ tệp thực thi an toàn`},help:{"v1-4cdcwe-29":`Hồ sơ an toàn tùy chọn cho từng tệp thực thi (giới hạn đối số vị trí + cờ được phép/bị cấm).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Tệp thực thi an toàn`},help:{"v1-1of1m2s-21":`Cho phép các tệp thực thi an toàn chỉ nhận đầu vào qua stdin chạy mà không cần mục cho phép rõ ràng trong danh sách.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Thư mục tin cậy cho tệp thực thi an toàn`},help:{"v1-zljbcn-2v":`Các thư mục bổ sung được chỉ định rõ là đáng tin cậy để kiểm tra đường dẫn tệp thực thi an toàn (các mục trong PATH không bao giờ được tự động tin cậy).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Bảo mật thực thi`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Yêu cầu phê duyệt thực thi mã nội tuyến`},help:{"v1-jkmgo7-5z":"Yêu cầu phê duyệt rõ ràng cho các dạng thực thi mã nội tuyến của trình thông dịch như `python -c`, `node -e`, `ruby -e` hoặc `osascript -e`. Ngăn việc âm thầm dùng lại danh sách cho phép và chuyển từ luôn cho phép sang hỏi mỗi lần đối với các dạng này."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Thời gian chờ thực thi (giây)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Công cụ hệ thống tệp chỉ trong không gian làm việc`},help:{"v1-1mhuvka-2s":`Giới hạn các công cụ hệ thống tệp (read/write/edit/apply_patch) trong thư mục không gian làm việc (mặc định: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Danh tính GitHub CLI và tác giả Git`},help:{"v1-1fl77im-5s":`Hồ sơ GitHub CLI cục bộ được quản lý và thông tin tác giả Git tùy chọn cho các công cụ của tác tử. Bỏ qua đối tượng này để giữ nguyên tài khoản và thông tin tác giả gốc của người dùng chạy Gateway; thông tin xác thực kho lưu trữ từ xa không bao giờ bị ghi đè.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Email tác giả Git`},help:{"v1-kol5g6-1i":`Email tùy chọn của tác giả và người tạo commit Git, chỉ áp dụng trong tiến trình.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Tên tác giả Git`},help:{"v1-z5bl1f-1h":`Tên tùy chọn của tác giả và người tạo commit Git, chỉ áp dụng trong tiến trình.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Loại thông tin xác thực GitHub`},help:{"v1-qi3qun-3q":`Đánh dấu hồ sơ OAuth được quản lý có thông tin xác thực làm mới luân phiên do Gateway sở hữu. Các hồ sơ không có trường này sử dụng mã truy cập cá nhân.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Phiên bản hồ sơ GitHub`},help:{"v1-4lzl0-27":`Mã phiên bản hồ sơ được tạo tự động, không mang ý nghĩa có thể diễn giải, dùng để chuyển đổi thông tin xác thực được quản lý theo cách nguyên tử.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Bật tính năng hiểu liên kết`},help:{"v1-23t2io-59":`Bật bước tiền xử lý tự động để hiểu liên kết, cho phép tóm tắt nội dung URL trước khi tác tử suy luận. Giữ tính năng này bật để có ngữ cảnh phong phú hơn và tắt khi cần tuân thủ nghiêm ngặt mức xử lý tối thiểu.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Số liên kết tối đa để phân tích nội dung`},help:{"v1-ksxmcv-52":`Số liên kết tối đa được mở rộng mỗi lượt khi phân tích nội dung liên kết. Dùng giá trị thấp hơn để kiểm soát độ trễ/chi phí trong các luồng trò chuyện nhiều tin nhắn và giá trị cao hơn khi ngữ cảnh từ nhiều liên kết đóng vai trò quan trọng.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Mô hình phân tích nội dung liên kết`},help:{"v1-6j3mnw-5a":`Danh sách mô hình ưu tiên cho các tác vụ phân tích nội dung liên kết, được xét lần lượt làm phương án dự phòng khi được hỗ trợ. Ưu tiên mô hình nhẹ cho tác vụ tóm tắt thông thường và chỉ dùng mô hình nặng hơn khi cần.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Phạm vi phân tích nội dung liên kết`},help:{"v1-183cwpa-55":`Kiểm soát thời điểm chạy phân tích nội dung liên kết dựa trên ngữ cảnh cuộc trò chuyện và loại tin nhắn. Giới hạn phạm vi để tránh truy xuất không cần thiết đối với những tin nhắn có liên kết không cần xử lý.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Thời gian chờ phân tích nội dung liên kết (giây)`},help:{"v1-61v30o-4p":`Giới hạn thời gian phân tích nội dung mỗi liên kết, tính bằng giây, trước khi bỏ qua các liên kết chưa xử lý xong. Đặt giới hạn hợp lý để tránh chờ quá lâu khi các trang bên ngoài phản hồi chậm hoặc không thể truy cập.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Phát hiện vòng lặp gọi công cụ`},help:{"v1-1e3rls8-5g":`Kiểm soát tính năng phát hiện vòng lặp công cụ dựa trên lịch sử gần đây và cơ chế bảo vệ sau khi rút gọn ngữ cảnh. Bỏ qua thiết lập này để giữ tính năng phát hiện theo lịch sử gần đây ở trạng thái tắt và cơ chế bảo vệ sau khi rút gọn ngữ cảnh ở trạng thái bật. Đặt thành true để bật cả hai hoặc false để tắt cả hai.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Chính sách tệp đính kèm cho phân tích nội dung âm thanh`},help:{"v1-1s3t9s5-3o":`Chọn các tệp âm thanh đính kèm phù hợp để xử lý. Chỉ xử lý tệp đầu tiên, trừ khi bạn chủ đích chuyển lời nói thành văn bản cho nhiều tệp đính kèm.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Định dạng hiển thị lại bản chép lời`},help:{"v1-glpdzh-3i":`Định dạng bản chép lời được gửi lại bằng phần giữ chỗ {transcript}. Giữ nguyên phần giữ chỗ để nội dung gửi đi bao gồm bản chép lời.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Gửi lại bản chép lời vào cuộc trò chuyện`},help:{"v1-1dedp8c-3r":`Gửi lại bản chép lời âm thanh vào cuộc trò chuyện gốc trước khi tác nhân xử lý. Bật tùy chọn này khi người dùng cần xác minh nội dung hệ thống đã nghe được.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Bật khả năng hiểu âm thanh`},help:{"v1-1v0x7te-2m":`Bật khả năng hiểu âm thanh để ghi chú giọng nói hoặc đoạn âm thanh có thể được chép thành văn bản làm ngữ cảnh cho tác nhân.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Ngôn ngữ để hiểu âm thanh`},help:{"v1-1ruqt97-3z":`Gợi ý ngôn ngữ mặc định cho các nhà cung cấp dịch vụ chép lời âm thanh. Đặt giá trị này khi đã biết ngôn ngữ nói chính và khả năng nhận diện của nhà cung cấp không đáng tin cậy.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Số byte tối đa để hiểu âm thanh`},help:{"v1-1mcckc8-43":`Giới hạn kích thước đầu vào âm thanh mặc định cho các mô hình đã cấu hình và được tự động phát hiện. Đặt giá trị này theo kích thước bản ghi lớn nhất mà nhà cung cấp và mạng của bạn nên chấp nhận.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Số ký tự tối đa để hiểu âm thanh`},help:{"v1-eo1dp-43":`Độ dài bản chép lời tối đa mặc định cho các mô hình đã cấu hình và được tự động phát hiện. Dùng giá trị thấp hơn để tránh việc ghi chú giọng nói dài làm tăng ngữ cảnh của tác nhân.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Mô hình hiểu âm thanh ưu tiên`},help:{"v1-1n5zya1-3c":`Ưu tiên một mục tools.media.models có gắn thẻ khả năng chép lời âm thanh trước các phương án dự phòng tương thích còn lại.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Lời nhắc phân tích âm thanh`},help:{"v1-1v5jtay-4b":`Lời nhắc chép lời âm thanh mặc định khi mục mô hình không ghi đè lời nhắc này. Giữ chỉ dẫn ổn định khi các quy trình tiếp theo phụ thuộc vào phong cách bản chép lời.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Phạm vi phân tích âm thanh`},help:{"v1-1pptfg0-3w":`Giới hạn việc phân tích âm thanh theo kênh, loại cuộc trò chuyện hoặc khóa nguồn. Giữ phạm vi này hẹp khi việc chép lời tự động có tính nhạy cảm hoặc tốn kém.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Thời gian chờ phân tích âm thanh (giây)`},help:{"v1-n8wc6c-3b":`Thời gian chờ mặc định cho các yêu cầu phân tích âm thanh. Tăng giá trị này đối với bản ghi âm dài hoặc các mô hình chép lời cục bộ chậm hơn.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Số thao tác phân tích đa phương tiện đồng thời`},help:{"v1-13kr9np-58":`Số thao tác phân tích đa phương tiện đồng thời tối đa trong mỗi lượt, tính chung cho các tác vụ hình ảnh, âm thanh và video. Giảm giá trị này trong các môi trường triển khai có tài nguyên hạn chế để tránh quá tải CPU/mạng.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Chính sách tệp đính kèm cho phân tích hình ảnh`},help:{"v1-11hofbw-3e":`Chọn các tệp hình ảnh đính kèm phù hợp sẽ được xử lý. Chỉ xử lý tệp đầu tiên trừ khi chủ đích là phân tích nhiều hình ảnh.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Bật phân tích hình ảnh`},help:{"v1-1b2zw34-50":`Bật tính năng hiểu hình ảnh để diễn giải hình ảnh đính kèm hoặc được tham chiếu thành ngữ cảnh văn bản. Tắt nếu bạn cần chỉ xử lý văn bản hoặc muốn tránh chi phí xử lý hình ảnh.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Số byte tối đa khi hiểu hình ảnh`},help:{"v1-jwwpd1-3v":`Giới hạn kích thước hình ảnh đầu vào mặc định cho các mô hình đã cấu hình và được tự động phát hiện. Đặt giá trị này phù hợp với giới hạn dữ liệu của nhà cung cấp và băng thông của môi trường triển khai.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Số ký tự tối đa khi hiểu hình ảnh`},help:{"v1-ebnxhk-3q":`Độ dài tối đa mặc định của mô tả hình ảnh. Dùng giá trị thấp hơn để ngữ cảnh gọn hơn hoặc giá trị cao hơn để nhận dạng ký tự quang học (OCR) và phân tích cảnh chi tiết hơn.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Mô hình hiểu hình ảnh ưu tiên`},help:{"v1-1o2uwo6-3c":`Ưu tiên một mục tools.media.models được gắn thẻ khả năng hiểu hình ảnh trước các phương án dự phòng tương thích còn lại.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Lời nhắc hiểu hình ảnh`},help:{"v1-1jdcu8b-3u":`Lời nhắc hiểu hình ảnh mặc định khi một mục không ghi đè lời nhắc này. Giữ lời nhắc có tính xác định khi các thành phần sử dụng kết quả cần mô tả ổn định.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Phạm vi hiểu hình ảnh`},help:{"v1-tievo1-3s":`Giới hạn tính năng hiểu hình ảnh theo kênh, loại cuộc trò chuyện hoặc khóa nguồn. Giữ phạm vi hẹp trong các kênh có nhiều hoạt động hoặc không đáng tin cậy để kiểm soát việc xử lý.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Thời gian chờ hiểu hình ảnh (giây)`},help:{"v1-1wcm84x-31":`Thời gian chờ mặc định cho các yêu cầu phân tích hình ảnh. Tăng giá trị này cho hình ảnh lớn hoặc các mô hình thị giác chạy cục bộ chậm hơn.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Các mô hình dùng chung để phân tích nội dung đa phương tiện`},help:{"v1-f34u65-47":`Danh sách chuẩn các mô hình phân tích nội dung đa phương tiện. Gắn thẻ khả năng xử lý hình ảnh, âm thanh hoặc video cho từng mục để mỗi quy trình xử lý chỉ chọn các mô hình dự phòng tương thích.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Chính sách tệp đính kèm cho phân tích video`},help:{"v1-1qm1qrc-3e":`Chọn các tệp video đính kèm phù hợp sẽ được xử lý. Chỉ xử lý tệp đầu tiên trừ khi bạn chủ đích phân tích nhiều video.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Bật phân tích video`},help:{"v1-1ltx5gl-58":`Bật phân tích video để có thể tóm tắt các đoạn video thành văn bản phục vụ việc suy luận và phản hồi ở các bước tiếp theo. Tắt khi việc xử lý video không phù hợp với chính sách hoặc quá tốn kém đối với hệ thống triển khai của bạn.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Số byte tối đa cho phân tích video`},help:{"v1-2mp77v-3v":`Giới hạn kích thước video đầu vào mặc định cho các mô hình đã cấu hình và được tự động phát hiện. Đặt giá trị này phù hợp với giới hạn dung lượng dữ liệu của nhà cung cấp và băng thông của hệ thống triển khai.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Số ký tự tối đa cho phân tích video`},help:{"v1-1j0x40b-3j":`Độ dài tối đa mặc định của phần mô tả video. Dùng giá trị thấp hơn để giữ ngữ cảnh gọn hoặc giá trị cao hơn để có bản tóm tắt cảnh chi tiết.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Mô hình phân tích video ưu tiên`},help:{"v1-1cygq5k-3c":`Ưu tiên một mục tools.media.models được gắn thẻ khả năng để hiểu video trước các phương án dự phòng tương thích còn lại.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Câu lệnh hướng dẫn hiểu video`},help:{"v1-ul2jx4-3r":`Câu lệnh hướng dẫn hiểu video mặc định khi một mục không ghi đè giá trị này. Giữ câu lệnh này nhất quán khi các thành phần sử dụng cần bản tóm tắt ổn định.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Phạm vi hiểu video`},help:{"v1-7gfrx3-3s":`Giới hạn việc hiểu video theo kênh, loại cuộc trò chuyện hoặc khóa nguồn. Giữ phạm vi này hẹp trong các kênh có nhiều hoạt động hoặc không đáng tin cậy để kiểm soát việc xử lý.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Thời gian chờ hiểu video (giây)`},help:{"v1-e8rzsy-33":`Thời gian chờ mặc định cho các yêu cầu hiểu video. Tăng giá trị này cho các đoạn video dài hơn hoặc các mô hình phân tích cục bộ chậm hơn.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Danh sách hành động tin nhắn được phép`},help:{"v1-1iceqwa-5c":`Danh sách hành động tin nhắn được phép trên toàn cục cho công cụ tin nhắn. Chỉ sử dụng khi toàn bộ môi trường thực thi cần cung cấp và chấp nhận một tập hợp hành động rút gọn; ưu tiên danh sách được phép riêng cho từng tác tử đối với các tác tử công khai hoặc chạy trong môi trường cách ly.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Bật gửi tin nhắn hàng loạt`},help:{"v1-1ms74z7-14":`Bật hành động gửi hàng loạt (mặc định: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Cho phép liên ngữ cảnh (giữa các nhà cung cấp)`},help:{"v1-276qxo-2s":`Cho phép gửi tin nhắn giữa các nhà cung cấp khác nhau (mặc định: true). Đặt thành false để chặn gửi tin nhắn giữa các nhà cung cấp.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Cho phép gửi giữa các ngữ cảnh (cùng nhà cung cấp)`},help:{"v1-1sg4x49-1z":`Cho phép gửi đến các kênh khác trong cùng nhà cung cấp (mặc định: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Dấu đánh dấu gửi giữa các ngữ cảnh`},help:{"v1-1fg6jrp-1z":`Thêm dấu đánh dấu nguồn gốc hiển thị khi gửi giữa các ngữ cảnh (mặc định: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Tiền tố dấu đánh dấu gửi giữa các ngữ cảnh`},help:{"v1-eblsru-1p":`Tiền tố văn bản cho dấu đánh dấu gửi giữa các ngữ cảnh (hỗ trợ "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Hậu tố dấu đánh dấu gửi giữa các ngữ cảnh`},help:{"v1-1nk0jub-1p":`Hậu tố văn bản cho dấu đánh dấu gửi giữa các ngữ cảnh (hỗ trợ "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Hồ sơ công cụ`},help:{"v1-h6k98q-5k":`Tên hồ sơ công cụ toàn cục dùng để chọn chính sách công cụ cơ sở được xác định sẵn trước khi áp dụng các thiết lập ghi đè cho phép/từ chối. Dùng mục này để duy trì cấu hình môi trường nhất quán giữa các tác nhân và giữ tên hồ sơ ổn định.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Chính sách công cụ trong môi trường cách ly`},help:{"v1-ea7awo-4k":`Lớp bao chính sách công cụ cho các lần thực thi tác nhân trong môi trường cách ly, giúp các lần chạy này có giới hạn năng lực riêng. Dùng mục này để tăng cường an toàn trong môi trường cách ly.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Chính sách cho phép/từ chối công cụ trong môi trường cách ly`},help:{"v1-ub701o-4t":`Chính sách cho phép/từ chối công cụ được áp dụng khi tác nhân chạy trong môi trường thực thi cách ly. Giới hạn chính sách ở mức tối thiểu để các tác vụ trong môi trường cách ly không thể mở rộng thành những hành động bên ngoài không cần thiết.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Phạm vi hiển thị của công cụ phiên`},help:{"v1-1vtq2rh-c5":`Kiểm soát những phiên mà sessions_list/sessions_history/sessions_search/sessions_send/session_status có thể nhắm đến. ("all" mặc định = mọi phiên trên Gateway, bao gồm cả phiên của các tác nhân và người dùng khác; "agent" = mọi phiên thuộc id tác nhân hiện tại; "self" = chỉ phiên hiện tại; "tree" = phiên hiện tại + các phiên tác nhân phụ được tạo). Quyền truy cập giữa các tác nhân được bật theo mặc định và giới hạn bởi tools.agentToAgent; hãy dùng phạm vi hiển thị hẹp hơn để hạn chế quyền truy cập.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Chính sách công cụ cho tác nhân phụ`},help:{"v1-1xoug01-4z":`Lớp chính sách công cụ dành cho các tác nhân phụ được tạo, cho phép hạn chế hoặc mở rộng tập công cụ khả dụng so với thiết lập mặc định của tác nhân cha. Dùng chính sách này để giới hạn khả năng của tác nhân được giao việc theo mục đích của tác vụ.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Chính sách cho phép/từ chối công cụ của tác nhân phụ`},help:{"v1-7vxsbf-5d":`Chính sách cho phép/từ chối công cụ áp dụng cho môi trường chạy của các tác nhân phụ được tạo. Hãy giữ phạm vi này hẹp hơn phạm vi của tác nhân cha. Các công cụ thuộc tác nhân cha như progress_card luôn bị từ chối, kể cả khi được chỉ định qua allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Nhóm tác tử`},help:{"v1-1q96vvs-45":`Điều phối tác nhân phụ ở chế độ thu thập. Được bật theo mặc định; đặt thành false để tắt. Quyền sử dụng công cụ vẫn áp dụng cho agents_wait và các tùy chọn tạo tác nhân trong swarm.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Tác nhân mặc định của swarm`},help:{"v1-p4alpg-2m":`Tác nhân đích mặc định khi tạo tác nhân trong swarm mà không chỉ định agentId. Danh sách tác nhân phụ được phép vẫn áp dụng.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Bật swarm`},help:{"v1-1nnnrq9-2e":`Bật tác nhân phụ ở chế độ thu thập và agents_wait. Mặc định được bật; đặt thành false để tắt.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Số tiến trình con đang hoạt động trên mỗi nhóm swarm`},help:{"v1-kfx6qp-1c":`Số tiến trình con thu thập đang hoạt động tối đa trên mỗi nhóm swarm.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Số tiến trình con đồng thời của swarm`},help:{"v1-1d46jtm-1s":`Số tiến trình con thu thập chạy đồng thời tối đa trên mỗi nhóm swarm.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Tổng số tiến trình con trên mỗi nhóm swarm`},help:{"v1-1gc9vl1-1e":`Số lần tạo tiến trình thu thập tối đa trong toàn bộ vòng đời của mỗi nhóm swarm.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Thời gian chờ tối đa của swarm`},help:{"v1-bog18y-1g":`Thời gian chờ tối đa mà agents_wait chấp nhận, tính bằng giây.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Tìm kiếm công cụ`},help:{"v1-s0kx04-7y":`Thu gọn các danh mục công cụ lớn của OpenClaw, MCP và ứng dụng khách. Khi chưa được thiết lập, môi trường chạy OpenClaw tự động sử dụng Tool Search có cấu trúc; Code Mode được ưu tiên khi đang hoạt động và Codex sử dụng tính năng tìm kiếm tích hợp riêng. Đặt thành false để tắt, true để dùng cầu nối mã, hoặc dùng dạng đối tượng để chọn chế độ.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Thời gian chờ thực thi mã tìm kiếm công cụ`},help:{"v1-105r499-34":"Số mili giây tối đa cho một lần thực thi `tool_search_code`. Môi trường thực thi giới hạn giá trị trong phạm vi được hỗ trợ 1s..60s."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Bật tìm kiếm công cụ`},help:{"v1-1vm3hfr-4h":"Bật tính năng tìm kiếm công cụ. Khi bật, OpenClaw ẩn các danh mục công cụ lớn sau `tool_search_code` hoặc các công cụ tìm kiếm/mô tả/gọi có cấu trúc trong các lần chạy của môi trường thực thi nhúng."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Số kết quả tìm kiếm công cụ tối đa`},help:{"v1-7du4kh-32":`Số lượng kết quả tìm kiếm công cụ tối đa mà mô hình có thể yêu cầu. Khi chạy, các giá trị được giới hạn trong phạm vi được hỗ trợ 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Giao diện tìm kiếm công cụ`},help:{"v1-jybcbe-7x":'Chọn giao diện dành cho mô hình: "code" cung cấp `tool_search_code`; "tools" cung cấp các công cụ dự phòng có cấu trúc để tìm kiếm/mô tả/gọi; "directory" giữ hiển thị một danh mục công cụ có giới hạn, cung cấp một tập hợp có giới hạn các lược đồ có khả năng cần dùng hoặc bắt buộc, và chỉ cho phép truy cập phần còn lại qua tìm kiếm/mô tả/gọi.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Số kết quả tìm kiếm công cụ mặc định`},help:{"v1-1uchq7t-39":"Số lượng kết quả tìm kiếm công cụ mặc định được trả về khi mô hình không chỉ định giới hạn. Khi chạy, giá trị này được giới hạn ở `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Bật công cụ lập kế hoạch có cấu trúc`},help:{"v1-1xgegme-4o":"Công cụ trạng thái `progress_card` hợp nhất dành cho các kế hoạch được lưu lâu dài và ghi chú diễn giải trong phiên cha. Được bật theo mặc định; đặt thành false để tắt. Luôn không khả dụng với tác tử con."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Công cụ web`},help:{"v1-fpsy5-4y":`Nhóm chính sách công cụ web dùng để điều chỉnh nhà cung cấp dịch vụ tìm kiếm/truy xuất, các giới hạn và hành vi dự phòng. Đảm bảo các cài đặt được bật phù hợp với khóa API hiện có và chính sách kết nối mạng ra ngoài.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL bộ nhớ đệm truy xuất web (phút)`},help:{"v1-1hk89qp-17":`TTL bộ nhớ đệm tính bằng phút cho kết quả web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Bật công cụ truy xuất web`},help:{"v1-yrswld-1f":`Bật công cụ web_fetch (truy xuất HTTP gọn nhẹ).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Tiêu đề yêu cầu tìm nạp web`},help:{"v1-16bjkv5-me":"Các tiêu đề yêu cầu bổ sung được gửi cùng các yêu cầu web_fetch trực tiếp, ví dụ như tiêu đề định tuyến hoặc xác thực Gateway. Mọi giá trị được cấu hình đều được coi là nhạy cảm và được che đi trong cấu hình được hiển thị và dữ liệu ghi lại để gỡ lỗi. Các giá trị là chuỗi thuần văn bản, hỗ trợ phép thay thế ${VAR} và cú pháp thoát ký tự nguyên văn toàn cục $${VAR}, đồng thời được gửi đến các URL do mô hình chọn. Các mục được xác thực khi tạo yêu cầu thay vì khi tải cấu hình, vì vậy tên không hợp lệ hoặc giá trị không thể gửi sẽ bị loại bỏ và ghi nhật ký thay vì vô hiệu hóa tính năng; Accept, Accept-Language, User-Agent và các tiêu đề đóng khung như Transfer-Encoding cũng bị loại bỏ. Dùng tools.web.fetch.userAgent để thay đổi tác nhân người dùng. Chuyển hướng khác nguồn chỉ giữ lại các tiêu đề thuộc danh sách cho phép an toàn của guarded-fetch, và việc thay đổi các tiêu đề thực sự được gửi sẽ phân tách bộ nhớ đệm tìm nạp."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Số ký tự tối đa khi tìm nạp web`},help:{"v1-12d1fw7-1d":`Số ký tự tối đa do web_fetch trả về (phần vượt quá sẽ bị cắt bớt).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Giới hạn cứng về số ký tự khi tìm nạp web`},help:{"v1-cl2mf1-1v":`Giới hạn cứng cho maxChars của web_fetch (áp dụng cho cấu hình và các lệnh gọi công cụ).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Số lần chuyển hướng tối đa khi tìm nạp web`},help:{"v1-t6eak9-1h":`Số lần chuyển hướng tối đa được phép cho web_fetch (mặc định: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Kích thước tải xuống tối đa khi tìm nạp web (byte)`},help:{"v1-q6ld9c-10":`Kích thước tải xuống tối đa trước khi cắt bớt.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Nhà cung cấp dịch vụ tìm nạp web`},help:{"v1-6pb3nv-v":`ID nhà cung cấp dự phòng cho việc lấy nội dung web.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Trích xuất bằng Readability khi lấy nội dung web`},help:{"v1-19exqzx-2c":`Dùng Readability để trích xuất nội dung chính từ HTML (dự phòng bằng cách làm sạch HTML cơ bản).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Chính sách SSRF khi lấy nội dung web`},help:{"v1-qtn7zx-3c":`Các thiết lập ghi đè chính sách SSRF có phạm vi giới hạn cho web_fetch. Hãy giữ phạm vi này hẹp và chỉ bật cho các môi trường proxy mạng cục bộ đã biết.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Tên máy chủ được phép khi lấy nội dung web`},help:{"v1-1j9ctya-35":`Tên máy chủ chính xác hoặc địa chỉ IP cụ thể được phép dùng cho web_fetch, bao gồm cả các đích vốn bị chặn. Hãy giữ danh sách ở mức tối thiểu.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Cho phép dải địa chỉ IPv6 cục bộ duy nhất khi lấy nội dung web`},help:{"v1-1eyz55i-3b":`Cho phép địa chỉ IPv6 cục bộ duy nhất (fc00::/7) để tương thích với các proxy IP giả đáng tin cậy như sing-box, Clash hoặc Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Cho phép dải địa chỉ đo hiệu năng RFC 2544 khi lấy nội dung web`},help:{"v1-u5asdb-2y":`Cho phép các IP thuộc dải đo hiệu năng RFC 2544 (198.18.0.0/15) để tương thích với các proxy IP giả như Clash hoặc Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Tên máy chủ bị chặn khi lấy nội dung web`},help:{"v1-1164vvk-66":`Các mẫu tên máy chủ bị từ chối trước khi phân giải DNS và áp dụng quy tắc cho phép ở mỗi lần chuyển hướng web_fetch. Hỗ trợ tên máy chủ chính xác và "*.example.com" chỉ dành cho tên miền phụ; thêm riêng "example.com" để chặn tên miền gốc. Để trống hoặc không đặt sẽ không thêm quy tắc từ chối nào.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Cho phép truy cập mạng riêng khi lấy dữ liệu web (nguy hiểm)`},help:{"v1-2s6mv7-3t":`Cho phép web_fetch truy cập các đích trong mạng riêng và mạng nội bộ. Giữ ở trạng thái tắt trừ khi các URL do mô hình chọn được tin cậy trong môi trường triển khai này.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Thời gian chờ lấy dữ liệu web (giây)`},help:{"v1-1c3yfr4-16":`Thời gian chờ tính bằng giây cho các yêu cầu web_fetch.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent khi lấy dữ liệu web`},help:{"v1-s7pe8j-1e":`Ghi đè tiêu đề User-Agent cho các yêu cầu web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Proxy môi trường đáng tin cậy khi lấy dữ liệu web`},help:{"v1-1ypkqj7-54":`Định tuyến web_fetch qua proxy HTTP(S) đáng tin cậy được cấu hình bằng biến môi trường và để proxy phân giải DNS. Chỉ bật khi proxy đó do người vận hành kiểm soát và thực thi chính sách kết nối ra ngoài sau khi phân giải DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL bộ nhớ đệm tìm kiếm web (phút)`},help:{"v1-6trzlf-18":`TTL bộ nhớ đệm tính bằng phút cho kết quả web_search.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Bật công cụ tìm kiếm web`},help:{"v1-n1cm4y-27":`Bật web_search được quản lý và tùy chọn tìm kiếm tích hợp sẵn của Codex cho các mô hình đủ điều kiện.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Số kết quả tìm kiếm web tối đa`},help:{"v1-mrw7mi-z":`Số kết quả cần trả về (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Tên miền được phép của Codex`},help:{"v1-1cv4y44-43":`Danh sách tên miền được phép cho web_search gốc của Codex. Trong các lượt tìm kiếm do nền tảng gốc lưu trữ, danh sách này cũng kiểm soát web_fetch được quản lý; các lượt dùng nhà cung cấp được quản lý không thay đổi.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Kích thước ngữ cảnh tìm kiếm Codex`},help:{"v1-antack-1u":`Gợi ý kích thước ngữ cảnh tìm kiếm gốc của Codex: "low", "medium" hoặc "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Bật tìm kiếm web gốc của Codex`},help:{"v1-ek2jzd-1k":`Bật tìm kiếm web gốc của Codex cho các mô hình hỗ trợ Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Chế độ tìm kiếm web Codex`},help:{"v1-1ahyq9f-32":`Tùy chọn tìm kiếm web gốc của Codex: "cached" (mặc định; các lượt Codex không bị hạn chế sẽ chuyển sang "live") hoặc "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Thành phố của người dùng Codex`},help:{"v1-1y95orp-1d":`Thành phố ước tính được gửi đến tính năng tìm kiếm web gốc của Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Quốc gia của người dùng Codex`},help:{"v1-1xkm5ms-1g":`Quốc gia ước tính được gửi đến tính năng tìm kiếm web gốc của Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Khu vực của người dùng Codex`},help:{"v1-lhar02-1l":`Khu vực/tiểu bang gần đúng được gửi đến tính năng tìm kiếm web tích hợp của Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Múi giờ người dùng Codex`},help:{"v1-fgv9fh-1h":`Múi giờ gần đúng được gửi đến tính năng tìm kiếm web tích hợp của Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Nhà cung cấp dịch vụ tìm kiếm web`},help:{"v1-10omglr-1x":`ID nhà cung cấp dịch vụ tìm kiếm. Được tự động phát hiện từ các khóa API có sẵn nếu bỏ qua.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Thời gian chờ tìm kiếm web (giây)`},help:{"v1-i0egvw-17":`Thời gian chờ tính bằng giây cho các yêu cầu web_search.`}},transcripts:{label:{"v1-1iqk6o8-b":`Bản chép lời`},help:{"v1-1i0sc09-66":`Các cài đặt cốt lõi về thu thập bản chép lời cho ghi chú cuộc họp, công cụ tác tử có khả năng ghi âm và các nguồn cuộc họp trực tiếp được cấu hình tự động khởi chạy. Theo mặc định, các plugin cuộc họp lưu ghi chú lâu dài; đặt enabled thành false để tắt trên toàn hệ thống.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Nguồn bản chép lời tự động khởi chạy`},help:{"v1-1mzsl79-5s":`Các nguồn bản chép lời trực tiếp được quản lý tự động kể từ khi gateway khởi động. Mỗi mục được bật khi có trong danh sách; xóa một mục để tắt nguồn đó. Các nguồn thu thập liên tục trừ khi whenOccupied được bật.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`ID tài khoản bản chép lời`},help:{"v1-6g2kjj-4b":`Mã định danh tài khoản nhà cung cấp hoặc không gian làm việc tùy chọn cho các nguồn bản chép lời cần phân biệt tài khoản. Sử dụng định dạng ID tài khoản được nêu trong tài liệu của nhà cung cấp.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`ID kênh bản chép lời`},help:{"v1-1lk9d5o-4u":`ID kênh của nhà cung cấp cho nguồn bản chép lời trực tiếp, chẳng hạn như kênh thoại Discord hoặc kênh trò chuyện nhóm Slack. Xác minh ý nghĩa của ID theo từng nhà cung cấp trước khi bật tính năng tự động khởi động.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`ID máy chủ Discord`},help:{"v1-fyfgnk-4l":`ID máy chủ Discord tùy chọn cho các nguồn bản chép lời từ kênh thoại Discord. Cấu hình giá trị này cùng với channelId tương ứng khi nhà cung cấp cần tra cứu kênh thoại trong phạm vi máy chủ.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`URL cuộc họp cần chép lời`},help:{"v1-1xtt9ci-4f":`URL cuộc họp tùy chọn cho các nhà cung cấp tham gia qua URL thay vì ID kênh. Chỉ sử dụng liên kết cuộc họp đáng tin cậy vì tính năng tự động khởi động có thể tham gia và ghi lại cuộc họp đó.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`ID nhà cung cấp nguồn bản chép lời`},help:{"v1-1uur06p-3s":`ID nhà cung cấp nguồn bản chép lời, chẳng hạn như nhà cung cấp kênh thoại Discord hoặc nhà cung cấp trò chuyện nhóm Slack trong tương lai. Sử dụng đúng ID do plugin của nhà cung cấp cung cấp.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`ID phiên chép lời`},help:{"v1-xyo4x5-5o":`ID phiên chép lời cố định tùy chọn cho nguồn tự động khởi động này. Bị bỏ qua khi whenOccupied là true. Để trống để tạo ID tự động, trừ khi bạn cần một mã chọn ổn định hằng ngày và có thể tránh trùng lặp trong cùng ngày.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Tiêu đề bản chép lời`},help:{"v1-ycjnmp-5y":`Tiêu đề tùy chọn cho các lần ghi bản chép lời trong tương lai. Chỉ thay đổi tiêu đề sẽ giữ các lần ghi hiện tại tiếp tục chạy và không đổi tiêu đề đã được chấp nhận hoặc ghi chú đã lưu của chúng. Các thay đổi khác về nguồn vẫn được xử lý khởi động lại như bình thường.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Ghi bản chép lời khi có người`},help:{"v1-34jid4-78":`Bắt đầu một phiên chép lời mới mỗi khi có người trong nguồn và dừng phiên đó (đồng thời tạo ghi chú) sau khi người cuối cùng rời đi. Yêu cầu nhà cung cấp có khả năng báo cáo sự hiện diện, chẳng hạn như discord-voice. Mặc định: false (ghi liên tục từ khi gateway khởi động).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Bật bản chép lời`},help:{"v1-fyqqr0-6d":`Bật ghi chú cuộc họp tự động được lưu lâu dài, công cụ transcripts của tác tử và các nguồn tự động khởi chạy đã cấu hình. Mặc định: true. Đặt thành false để tắt tính năng lưu trữ lâu dài và công cụ này; chế độ chép lời cuộc họp được chọn rõ ràng vẫn giữ phần nội dung trực tiếp gần nhất trong giới hạn.`}},tts:{label:{"v1-bmxkk9-e":`Chuyển văn bản thành giọng nói`},help:{"v1-1o27tk2-4n":`Chính sách chuyển văn bản thành giọng nói để đọc to câu trả lời của tác tử trên các giao diện giọng nói hoặc âm thanh được hỗ trợ. Giữ ở trạng thái tắt trừ khi việc phát giọng nói là một phần trong quy trình làm việc của người vận hành/người dùng.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Hồ sơ giọng nói TTS`},help:{"v1-1r0opcb-29":`ID hồ sơ giọng nói TTS mặc định. Tùy chọn hồ sơ giọng nói TTS cục bộ có thể ghi đè giá trị này trên từng máy chủ.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Các hồ sơ giọng nói TTS`},help:{"v1-19aybhl-2l":`Các hồ sơ giọng nói TTS có tên, xác định đặc trưng giọng nói nhất quán cùng các liên kết giọng nói riêng cho từng nhà cung cấp.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Hồ sơ giọng nói TTS`},help:{"v1-10s52ah-2l":`Một hồ sơ giọng nói TTS. Sử dụng các liên kết riêng cho từng nhà cung cấp để chỉ định chính xác giọng nói/mô hình và mẫu lời nhắc.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Liên kết nhà cung cấp cho hồ sơ giọng nói TTS`},help:{"v1-993jop-3e":`Các liên kết hồ sơ giọng nói TTS dành riêng cho từng nhà cung cấp, với khóa là ID nhà cung cấp giọng nói. Các liên kết này được hợp nhất và ghi đè lên tts.providers cho hồ sơ giọng nói đang hoạt động.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Cài đặt nhà cung cấp TTS`},help:{"v1-1k80nl4-4y":`Cài đặt TTS dành riêng cho từng nhà cung cấp, với khóa là ID nhà cung cấp giọng nói. Dùng mục này thay cho các khóa cấp cao nhất dành riêng cho nhà cung cấp tích hợp sẵn để các plugin giọng nói không phụ thuộc vào lược đồ cấu hình cốt lõi.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Cấu hình nhà cung cấp TTS`},help:{"v1-dwapva-3d":`Cấu hình TTS dành riêng cho một ID nhà cung cấp giọng nói. Giới hạn các trường trong phạm vi plugin sở hữu nhà cung cấp đó.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Khóa API của nhà cung cấp TTS`},help:{"v1-1m2fj0i-2o":`Khóa API được nhà cung cấp giọng nói đó sử dụng khi plugin của họ yêu cầu xác thực để truy cập TTS.`}},tui:{label:{"v1-c8hus1-b":`Giao diện terminal`},help:{"v1-1fg9vw2-3s":`Cài đặt hiển thị giao diện terminal. Dùng phần này để tùy chỉnh cách trình bày chỉ trong terminal mà không thay đổi hành vi của Gateway hay các giao diện khác.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Chân trang giao diện terminal`},help:{"v1-6e12l3-3k":`Cài đặt hiển thị chân trang giao diện terminal. Giữ thông tin ngữ cảnh tùy chọn gọn gàng để thông tin về phiên, mô hình, mục tiêu và token luôn dễ đọc.`}},ui:{label:{"v1-ye4dff-2":`Giao diện người dùng`},help:{"v1-dt1924-42":`Cài đặt trình bày giao diện cho màu nhấn và tùy chọn hiển thị của người vận hành. Dùng mục này để tùy chỉnh cho dễ đọc mà không thay đổi hành vi khi chạy.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Màu nhấn của người dùng`},help:{"v1-16klzws-4z":`Màu nhấn của Control UI: #RRGGBB để dùng màu tùy chỉnh, hoặc 'theme' để dùng bảng màu của giao diện đã chọn. Ghi đè ui.seamColor; xóa giá trị này để kế thừa màu đường nối đã cấu hình hoặc màu mặc định của giao diện.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Màu nhấn`},help:{"v1-14q3r4h-4g":`Màu nhấn chính được dùng trên các bề mặt giao diện để làm nổi bật, hiển thị huy hiệu và tạo dấu hiệu nhận diện trực quan. Sử dụng các giá trị có độ tương phản cao, đảm bảo dễ đọc ở cả giao diện sáng và tối.`}},update:{label:{"v1-k12u1x-7":`Bản cập nhật`},help:{"v1-11c5k8v-5c":`Hành vi của kênh cập nhật và tính năng kiểm tra khi khởi động để duy trì phiên bản môi trường chạy OpenClaw mới nhất. Sử dụng các kênh ít rủi ro trong môi trường vận hành thực tế và chỉ dùng các kênh mang tính thử nghiệm hơn trong môi trường được kiểm soát.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Bật tự động cập nhật`},help:{"v1-49xs2h-3c":`Bật tự động cập nhật nền cho các bản cài đặt dạng gói thuộc kênh stable và beta; extended-stable không bao giờ tự động áp dụng bản cập nhật (mặc định: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Kênh cập nhật`},help:{"v1-lqtdvf-5b":`Kênh cập nhật cho các bản cài đặt qua git + npm ("stable", "extended-stable", "beta" hoặc "dev"). extended-stable chỉ dành cho bản cài đặt dạng gói: chỉ cài đặt ở chế độ tiền cảnh, với tùy chọn hiển thị gợi ý chỉ đọc khi khởi động.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Kiểm tra cập nhật khi khởi động`},help:{"v1-qy3q9g-5v":`Kiểm tra bản cập nhật khi Gateway khởi động, bao gồm cả thông báo chỉ đọc về extended-stable (mặc định: true). Đặt thành false để tắt việc tự động kiểm tra và áp dụng bản cập nhật cho Gateway và nút không có giao diện, cũng như các yêu cầu kiểm tra cập nhật ẩn danh.`}},voicewake:{label:{"v1-txt1wb-a":`Đánh thức bằng giọng nói`}},web:{label:{"v1-1ae9z56-b":`Kênh web`}},wizard:{label:{"v1-28jonk-h":`Tùy chọn thiết lập`},help:{"v1-14jh6rm-3b":`Các tùy chọn thiết lập do người dùng quản lý. Lịch sử trình hướng dẫn và trạng thái xác nhận do máy quản lý được lưu trong cơ sở dữ liệu trạng thái dùng chung.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Quyền truy cập khám phá khi thiết lập`},help:{"v1-1nqxt0w-38":`Sự đồng ý cho phép dò tìm trong quá trình thiết lập có hướng dẫn: "full" quét mà không hỏi, còn "guarded" hỏi trước khi kiểm tra các ứng dụng cục bộ.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Đề xuất ứng dụng khi thiết lập`},help:{"v1-ub8uoi-30":`Kiểm soát việc quy trình thiết lập có hướng dẫn có được dùng nhãn của các ứng dụng đã cài đặt để đề xuất plugin và kỹ năng phù hợp hay không.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Dấu thời gian lần chạy trình hướng dẫn gần nhất`},help:{"v1-1y0fbk-1k":`Dấu thời gian của lần chạy trình hướng dẫn gần nhất đã lưu thành công.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Lệnh chạy trình hướng dẫn gần nhất`},help:{"v1-x2pfkk-15":`Lệnh đã gọi lần chạy trình hướng dẫn gần nhất.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit của lần chạy trình hướng dẫn gần nhất`},help:{"v1-h0jkmt-1i":`Commit mã nguồn được dùng trong lần chạy trình hướng dẫn gần nhất ở môi trường phát triển.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Chế độ chạy trình hướng dẫn gần nhất`},help:{"v1-16508qy-1r":`Cho biết lần chạy trình hướng dẫn gần nhất nhắm đến thiết lập "local" hay "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Phiên bản của lần chạy trình hướng dẫn gần nhất`},help:{"v1-1tr4z9d-19":`Phiên bản OpenClaw được dùng trong lần chạy trình hướng dẫn gần nhất.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Dấu thời gian xác nhận bảo mật trong trình hướng dẫn`},help:{"v1-86i182-2a":`Dấu thời gian xác nhận bảo mật khi thiết lập, được lưu cùng cấu hình đích.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Tăng tốc worktree`},help:{"v1-9es3gc-4r":`Sử dụng tính năng tăng tốc hệ thống tệp cho các worktree được quản lý mới khi được hỗ trợ (mặc định: true). Đặt thành false để sử dụng thao tác checkout Git và sao chép tệp thông thường. Chỉ áp dụng cho các worktree mới.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Thư mục gốc của worktree`},help:{"v1-1tgti9j-5d":`Thư mục chung cho các worktree được quản lý mới. Dùng đường dẫn tuyệt đối hoặc ~ để chỉ thư mục chính của bạn; mặc định là <state-dir>/worktrees. Các worktree hiện có giữ nguyên đường dẫn đã ghi nhận khi giá trị này thay đổi.`}}}}})))()}export{t as n,n as t};